Object.assign(window.GEN, {"archetipi": [{"id": "custode", "label": "Custode della Pira", "cult": ["resistenti", "celsiani"], "stat": ["Guardia Armata", "Adepto del Culto", "Campione Consacrato"], "chi": ["veglia l'unico fuoco sacro del villaggio da vent'anni, senza mai dormire più di tre ore di fila", "ha ricevuto la Pira a quindici anni, il giorno in cui il vecchio custode ci è caduto dentro", "custodisce una Pira che da qualche mese brucia più bassa, e non ne ha parlato a nessuno", "ha fatto la guerra, e ora alimenta il fuoco con le stesse mani che hanno ucciso", "conosce il nome di ogni morto bruciato sulla Pira, e li recita tutti a ogni alba", "porta ogni notte una brace accesa di casa in casa, perché nessuna soglia resti al buio"], "aspetto": ["sopracciglia bruciate, sguardo che non lascia mai le fiamme", "mani coperte di vecchie ustioni, guanti di cuoio sempre alla cintura", "veste grigio cenere, un ciondolo di brace spenta al collo", "voce roca di fumo, tossisce prima di ogni frase importante", "odore di resina e di capelli bruciati che arriva prima dei suoi passi", "si sfrega le mani davanti al fuoco anche in piena estate"], "vuole": ["un carico di legna benedetta che doveva arrivare tre giorni fa", "che qualcuno vada a vedere perché la Pira del villaggio vicino si è spenta", "un testimone, perché qualcuno ruba le braci di notte", "che i PG lascino le armi fuori dal cerchio del fuoco", "che i PG portino una brace viva a un casolare isolato prima che faccia buio", "che uno dei PG vegli il fuoco stanotte al suo posto, senza chiudere occhio"], "offre": ["una brace consacrata che tiene lontana l'Umbra per una notte", "un posto vicino al fuoco, e nessuna domanda", "il nome di chi ha visitato la Pira prima dei PG", "una benedizione che vale come lasciapassare nel villaggio", "un pugno di cenere della Pira: sparsa su una soglia, tiene fuori i ritornati per una notte", "il permesso di riposare dentro il cerchio, dove le cose della notte non entrano"], "segreto": ["la Pira sta morendo, e la tiene viva col proprio sangue", "una notte ha lasciato fuori dal cerchio una persona che chiedeva aiuto, e la sente ancora bussare", "riceve ordini da una voce nelle fiamme", "non crede più agli dèi; crede solo al fuoco", "per tenere alta la fiamma ci getta le offerte dei fedeli, compreso il cibo dei più poveri", "sa che spegnendo la Pira i morti del villaggio troverebbero pace, e i vivi resterebbero al buio"], "battuta": ["«Il fuoco non chiede chi siete. Io sì.»", "«Fuori dal cerchio nessuno vi sente gridare.»", "«Portate legna o portate guai. Di solito la gente porta guai.»", "«Questa fiamma ha visto morire mia madre. Non vedrà morire me.»", "«Sedetevi. No, non lì: lì si siede chi non torna.»", "«Ogni scintilla che vola via è una preghiera. Stanotte ne volano troppe.»"]}, {"id": "contrabbandiere", "label": "Contrabbandiere", "cult": ["senzaporta", "resistenti"], "stat": ["Bandito dei Coltelli Seghettati", "Ladro Mascherato", "Spia"], "chi": ["sposta merce tra le comunità per strade che sulle mappe non esistono", "vende braci, medicine e notizie a chi paga, a prezzi che cambiano col tempo", "ha un carro col doppio fondo e un mulo che conosce la strada meglio di chiunque", "lavorava per una famiglia potente, finché non ha deciso di lavorare in proprio", "fa passare persone oltre i posti di blocco della milizia, una alla volta, dentro le botti", "tiene i conti di mezza città su un quadernetto scritto in un codice tutto suo"], "aspetto": ["cappotto con troppe tasche, tutte cucite a mano", "un sorriso pronto e un coltello ancora più pronto", "scarpe consumate, anelli nuovi", "una cicatrice sul labbro che rende ogni sorriso storto", "conta le uscite di ogni stanza appena entra, muovendo le labbra", "odore di tabacco dolce e di olio per serrature"], "vuole": ["una scorta per un carico che non deve essere aperto", "che i PG comprino tutta la merce prima che arrivino le guardie", "un diversivo, adesso, mentre esce dalla porta sul retro", "sapere chi ha fatto il suo nome alla milizia", "che qualcuno ritiri un pacco a una dogana dove la sua faccia è fin troppo nota", "che i PG recuperino il suo mulo, sequestrato con tutto il carico al posto di blocco"], "offre": ["una via segreta per entrare o uscire dalla città", "merce rara a metà prezzo, se nessuno chiede da dove viene", "un debito da riscuotere con qualcuno che conta", "una mappa delle pattuglie, aggiornata a ieri", "un posto nascosto nel carro, per chi ha bisogno di sparire", "il nome del funzionario che chiude un occhio, e quanto costa il secondo occhio"], "segreto": ["il carico che sposta stavolta respira", "ha già venduto i PG, o sta per farlo", "è ricercato in un'altra città, sotto un altro nome", "parte dei guadagni va a un orfanotrofio, e lo nega con chiunque", "le medicine che vende sono annacquate, ma senza quei soldi il suo villaggio non mangia", "fa passare il confine anche ai Toccati dall'Umbra, sapendo che alcuni diventeranno pericolosi"], "battuta": ["«Io non vendo niente. Lascio che le cose cambino di mano.»", "«Prezzo pieno per le domande, mezzo prezzo per il silenzio.»", "«Tutti hanno bisogno di qualcosa. Il trucco è arrivare prima.»", "«Se vi fermano, non mi conoscete. Se non vi fermano, mi dovete un favore.»", "«Legale, illegale… Parole da gente che mangia tutti i giorni.»", "«Questa strada non esiste. Quindi non ci siamo mai passati, d'accordo?»"]}, {"id": "studioso", "label": "Studioso dell'Ateneo", "cult": ["celsiani"], "stat": ["Duellante Arcano", "Mago da Battaglia", "Arcimago"], "chi": ["cataloga libri che nessuno legge più, nella certezza che uno di essi salverà il mondo", "studia l'Umbra da vicino, troppo da vicino", "ha perso la cattedra all'Ateneo per una teoria che ora si sta dimostrando vera", "fa da precettore ai figli dei potenti e annota tutto ciò che si dicono", "misura ogni giorno l'altezza delle fiamme della Pira e ne trae previsioni che nessuno vuole sentire", "ricopia a mano i testi del Vecchio Mondo prima che l'umidità se li mangi"], "aspetto": ["occhiali tenuti insieme col filo, dita nere d'inchiostro", "toga elegante ma rammendata cento volte", "una borsa di pergamene che non lascia mai, nemmeno per mangiare", "occhiaie profonde, parla guardando un punto sopra la vostra testa", "corregge la grammatica di chiunque a metà frase, poi chiede scusa", "una bruciatura a forma di mano sulla manica, ancora fresca"], "vuole": ["un libro rimasto in una biblioteca in rovina", "un campione: qualcosa toccato dall'Umbra, vivo se possibile", "protezione, perché qualcuno ha bruciato il suo studio stanotte", "che i PG testimonino davanti al consiglio dell'Ateneo", "il racconto preciso, parola per parola, dell'ultima volta che i PG hanno visto un morto tornare", "una scorta fino a un osservatorio crollato, per guardare il cielo nell'unica notte senza nubi del mese"], "offre": ["la risposta a una domanda che i PG si fanno da tempo", "un incantesimo copiato di nascosto", "l'accesso a un archivio chiuso", "una lettera di presentazione firmata da qualcuno di importante", "la traduzione di un'iscrizione che i PG hanno visto e non capito", "la pianta di un'ala dell'Ateneo che ufficialmente è murata da anni"], "segreto": ["ha falsificato una scoperta per avere fondi", "i suoi appunti descrivono un rito che ha già provato una volta", "lavora in segreto per una famiglia nobile", "ha fatto trapelare la notizia che ha causato il disastro", "ha la prova che l'Umbra si può fermare, ma servono le anime di un intero villaggio", "tiene un morto ritornato chiuso nello scantinato e lo interroga ogni notte: le risposte sono vere"], "battuta": ["«Interessante. Sbagliato, ma interessante.»", "«Lo dicevo dieci anni fa. Allora era eresia, oggi è un'emergenza.»", "«Non toccate niente. Soprattutto quello.»", "«La conoscenza non è pericolosa. Le persone che la usano sì.»", "«Ho una nota a piè di pagina che vi salverà la vita. Forse.»", "«Datemi tre giorni e una candela. No, due candele.»"]}, {"id": "mercenario", "label": "Mercenario stanco", "cult": ["montanari", "resistenti"], "stat": ["Maestro d'Armi", "Soldato Scelto", "Cavaliere del Reame"], "chi": ["combatte da vent'anni per chi paga, e ha perso il conto delle bandiere", "è l'ultima persona ancora in piedi di una compagnia di ventura", "vende la spada per mandare soldi a una famiglia che non vede da anni", "ha accettato di uccidere qualcuno che ora trova simpatico", "addestra le milizie dei villaggi a pagamento, e sa che non basteranno", "porta con sé il libro paga della vecchia compagnia e manda la paga ai figli dei caduti"], "aspetto": ["armatura spaiata, ogni pezzo da un esercito diverso", "un orecchio mancante e nessuna voglia di parlarne", "spalle larghe, passo stanco, occhi svelti", "un nastro colorato legato all'elsa, l'unica cosa che non vende", "si siede sempre con la schiena al muro e la spada sulle ginocchia", "mastica una radice amara per tenere lontano il sonno, e sputa a ogni pausa"], "vuole": ["la paga in anticipo, tutta", "un ingaggio in cui non tocchi uccidere civili, per una volta", "un aiuto per sparire: il suo ultimo committente non accetta dimissioni", "che i PG facciano la guardia al suo sonno, una notte sola", "che i PG mettano una buona parola con un capitano che recluta", "che i PG portino una lettera e la paga alla famiglia di un compagno morto"], "offre": ["la sua spada per tre giorni, poi si ridiscute", "informazioni sulle difese di un campo nemico", "il nome di chi paga qualcuno per seguire i PG", "un trucco di scherma, in cambio di un pasto caldo", "un'armatura in buono stato, tolta a qualcuno che non ne aveva più bisogno", "la parola d'ordine di una compagnia rivale, valida fino a domani"], "segreto": ["ha ricevuto soldi per tenere d'occhio i PG", "ha già tradito un committente, e quel committente è ancora vivo", "ha paura del buio e dorme con una candela accesa", "anni fa ha dato fuoco al villaggio di uno dei PG, eseguendo un ordine", "la sua vecchia compagnia esiste ancora, e cerca chi l'ha abbandonata", "ha in tasca il contratto per uccidere un innocente: se rifiuta, il lavoro passerà a qualcuno di peggio"], "battuta": ["«Le cause giuste pagano poco. Quelle sbagliate pagano in tempo.»", "«Non odio nessuno. È più semplice così.»", "«Pagate, e sarò il vostro cane. Smettete, e sarò quello di un altro.»", "«Ho visto quella bandiera da entrambe le parti del campo.»", "«Il primo giorno si combatte per qualcosa. Dal secondo, per arrivare al terzo.»", "«Svegliatemi solo se sanguina qualcuno. Qualcuno dei nostri.»"]}, {"id": "predicatore", "label": "Predicatore", "cult": ["resistenti", "celsiani"], "stat": ["Cortigiano", "Adepto del Culto", "Sacerdote del Dolore"], "chi": ["predica la fine del mondo in piazza, e ogni giorno ha più ascoltatori", "officia ancora per un dio che non risponde più", "guida un gruppo di fedeli verso una terra promessa che nessuno ha mai visto", "dice di parlare con i morti, e a volte i morti rispondono", "benedice i morti che tornano invece di scacciarli, tra le proteste del villaggio", "va di villaggio in villaggio a raccogliere i nomi degli dèi dimenticati, prima che spariscano del tutto"], "aspetto": ["piedi scalzi coperti di polvere, voce che riempie le strade", "occhi lucidi di fede, mani che tremano", "un simbolo sacro scalpellato via dalla veste", "un seguito di bambini che ripetono le sue parole un attimo dopo", "cita versi sacri e poi li corregge, come se li avesse scritti di persona", "una benda sugli occhi, eppure cammina senza mai inciampare"], "vuole": ["che i PG confessino un peccato davanti a tutti", "protezione per il suo gregge durante il viaggio", "una reliquia rubata al suo tempio", "che qualcuno faccia tacere un predicatore rivale", "che i PG accendano una candela su un altare dall'altra parte del bosco, stanotte", "che i PG assistano a un miracolo stasera, e poi lo raccontino in giro"], "offre": ["occhi e orecchie in tutta la città: i fedeli vedono tutto", "una benedizione che, stranamente, funziona", "un rifugio nel tempio, dove le guardie non entrano", "una profezia che riguarda uno dei PG", "pane della mensa dei poveri e un pagliericcio, in cambio di una preghiera", "una folla: basta un suo cenno e cento persone scendono in strada"], "segreto": ["non crede più a una parola di ciò che predica", "la sua fede viene da qualcosa che non è un dio", "le offerte dei fedeli finiscono a un usuraio", "ha visto il futuro, e lì i PG muoiono", "i miracoli sono trucchi, ma danno ai fedeli la forza di resistere un altro inverno", "sa chi ha avvelenato il pozzo perché ne ha ricevuto la confessione, e non vuole tradirla"], "battuta": ["«Il cielo non tace. Siete voi che non ascoltate.»", "«Pentitevi oggi, che domani ci sarà la fila.»", "«Gli dèi hanno lasciato la porta aperta. Qualcos'altro è entrato.»", "«Non vi chiedo di credere. Vi chiedo di ricordare.»", "«Ogni morto che torna è una domanda. Io provo a rispondere.»", "«Sapete pregare? No? Allora correte. È una preghiera anche quella.»"]}, {"id": "capo", "label": "Capo di una comunità", "cult": ["resistenti", "montanari"], "stat": ["Capo delle Guardie", "Dignitario", "Cavaliere del Reame"], "chi": ["tiene insieme un villaggio con la forza di volontà e poche provviste", "ha ricevuto il comando perché nessun altro lo voleva", "governa una comunità isolata che non si fida di nessuno", "ha preso il comando quando il vecchio capo è sparito nella nebbia", "decide ogni sera, davanti a tutti, chi mangia per primo e chi per ultimo", "tratta da mesi con la comunità vicina per dividere l'unico pozzo della valle"], "aspetto": ["vestiti semplici, una spada troppo bella per un villaggio così", "rughe precoci, voce bassa e ferma", "chiama ogni persona per nome, anche i bambini, anche i cani", "un mantello da cerimonia sopra gli abiti da lavoro", "mani spaccate dal lavoro nei campi e un sigillo d'ottone appeso al collo", "ascolta a occhi chiusi e risponde solo dopo aver contato fino a cinque, a mezza voce"], "vuole": ["che i PG trovino chi svuota le scorte di notte", "un accordo con la comunità vicina, che odia questo villaggio da generazioni", "che i PG se ne vadano prima di attirare guai", "braccia per difendere le mura, almeno fino al raccolto", "che i PG riportino a casa un gruppo di ragazzi partiti a caccia di gloria", "che i PG facciano da giudici in una lite che il villaggio non riesce a risolvere"], "offre": ["ospitalità, cibo e un posto dove riposare in sicurezza", "le chiavi di una cripta che nessuno apre da anni", "rifornimenti e un mulo", "un titolo onorario che apre qualche porta nei villaggi vicini", "una scorta di miliziani fino al passo, purché tornino tutti interi", "il registro delle nascite e delle morti, dove si legge chi è tornato e chi no"], "segreto": ["ha fatto un patto con qualcosa nella foresta per proteggere il villaggio", "il vecchio capo non è sparito: lo ha esiliato di persona", "nasconde un ricercato che somiglia molto a uno dei PG", "le scorte non bastano per l'inverno, e ha già scelto chi lasciare senza", "ha gonfiato il numero degli abitanti per avere più braci dalla città, e l'inganno sta per venire a galla", "ha consegnato ai predoni una famiglia del villaggio in cambio della pace"], "battuta": ["«Qui nessuno fa l'eroe. Siamo solo quelli rimasti.»", "«Avete l'aria di chi porta guai. Restate per cena.»", "«Ogni bocca in più è un rischio. Ogni spada in più è una speranza.»", "«Se fallite, non tornate. Non potrei proteggervi.»", "«Non vi chiedo di amarci. Vi chiedo di non farci ammazzare.»", "«Votiamo. Poi faccio quello che serve, come sempre.»"]}, {"id": "cacciatore", "label": "Cacciatore", "cult": ["resistenti", "elfi", "senzaporta"], "stat": ["Guardia Arciere", "Soldato Silvano", "Cacciatore di Mortali"], "chi": ["caccia bestie mutate per la loro pelle, che vale oro", "conosce la palude meglio di chiunque, e ne ha più paura di chiunque", "insegue da settimane una preda che si muove come una persona", "cerca chi ha ucciso il suo compagno di caccia", "tende trappole attorno al villaggio ogni notte e all'alba conta cosa ci è finito dentro", "addestra cani a fiutare i morti che tornano, prima che arrivino alle case"], "aspetto": ["odore di muschio e sangue secco", "una collana di denti di bestie che non esistono sui libri", "si muove senza fare rumore, anche sul ghiaino", "un occhio lattiginoso e l'altro che non sbaglia mai", "annusa l'aria prima di rispondere a qualsiasi domanda", "il viso dipinto di fango a strisce, anche in città"], "vuole": ["aiuto per abbattere una bestia troppo grande per una persona sola", "che i PG non seguano le tracce appena trovate", "un guaritore per il suo cane, ferito da qualcosa di strano", "compagnia: da tre giorni qualcosa segue le sue orme", "che i PG facciano da esca per una notte, con la promessa di non mancare il colpo", "che i PG recuperino le sue trappole da un territorio dove ora c'è qualcosa di più grosso"], "offre": ["la strada più breve e più sicura attraverso le terre selvagge", "carne fresca e un fuoco ben nascosto", "le sue trappole, e come disinnescarle", "una pelle rara che vale una fortuna in città", "il punto debole della bestia che i PG stanno affrontando, se sanno descriverla bene", "un richiamo di corno che imita un branco in arrivo: utile per far scappare o per attirare"], "segreto": ["la bestia che caccia è sua sorella, trasformata", "ha lasciato morire il suo compagno per salvarsi", "fa da guida a una banda di predoni e indica loro le carovane", "ha l'Umbra nel sangue, e la sente arrivare prima degli altri", "la bestia rara che vuole abbattere è l'ultima della sua specie, e con quella pelle pagherebbe le cure di un figlio", "in un inverno di fame ha mangiato carne di un ritornato, e da allora sogna con gli occhi dei morti"], "battuta": ["«Le tracce non mentono. Chi le lascia sì.»", "«Se senti cantare nella palude, non rispondere.»", "«Non è la bestia più grande a ucciderti. È quella che non vedi.»", "«Camminate dove cammino io. Esattamente dove cammino io.»", "«Silenzio. Non è il vento. Il vento non respira.»", "«Ho mangiato di peggio. Ho dormito accanto a di peggio.»"]}, {"id": "nobile", "label": "Nobile decaduto", "cult": ["celsiani"], "stat": ["Nobile Minore", "Duellante Arcano", "Dignitario"], "chi": ["discende da una casata che governava la regione, e ora possiede un palazzo vuoto", "si comporta come se il mondo non fosse finito", "vende gli argenti di famiglia uno alla volta, di nascosto", "vuole riprendersi ciò che la sua famiglia ha perso, a qualunque costo", "dà un ricevimento ogni settimana in un salone mezzo crollato, e la gente ci va per il cibo", "raccoglie i ritratti salvati dalle case bruciate, anche quelli di famiglie che non conosce"], "aspetto": ["abiti di velluto lisi ai gomiti, portati con orgoglio", "un anello col sigillo di famiglia girato verso il palmo", "profumo costoso sopra l'odore di muffa", "un servitore anziano sempre un passo indietro", "un fazzoletto di pizzo premuto sul naso ogni volta che parla con la gente comune", "denti perfetti, uno d'oro, e un sorriso che li mostra tutti"], "vuole": ["che i PG recuperino un cimelio dalla vecchia tenuta di famiglia", "una scorta a un ballo dove deve fare bella figura", "che i PG favoriscano un matrimonio vantaggioso", "vendetta contro la famiglia che ha rovinato la sua", "che i PG caccino gli occupanti dall'ala est del palazzo, senza fare rumore", "un campione: domani all'alba c'è un duello d'onore, e uno dei PG deve battersi al suo posto"], "offre": ["un titolo, una lettera, un nome che apre porte", "un pezzo del tesoro di famiglia, se lo ritrovano", "pettegolezzi esatti su chiunque conti qualcosa", "alloggio nel palazzo, con stanze che nessuno usa da decenni", "un invito a un ricevimento dove ci saranno tutte le persone che contano", "una spada di famiglia con un nome e una storia, data in prestito"], "segreto": ["è in rovina e deve soldi a persone pericolose", "il titolo che porta non è suo: l'erede vero è morto", "ha venduto la sua famiglia ai nemici per salvarsi", "nel palazzo c'è una stanza chiusa, e qualcosa ci vive dentro", "i suoi antenati sono tornati dalla morte e vivono chiusi nell'ala nord, nutriti con quello che si trova", "la terra che rivendica ospita oggi un villaggio di profughi: riaverla significa cacciarli"], "battuta": ["«Mio nonno avrebbe fatto impiccare gente come voi. Io vi assumo.»", "«Il mondo è finito, ma le buone maniere no.»", "«Non è avidità. È riprendersi ciò che è nostro.»", "«Si paga in oro, si ripaga in sangue. Lo diceva sempre mia madre.»", "«Pulitevi gli stivali. Quel tappeto ha visto due guerre.»", "«Vi pagherò. Non oggi, non in monete, ma vi pagherò.»"]}, {"id": "guaritrice", "label": "Guaritrice", "cult": ["resistenti", "elfi"], "stat": ["Stregone dei Coltelli Seghettati", "Assassino Avvelenatore", "Necrosacerdote Tumulato"], "chi": ["cura chiunque, anche i nemici, e per questo ha molti nemici", "cerca una cura per la piaga che fa tornare i morti", "è l'unica persona che sa ancora fare i rimedi del Vecchio Mondo", "segue i carri dei profughi da un campo all'altro", "fa nascere i bambini di tre villaggi e conosce i segreti di ogni famiglia", "manda avanti un lazzaretto in un vecchio mulino, con più malati che letti"], "aspetto": ["grembiule macchiato, mani che sanno di erbe amare", "una borsa di cuoio piena di boccette tintinnanti", "capelli raccolti con un ago da sutura", "parla piano, come se tutti fossero malati", "assaggia ogni rimedio prima di darlo, con una smorfia", "una maschera a becco piena di lavanda appesa al collo"], "vuole": ["un'erba rara che cresce solo in un posto pericoloso", "che i PG portino un malato contagioso fuori dal villaggio", "sapere cosa ha ucciso un paziente che stava guarendo", "aiuto per curare una persona che il villaggio vuole morta", "che i PG tengano fermo un ferito mentre amputa, adesso, subito", "che i PG trovino chi ruba i suoi rimedi e li rivende a peso d'oro"], "offre": ["cure senza chiedere chi vi ha ferito", "due pozioni di guarigione, preparate stanotte", "rifugio nella sua capanna, dove nessuno entra per paura del contagio", "un infuso che, bevuto prima di dormire, rimuove uno Stress", "l'antidoto per un veleno che i PG ancora non sanno di aver bevuto", "il nome di ogni ferito di coltello curato nell'ultima settimana"], "segreto": ["ha avvelenato qualcuno, una volta, e lo rifarebbe", "sperimenta sui morti per trovare la cura", "uno dei suoi pazienti è un mostro, e lo protegge", "la cura che cerca richiede un sacrificio umano", "lascia morire i malati senza speranza per salvare le medicine per gli altri, e decide senza dirlo a nessuno", "porta in sé la piaga e la tiene a bada con un rimedio che sta finendo"], "battuta": ["«Sdraiati. Fa male, ma meno di quello che hai fatto per procurartela.»", "«Non chiedo chi sei. Chiedo dove ti fa male.»", "«Ogni ferita racconta una storia. La tua è noiosa: cadi spesso?»", "«I morti tornano. I malati, a volte, no.»", "«Mordi questo. Non per il dolore: per non urlare. Ci sentono.»", "«Lavatevi le mani. Gli dèi sono andati via, i vermi no.»"]}, {"id": "senzaporta", "label": "Nomade dei Senzaporta", "cult": ["senzaporta"], "stat": ["Bandito dei Coltelli Seghettati", "Mercante", "Ladro Mascherato"], "chi": ["guida una carovana che non si ferma mai più di tre notti", "combatte a mani nude per soldi nel cerchio dell'accampamento", "legge il futuro nelle ossa, e non sbaglia quanto dovrebbe", "commercia in cavalli, cani e qualunque cosa non sia inchiodata", "porta lettere tra comunità che non si parlano da anni, e le legge tutte", "custodisce la memoria cantata della carovana: centinaia di nomi, in ordine"], "aspetto": ["anelli su ogni dito, uno per ogni affare chiuso", "parla così in fretta che si capisce una parola su tre", "un cappello piumato e stivali fangosi", "cicatrici sulle nocche, sorriso con due denti d'oro", "batte le mani una volta prima di ogni affare, e sputa per terra dopo", "un mantello cucito con le toppe di tutti i villaggi attraversati"], "vuole": ["che i PG combattano nel cerchio, e perdano al terzo round", "il suo cane migliore, rubato stanotte", "un passaggio sicuro attraverso le terre di una milizia", "sapere chi segue la carovana da due giorni", "che i PG tirino fuori un carro dal fango prima che arrivi la tempesta", "che i PG riportino in carovana un giovane scappato per mettere su casa in città"], "offre": ["un posto al fuoco, un bicchiere e storie vere a metà", "cavalli veloci, a un prezzo onesto per i Senzaporta", "notizie dalle strade: chi è passato, chi non è tornato", "protezione: nessuno tocca chi beve con i Senzaporta", "un passaggio in carovana, nascosti tra le stoffe, fino alla prossima regione", "una lettura delle ossa per ciascun PG, con una verità a testa"], "segreto": ["la carovana trasporta qualcosa che i Senzaporta hanno giurato di non toccare", "ha promesso uno dei PG in matrimonio per saldare un vecchio debito", "ha venduto la posizione della carovana a qualcuno", "il cerchio è truccato da anni", "quando la carovana è in pericolo, la legge dei Senzaporta impone di lasciare indietro vecchi e malati, e la fa rispettare", "un bambino della carovana è figlio di una famiglia nobile, comprato in fasce, e ora la famiglia lo cerca"], "battuta": ["«Ti piacciono i cani? Questo morde solo chi mente.»", "«Affare fatto: stringi la mano, sputa per terra.»", "«Noi non abbiamo porte. Per questo nessuno ci chiude fuori.»", "«Tre round. Al terzo vai giù. Capito? Al terzo.»", "«Le strade sono di chi le cammina. Questa, oggi, è nostra.»", "«C'è il prezzo per gli amici e quello per gli stranieri. Voi, cosa siete?»"]}, {"id": "toccato", "label": "Toccato dall'Umbra", "cult": ["resistenti", "sotterranei", "elfi"], "stat": ["Mago dall'Anima Infranta", "Ladro Mascherato", "Spettro Sussurrante"], "chi": ["ha attraversato la tempesta a piedi, e dall'altra parte non è più la stessa persona", "nasconde le vene nere sulle braccia sotto le maniche lunghe", "sente le voci dei morti e prova a ignorarle", "vive in una capanna fuori dal villaggio, dove la gente va solo quando ha bisogno", "dorme di giorno e di notte cammina lungo il confine, contando le ombre", "segna col gesso le porte delle case dove l'Umbra colpirà, e nessuno sa come lo sa"], "aspetto": ["occhi che a volte riflettono una luce che non c'è", "un'ombra che si muove un istante dopo il corpo", "pelle fredda, voce troppo calma", "guanti anche d'estate, e non li toglie nemmeno per mangiare", "si gira a rispondere a qualcuno che non ha parlato", "dove posa le mani, il legno si copre di brina nera"], "vuole": ["una risposta sincera: sta diventando un mostro?", "un posto dove nessuno sappia cosa porta dentro", "che i PG distruggano la cosa nella tempesta che ha lasciato un segno nella sua carne", "una cura, o una fine rapida se la cura non esiste", "che i PG facciano la guardia alla sua porta stanotte e non la aprano, qualunque cosa dica la sua voce", "che i PG trovino il corpo di una persona di cui sente la voce ogni notte, e le diano sepoltura"], "offre": ["un avvertimento: sente arrivare l'Umbra prima di chiunque altro", "una domanda a chi è già stato preso dall'Umbra, e la risposta", "un passaggio che solo i Toccati possono aprire", "il proprio sacrificio, se servirà", "la verità sui sogni che i PG fanno da quando sono qui", "il nome dell'ombra che segue uno dei PG"], "segreto": ["la voce che sente racconta cosa faranno i PG, prima che lo facciano", "ha già fatto del male a qualcuno, senza ricordarlo", "non ha superato la tempesta: è ciò che è tornato al suo posto", "ha trovato un modo per controllare l'Umbra, e lo sta imparando", "il segno nero si può passare a un'altra persona, e ha già scelto a chi", "l'Umbra che porta dentro tiene lontana la tempesta dal villaggio: se guarisce, il villaggio muore"], "battuta": ["«Non avvicinatevi troppo. Non per me. Per voi.»", "«La sentite? No. Certo che no.»", "«Ogni notte sogno lo stesso posto. Stanotte c'eravate anche voi.»", "«Non chiedetemi cosa ho visto. Chiedetemi cosa mi ha visto.»", "«Sta arrivando. Contate fino a cento. Non arriverete a cento.»", "«Ho freddo da tre anni. Ci si abitua a tutto.»"]}, {"id": "oste", "label": "Oste", "cult": ["resistenti", "montanari", "sotterranei"], "stat": ["Mercante", "Picchiatore dei Coltelli Seghettati", "Soldato Scelto"], "chi": ["gestisce l'unica locanda rimasta su questa strada", "sa tutto di tutti e vende le notizie insieme alla birra", "ha trasformato la locanda in una fortezza, con feritoie e sbarre", "ha ereditato la locanda e un debito enorme", "distilla una grappa così forte che la usano anche per accendere le torce", "apparecchia ogni sera un posto per un cliente che non si vede da sette anni"], "aspetto": ["grembiule di cuoio e un randello sotto il bancone", "una risata che si sente dalla strada", "occhi che contano i clienti e le monete allo stesso tempo", "un gatto enorme sempre sulla spalla", "asciuga lo stesso boccale per tutta la conversazione", "un dito mancante e un anello infilato sul moncherino"], "vuole": ["che qualcuno sistemi i clienti che non pagano da una settimana", "un ingrediente per la sua specialità, che vive in una grotta", "che i PG facciano sparire un cadavere trovato in cantina", "notizie fresche, e i PG ne hanno di sicuro", "che i PG sedino una rissa prima che sfasci il bancone nuovo", "che i PG recuperino la botte migliore, rubata da un carro sulla strada"], "offre": ["una stanza, un bagno caldo e un pasto vero", "le voci che girano: chi cerca chi, chi paga cosa", "credito, finché non fate danni", "una porta sul retro che dà su un vicolo nascosto", "un tavolo d'angolo dove incontrare chiunque senza essere visti", "un'occhiata al registro degli ospiti, con nomi veri e nomi falsi"], "segreto": ["la cantina dà su un passaggio dei contrabbandieri", "avvelena i clienti ricchi e prende le loro cose", "ha disertato dall'esercito e ha una taglia sulla testa", "ascolta tutto e lo riferisce a una fazione", "nasconde in una stalla chiusa i morti ritornati della valle: sono parenti dei suoi clienti", "ha pagato qualcuno per far crollare il ponte vecchio, perché i viandanti passino davanti alla sua porta"], "battuta": ["«Qui si beve, si mangia e non si chiede. Chi chiede paga doppio.»", "«Le risse fuori. I morti in cantina. Regola della casa.»", "«Notizie? Ne ho. Sete? Ne avrete.»", "«L'ultimo che ha fatto il furbo è ancora qui. Sotto il pavimento.»", "«Pulite il sangue prima di sedervi. Le sedie sono nuove.»", "«Una zuppa, un letto e un consiglio: non uscite dopo il tramonto. Il consiglio è gratis.»"]}, {"id": "becchino", "label": "Becchino dei ritorni", "cult": ["resistenti"], "stat": ["Teppista Comune", "Necrosacerdote Tumulato", "Arci-Negromante"], "chi": ["scava fosse e, quando qualcuno ne torna fuori, si siede a parlarci finché non si calma", "tiene un registro di chi è tornato dalla tomba, con data, ora e prime parole", "seppellisce i morti a faccia in giù e legati, perché è l'unico metodo che funziona", "conosce ogni morto che torna nel suo cimitero, e i debiti che ha lasciato in sospeso", "riporta i ritornati alle famiglie quando le famiglie li rivogliono, cioè quasi mai", "canta ninnenanne ai morti appena sepolti, perché dormano più a fondo"], "aspetto": ["terra sotto le unghie che non viene più via", "una vanga con il manico pieno di tacche, una per ogni morto rimandato giù", "parla con le pause dei morti: lunghe, e sempre a metà frase", "un campanello legato alla caviglia, così i ritornati sentono che sta arrivando", "odore di calce viva e di fiori secchi", "pranza sulle lapidi e lascia sempre un boccone per chi sta sotto"], "vuole": ["braccia: stanotte tornano in sette, e la fossa comune non tiene", "che i PG ascoltino l'ultima volontà di un ritornato e la portino a termine", "che i PG riportino al cimitero un morto scappato in paese, prima che lo vedano i bambini", "sapere chi dissotterra i morti di notte e dove li porta", "testimoni, perché un ritornato accusa il proprio fratello di averlo ucciso", "una cassa di chiodi benedetti dal villaggio vicino, prima del prossimo funerale"], "offre": ["una conversazione con un morto: le domande sono sue, lo scavo tocca ai PG", "l'elenco di chi è sepolto dove, e con quali oggetti", "un nascondiglio sicuro: nessuno cerca nessuno in una cripta", "il modo per rimandare a riposare un ritornato senza doverlo combattere", "le ultime parole di qualcuno che i PG hanno conosciuto", "un amuleto d'osso che rende i ritornati diffidenti, ma non ostili"], "segreto": ["alcuni ritornati vivono nella cripta, e li sfama all'insaputa del villaggio", "vende i corpi più freschi a uno studioso, che paga bene e non dice a cosa servono", "ha ucciso con le proprie mani uno dei morti sepolti qui, e quel morto sta per tornare", "i ritornati sussurrano chi morirà presto, e vende quei nomi a chi può approfittarne", "custodisce un ritornato mite che chiede solo di rivedere i figli, che lo credono in pace", "il suo nome è inciso su una lapide del cimitero, con una data di vent'anni fa"], "battuta": ["«Non temete i morti. Hanno solo fretta di finire un discorso.»", "«Un metro e ottanta di fondo. Per lui, facciamo due.»", "«Bentornato. No, non è casa tua. Non più.»", "«I vivi mentono sempre. I morti, solo il primo giorno.»", "«Prima scavavo e basta. Adesso devo anche ascoltare.»", "«Sssh. Se fate silenzio, smette di grattare.»"]}, {"id": "cartografo", "label": "Cartografo di strade scomparse", "cult": ["celsiani", "senzaporta"], "stat": ["Schermagliatore", "Spia", "Arcimago"], "chi": ["disegna le strade che l'Umbra ha cancellato, sperando che un giorno ritornino", "percorre ogni mese la stessa valle e la trova ogni volta diversa", "vende mappe di villaggi che non esistono più a chi ci aveva dei parenti", "cerca una città che compare su una sola mappa antica, in un punto dove ora c'è nebbia", "misura le distanze a passi e le scrive sul proprio braccio, dove non si perdono", "lavorava per l'Ateneo, ora disegna solo per chi paga in racconti di viaggio"], "aspetto": ["una bussola in ogni tasca, e nessuna punta a nord", "braccia tatuate di linee, fiumi e numeri", "un rotolo di carta lungo come una persona, portato sulla schiena come una lancia", "misura tutto col pollice teso e un occhio chiuso, prima di parlarne", "stivali risuolati tante volte che sono più toppa che cuoio", "mormora i nomi delle strade mentre cammina, come preghiere"], "vuole": ["una scorta fino a un incrocio che compare solo con la nebbia", "che i PG descrivano ogni dettaglio della strada che hanno appena percorso", "una mappa rubata dal suo carro, l'unica copia", "che i PG verifichino se un ponte segnato sulla mappa esiste ancora, prima che ci passi una carovana", "inchiostro ricavato da una pianta che cresce solo dove l'Umbra è passata", "che i PG portino un messaggio a un villaggio raggiungibile solo per una strada che si apre stanotte"], "offre": ["una scorciatoia che taglia due giorni di viaggio, purché nessuno si fermi a metà", "la mappa del luogo che i PG cercano, con un errore voluto in un punto preciso", "la posizione esatta di un villaggio abbandonato con le cantine ancora piene", "una lettura del terreno: dove l'Umbra colpirà la prossima volta", "un sentiero sicuro tra due territori nemici, segnato con nodi su una corda", "un indirizzo: una porta che dà su una via scomparsa, e ciò che c'è dietro"], "segreto": ["le strade che disegna diventano reali, e ogni strada nuova ne cancella una vecchia, con chi ci abita", "ha venduto la mappa del villaggio dei PG a dei predoni", "ha cancellato apposta un villaggio dalle mappe ufficiali per proteggerlo, e ora laggiù serve aiuto che non arriverà", "la città perduta delle sue mappe è casa sua, e ci ha chiuso dentro qualcuno", "fornisce ancora all'Ateneo le mappe con cui si decide quali villaggi abbandonare", "non sa più tornare a casa: ogni volta che ci prova, la strada finisce in un lago"], "battuta": ["«Le mappe non mentono. Invecchiano.»", "«Qui c'era una città. Lo so perché l'ho disegnata io.»", "«Tre giorni a piedi. O mezza giornata, se la nebbia è d'accordo.»", "«Non andate mai dove la mappa è bianca. Il bianco non è vuoto, è un avvertimento.»", "«Ditemi da dove venite e vi dirò se esiste ancora.»", "«Questa strada l'ho percorsa ieri. Oggi non c'è. Domani, chissà.»"]}, {"id": "guida-fogne", "label": "Guida delle fogne", "cult": ["resistenti", "sotterranei"], "stat": ["Lacchè dei Coltelli Seghettati", "Ombra dei Coltelli Seghettati", "Ladro Mascherato"], "chi": ["ha undici anni e conosce ogni galleria sotto la città, meglio delle guardie e dei ratti", "porta i forestieri sotto le mura per due monete, tre se c'è da correre", "guida una banda di ragazzini che vive nelle vecchie cisterne", "raccoglie dalle grate ciò che la città butta via, e a volte trova cose che nessuno doveva buttare", "vende candele di sego a chi lavora nelle gallerie e si fa pagare in notizie", "segna i muri delle gallerie con simboli che solo i bambini di strada sanno leggere"], "aspetto": ["piedi nudi e callosi, una lanterna cieca grande quanto la sua testa", "un cappello da adulto calato fino al naso", "un odore che fa lacrimare gli occhi, portato con orgoglio", "fischietta un motivo diverso a ogni incrocio, per non perdere la strada", "un ratto addomesticato che spunta dal colletto quando sente odore di cibo", "denti da latte mancanti e uno sguardo che conta già le vostre monete"], "vuole": ["che i PG ritrovino un amico sparito nella galleria dove l'acqua è nera", "un paio di stivali veri, adesso, prima di scendere", "che i PG spaventino la banda che chiede il pizzo ai ragazzini delle cisterne", "una lettera consegnata a un genitore che vive in superficie e non vuole saperne", "che i PG uccidano la cosa nella cisterna grande, quella che canta", "metà paga subito, in cibo caldo"], "offre": ["un passaggio sotto le mura, fino a un punto qualunque della città", "i nomi delle guardie che scendono nelle fogne per affari loro", "una dozzina di occhi: i ragazzini sanno chi entra e chi esce da ogni porta", "una cosa trovata in una grata: un anello con uno stemma che qualcuno sta cercando", "un nascondiglio asciutto dove nessun adulto è mai entrato", "il cunicolo dimenticato che porta dritto nella cantina di un palazzo importante"], "segreto": ["ha venduto i PG a una banda e ora se ne pente, ma l'agguato è già pronto", "porta da mangiare a una creatura delle gallerie che protegge i bambini e divora tutti gli altri", "ha sangue nobile, e la sua famiglia ha pagato degli assassini perché non torni mai a casa", "la banda dei ragazzini ruba anche per una guardia corrotta, che in cambio li lascia vivere", "in fondo alle gallerie ha trovato una porta antica, e ogni notte qualcosa dall'altra parte risponde ai suoi colpi", "ha l'Umbra negli occhi: al buio vede tutto, e ogni settimana la luce del giorno fa più male"], "battuta": ["«Due monete. Tre se urlate. Quattro se vi devo trascinare.»", "«Lì no. Lì l'acqua morde.»", "«I grandi non guardano mai in basso. Per questo noi stiamo qui.»", "«Tenete la mano sul muro destro. Sempre. Anche se il muro si muove.»", "«Se sentite cantare, state zitti. Se smette, correte.»", "«Mia madre dice che sono un ratto. I ratti sopravvivono.»"]}, {"id": "inquisitore", "label": "Inquisitore pentito", "cult": ["celsiani", "resistenti"], "stat": ["Capo delle Guardie", "Cavaliere del Reame", "Campione Consacrato"], "chi": ["ha mandato al rogo streghe e Toccati per vent'anni, e ora cerca le loro famiglie per chiedere perdono", "porta ancora il sigillo dell'ordine, ma lo usa per far scappare chi doveva arrestare", "vive in una torre di guardia diroccata e scrive sui muri i nomi di chi ha condannato", "ha lasciato l'ordine il giorno in cui l'ordine voleva bruciare un villaggio intero", "difende oggi in tribunale le stesse persone che ieri accusava", "dà la caccia ai vecchi confratelli prima che facciano altre vittime"], "aspetto": ["un marchio a fuoco sul palmo: il simbolo dell'ordine, cancellato da un secondo marchio", "una veste di sacco sopra una cotta di maglia di ottima fattura", "si inginocchia davanti a ogni Pira, ma non prega mai", "voce gentile, abituata a fare domande che finiscono male", "un mazzo di chiavi appeso al collo, di celle che non esistono più", "non guarda mai il fuoco, nemmeno quando si scalda"], "vuole": ["che i PG portino fuori città una famiglia di Toccati prima che arrivino i vecchi confratelli", "un documento dall'archivio dell'ordine: la lista delle prossime condanne", "che uno dei PG ascolti la sua confessione, tutta, adesso", "che i PG fermino un rogo previsto per domani all'alba", "il perdono di una persona a cui ha bruciato la casa, e che ha tutte le ragioni per non perdonare", "un posto dove nascondersi: l'ordine ha messo una taglia sulla sua testa"], "offre": ["le procedure dell'ordine: come interroga, come cerca, come gli si sfugge", "la sua spada, e un addestramento contro chi usa la magia", "la parola d'ordine per entrare in una prigione dell'ordine", "i nomi dei confratelli che si lasciano corrompere", "un segno di riconoscimento che fa abbassare le armi a qualunque inquisitore, per un momento", "la verità su un vecchio processo che ha colpito la famiglia di uno dei PG"], "segreto": ["sa che uno dei Toccati che protegge ha già ucciso, e continua a proteggerlo", "il pentimento è una recita: lavora ancora per l'ordine e cerca un nascondiglio di Toccati", "ha condannato ingiustamente un parente di uno dei PG", "tiene ancora un diario di ogni rogo, con disegni accurati, e a volte lo rilegge con piacere", "c'è davvero un Toccato pericoloso in città, ed è una persona amata da tutti: denunciarlo significa un rogo", "porta sulla schiena le vene nere dell'Umbra, da prima di lasciare l'ordine"], "battuta": ["«Ho fatto domande per vent'anni. Adesso tocca a me rispondere.»", "«Il fuoco purifica. Mi hanno insegnato questo. Mi hanno insegnato male.»", "«Non chiedetemi di perdonarmi. Chiedetemi di essere utile.»", "«Conosco quegli stivali. Li ho lucidati anch'io.»", "«Tutti hanno qualcosa da confessare. Io ho solo cominciato prima.»", "«Se vi prendono, dite il mio nome. Vi bruceranno più tardi.»"]}, {"id": "alchimista", "label": "Alchimista di mercato", "cult": ["celsiani", "sotterranei"], "stat": ["Mercante", "Assassino Avvelenatore", "Esperimento Fallito"], "chi": ["vende elisir da un banco al mercato, con cartellini scritti a mano e garanzie a voce", "prepara tinture, veleni per topi e filtri d'amore, e li tiene sullo stesso scaffale", "prova ogni intruglio su di sé prima di venderlo, e ne porta i segni", "ha imparato il mestiere in un laboratorio dell'Ateneo che poi è saltato in aria", "compra a peso cose che nessuno vuole: occhi di bestia, cenere di Pira, terra di cimitero", "fa concorrenza ai guaritori con prezzi bassi e risultati imprevedibili"], "aspetto": ["sopracciglia di due colori diversi, ricordo di un esperimento", "una nuvoletta di fumo violetto che esce dalle tasche", "dita gialle fino alle nocche, e un odore di zolfo e cannella", "annusa ogni moneta prima di metterla via", "occhiali dalle lenti affumicate sempre alzati sulla fronte, mai abbassati", "una bilancina d'ottone appesa alla cintura che tintinna a ogni passo"], "vuole": ["un ingrediente vivo: una bestia piccola, velenosa e molto arrabbiata", "che i PG provino un intruglio nuovo, adesso, e descrivano cosa sentono", "che i PG tengano lontano un cliente insoddisfatto prima che parli con le guardie", "che i PG recuperino un alambicco prestato a un collega che non apre più la porta", "una scorta al mercato notturno dei Sotterranei, dove si vendono cose proibite", "un campione di sangue di un ritornato, fresco"], "offre": ["un elisir di guarigione a metà prezzo, con un effetto collaterale a sorpresa", "un fumogeno che riempie una stanza di nebbia per qualche minuto", "l'analisi di qualunque veleno, polvere o liquido i PG portino", "una boccetta di fuoco liquido, da maneggiare con molta cura", "l'antidoto giusto, e il nome di chi ha comprato il veleno", "un tonico che toglie il sonno per tre notti, e qualcos'altro dopo"], "segreto": ["metà degli elisir sono acqua colorata, e tutta la concorrenza lo sa", "vende veleni a chiunque, compreso chi li userà contro i PG", "la cenere di Pira che compra è rubata ai santuari, e un villaggio rischia di restare al buio", "ha creato per errore una muffa che fa tornare i morti più in fretta, e la produce ancora per un cliente", "ha un rimedio che tiene a bada la piaga dei ritornati, ma si fa con i resti di morti che le famiglie credono sepolti", "sotto i vestiti, per colpa dei suoi stessi intrugli, la pelle si sta coprendo di squame"], "battuta": ["«Funziona. Quasi sempre. Diciamo spesso.»", "«Veleno, medicina: dipende dalla dose e da chi paga.»", "«Non annusatelo. Ecco, l'avete annusato.»", "«Soddisfazione garantita o rimborso. I morti non chiedono rimborsi.»", "«Ho una cosa per quello. Ho una cosa per tutto.»", "«Se la pelle diventa blu, è normale. Se diventa verde, tornate qui di corsa.»"]}, {"id": "cantastorie", "label": "Cantastorie su commissione", "cult": ["senzaporta", "resistenti"], "stat": ["Cortigiano", "Ladro Mascherato", "Dignitario"], "chi": ["scrive canzoni su ordinazione: lodi, insulti, dichiarazioni d'amore, elogi funebri", "va di locanda in locanda a cantare le imprese degli altri, inventando dove serve", "ha una canzone su ogni potente della regione, e per ognuna c'è chi paga perché non la canti", "porta le notizie da un villaggio all'altro in rima, perché così la gente le ricorda", "tiene viva la memoria dei villaggi scomparsi cantando i nomi di chi ci abitava", "ha la voce più famosa della valle, e la sua ultima canzone ha fatto scoppiare una rissa"], "aspetto": ["un liuto con una corda di troppo e una di meno", "abiti sgargianti rattoppati con stoffe ancora più sgargianti", "accompagna ogni frase con un accordo, anche quando non serve", "voce rauca da taverna che diventa limpida appena canta", "un quaderno di testi pieno di nomi cancellati e riscritti", "china la testa a ogni complimento e prende appunti a ogni insulto"], "vuole": ["una storia vera da cantare, la più incredibile che i PG abbiano vissuto", "che i PG proteggano l'esibizione di stasera: qualcuno ha giurato di interromperla", "che i PG riscattino il suo liuto, perso a dadi con la persona sbagliata", "che i PG facciano qualcosa di eroico davanti a tutti, così da avere materiale nuovo", "che i PG consegnino una serenata cantandola di persona, a qualcuno che non vuole riceverla", "un passaggio fino in città, prima che il nobile offeso dall'ultima canzone mandi le guardie"], "offre": ["una canzone sui PG: dove la cantano, la gente li riconosce e li aiuta", "pettegolezzi in rima su tutti i presenti", "un diversivo: quando attacca la ballata giusta, nessuno guarda più la porta", "la strofa mancante di una vecchia ballata, che indica dove fu sepolto un tesoro", "un ingresso a una festa nobiliare, come parte del suo seguito", "una canzone satirica capace di rovinare la reputazione di un nemico dei PG"], "segreto": ["le canzoni che vende contengono messaggi in codice per una rete di spie", "la ballata più famosa della valle è sua, e la battaglia che racconta non è mai avvenuta: è servita a coprire un massacro", "ha rubato tutte le sue canzoni a un vecchio collega che ora vive in miseria", "riceve soldi da una famiglia potente per cantare male dei suoi rivali", "conosce un verso che fa riposare i morti per sempre, ma chi lo canta perde la voce", "ha scritto una canzone che accusa una persona innocente, e quella persona ora rischia la forca"], "battuta": ["«Una strofa per l'eroe, due per il cattivo. I cattivi pagano meglio.»", "«Ditemi il vostro nome. Vi faccio diventare leggenda, o barzelletta. Dipende dalla mancia.»", "«La verità è noiosa. Io la miglioro.»", "«Non applaudite. Pagate.»", "«Fra cent'anni nessuno ricorderà voi. Ricorderanno la mia canzone su di voi.»", "«Cosa fa rima con tradimento? Pagamento. Sempre.»"]}, {"id": "falsario", "label": "Fabbro di reliquie false", "cult": ["sotterranei", "montanari"], "stat": ["Teppista Comune", "Maestro d'Armi", "Soldato Scelto"], "chi": ["forgia ossa di santi, chiodi sacri e schegge di spade leggendarie, una decina al mese", "di giorno lavora alla forgia come un fabbro qualunque, di notte invecchia il ferro con fuliggine e aceto", "ha venduto lo stesso dito dello stesso santo a tre templi diversi", "rifornisce di amuleti contro l'Umbra mezza regione, e nessuno ha ancora chiesto se funzionano", "ricostruisce le reliquie perdute di famiglie che non vogliono ammettere di averle vendute", "ha una bottega piena di teste di martiri, tutte con la stessa faccia"], "aspetto": ["avambracci pieni di piccole bruciature a forma di croce, di stella, di ruota", "un grembiule da fabbro con un reliquiario d'argento appuntato sopra, come una spilla", "soffia sulle cose prima di mostrarle, come se avessero addosso polvere di secoli", "occhi arrossati dal fumo e il sorriso di chi ha appena concluso un affare", "un tremito alla mano sinistra che sparisce del tutto quando lavora", "parla delle sue reliquie con una devozione sincera, come se fossero vere"], "vuole": ["un pezzo autentico da copiare: una reliquia vera, prestata per una notte", "che i PG consegnino una cassa di reliquie a un tempio, senza aprirla e senza domande", "che i PG spaventino un esperto dell'Ateneo che sta per smascherare la bottega", "ossa vere, e non di animale, per un lavoro importante", "che i PG ritrovino un apprendista scappato con gli stampi e i segreti del mestiere", "testimoni che giurino sulla sua buona fede: domani c'è un processo per frode"], "offre": ["un falso perfetto di qualunque oggetto, in tre giorni", "un lasciapassare con sigillo sacro, indistinguibile dall'originale", "un occhio che riconosce qualsiasi falso, e sa dire chi l'ha fatto", "un'arma solida, e in omaggio una leggenda da raccontare a chi la vede", "l'elenco dei templi che espongono i suoi falsi, e cosa custodiscono davvero nelle cripte", "la reliquia vera che ha sostituito anni fa, nascosta sotto la forgia"], "segreto": ["una delle sue reliquie false ha fatto un miracolo vero, e non sa spiegarselo", "sostituisce le reliquie vere dei templi con delle copie e vende gli originali", "gli amuleti contro l'Umbra non funzionano, ma senza di essi i villaggi cadrebbero nel panico", "le ossa che usa vengono dalle fosse comuni dei ritornati", "ha forgiato la reliquia su cui si regge la fede di un intero villaggio: rivelarlo spezzerebbe quella gente", "un ordine sacro compra i suoi falsi in piena coscienza, per rimpiazzare le reliquie vendute dai propri capi"], "battuta": ["«Vero, falso… La gente prega lo stesso.»", "«Questo osso ha settecento anni. Più o meno. Diciamo da martedì.»", "«Non vendo bugie. Vendo conforto, col bollo.»", "«Un santo ha duecentosei ossa. I miei clienti ne hanno comprate novecento.»", "«L'importante è il peso. La gente si fida delle cose pesanti.»", "«Toccatelo pure, porta fortuna. Ve lo garantisco: l'ho fatto io.»"]}, {"id": "pescatore", "label": "Pescatore di cose annegate", "cult": ["resistenti", "sotterranei"], "stat": ["Schermagliatore", "Pirata Brutale", "Tritone Maledetto"], "chi": ["getta le reti nel lago dove è affondato un villaggio intero, e tira su ciò che il villaggio ha perso", "recupera dai fiumi i corpi degli annegati per le famiglie, a pagamento, e tiene per sé quel che hanno in tasca", "pesca con un amo d'argento le cose che la gente butta in acqua per dimenticarle", "si immerge nelle cisterne della città vecchia trattenendo il fiato per minuti interi", "vende ricordi bagnati, lettere, ritratti, giocattoli, a chi riconosce qualcosa", "rema ogni notte sul fiume e prega le cose sul fondo di restarci"], "aspetto": ["pelle grinzosa di chi sta troppo in acqua, e un odore di alghe che non va via", "una collana di chiavi arrugginite che non aprono niente di conosciuto", "trattiene il respiro per abitudine ogni volta che qualcuno alza la voce", "una voce che sembra arrivare da sott'acqua", "una barca a fondo piatto trascinata con una corda, anche sulla terraferma", "occhi chiarissimi, quasi bianchi, abituati al fondo torbido"], "vuole": ["aiuto a tirare su una cosa troppo pesante per la sua rete, che ha appena aperto gli occhi", "che i PG scoprano chi butta corpi legati nel suo tratto di fiume", "una scorta per un tuffo nel lago nero, dove la corda si spezza sempre a metà", "che i PG riportino un anello ripescato a chi l'ha perso, e che non vuole riaverlo", "reti nuove, perché in una notte qualcosa le ha tagliate tutte", "che i PG tengano la corda mentre scende, e la tirino su al terzo strattone, non prima"], "offre": ["un oggetto ripescato che uno dei PG riconosce", "un passaggio in barca lungo il fiume, lento ma invisibile", "le correnti del lago: dove si può nuotare e dove non si torna su", "una cassa sigillata ripescata ieri, ancora chiusa", "una spada antica dalla lama verde d'alghe, che non arrugginisce", "notizie dal fondo: cosa è stato gettato in acqua di recente, e da chi"], "segreto": ["ha ripescato le prove di un omicidio e le usa per ricattare un notabile", "il villaggio sommerso è ancora abitato, e chi ci vive pretende ogni mese un vivo in cambio dei pesci", "ha annegato il proprio socio, e il corpo non è mai venuto a galla", "tiene in casa le cose ripescate che non vende, e con quelle sta costruendo una persona", "ha ripescato il bambino annegato di una famiglia del paese: respira ancora, sott'acqua, e la famiglia lo piange", "ha le branchie dietro le orecchie, e ogni anno sono più profonde"], "battuta": ["«Quello che finisce in acqua non sparisce. Aspetta.»", "«Ho tirato su una corona, una volta. Con la testa ancora dentro.»", "«Non buttate niente nel fiume. Il fiume restituisce, con gli interessi.»", "«Tenete forte la corda. Se tira in giù da sola, lasciatela.»", "«L'acqua è fredda, il fondo è più freddo. Andiamo?»", "«Questa la conosco. È di uno di voi, vero?»"]}, {"id": "usuraio", "label": "Usuraio", "cult": ["celsiani", "sotterranei", "resistenti"], "stat": ["Mercante", "Magnate", "Consigliere di Corte"], "chi": ["presta denaro a chiunque, a interessi che crescono con la luna", "tiene i pegni dei disperati in una stanza che sembra il magazzino di un intero villaggio", "presta braci invece di monete, e d'inverno fa pagare il fuoco a peso d'oro", "ha comprato i debiti di metà città, e metà città abbassa gli occhi al suo passaggio", "accetta in pegno anche cose che non si possono toccare: promesse, anni di servizio, nomi", "riscuote di persona, con un libro mastro sotto il braccio e due nipoti grossi come porte"], "aspetto": ["mani sempre pulite, unghie curate, un anello per ogni debitore che non ha pagato", "un pallottoliere d'avorio che fa scorrere mentre parla, anche quando non conta", "abiti modesti e scarpe da principe", "sorride a lungo, in silenzio, prima di dire un numero", "una tosse secca che usa per interrompere chiunque provi a trattare", "occhiali tondi e una penna dietro l'orecchio, sporca d'inchiostro rosso"], "vuole": ["che i PG riscuotano un debito da una persona che non può pagare", "che i PG recuperino un pegno rubato dalla sua stanza blindata", "garanzie: un oggetto prezioso dei PG in pegno, prima di qualsiasi aiuto", "che i PG trovino un debitore scappato con la famiglia e la casa intera sul carro", "una scorta per il giorno di riscossione nel quartiere povero", "che i PG convincano un nobile a firmare un'ipoteca stasera, prima che rinsavisca"], "offre": ["un prestito immediato, di qualunque somma, a condizioni che leggerete dopo", "la cancellazione del debito di qualcuno a cui i PG tengono", "le debolezze di chiunque in città, perché prima o poi tutti passano da quella porta", "un oggetto preso in pegno anni fa e mai riscattato: proprio quello che serve ai PG", "la lista di chi deve soldi a chi, per far parlare le persone giuste", "il debito segreto di un potente, da usare come leva"], "segreto": ["deve a sua volta una cifra enorme a qualcosa che non è umano", "ha in pegno un oggetto che appartiene a uno dei PG, o alla sua famiglia", "rovina i ricchi per prestare ai poveri quasi senza interessi, e nessuno deve saperlo", "il suo libro mastro è vincolato da un patto: i debiti non pagati passano ai figli, anche dopo la morte", "se muore, tutti i debiti della città si estinguono, e un gruppo di debitori ha già pagato un sicario", "finanzia in segreto la milizia che difende le mura: senza i suoi interessi da strozzo, le mura cadrebbero"], "battuta": ["«La crudeltà non c'entra. È aritmetica.»", "«Un debito è una promessa. E io credo nelle promesse.»", "«Firmate qui. E qui. E qui, dove c'è scritto piccolo.»", "«Tutti pagano. Alcuni in monete.»", "«Prestare è un atto di fede. Riscuotere, di giustizia.»", "«Non mi interessa a cosa vi servono. Mi interessa quando li riporterete.»"]}, {"id": "guardia", "label": "Guardia corrotta", "cult": ["resistenti", "montanari"], "stat": ["Guardia Armata", "Capo delle Guardie", "Soldato Scelto"], "chi": ["prende mazzette da tutti, ma una volta sola a persona, e mantiene sempre la parola", "chiude un occhio sui piccoli furti e li fa pagare ai ladri grossi", "fa la ronda nel quartiere peggiore della città, e lo protegge come un cane da pastore", "riscuote il pizzo per conto del capitano e ne restituisce di nascosto un terzo alle vedove", "vende i turni di guardia al miglior offerente, ma mai quelli della porta che dà sulla tempesta", "ha un tariffario scritto su un'asse: rissa, furto, contrabbando, ognuno col suo prezzo"], "aspetto": ["divisa stirata alla perfezione, stivali sfondati", "una borsa tintinnante sotto la giubba e una lancia che non vede olio da anni", "fischietta mentre conta le monete, sempre lo stesso motivo", "il naso rotto tre volte, e ogni volta raddrizzato male", "saluta toccandosi l'elmo con due dita, che siano ladri o nobili", "mangia sempre qualcosa preso da una bancarella, senza mai pagare"], "vuole": ["il suo pezzo: una moneta d'oro per voltarsi dall'altra parte", "che i PG diano una lezione a una guardia nuova troppo avida, che rovina gli affari", "che i PG portino fuori città un ladruncolo prima che lo prenda il capitano", "che i PG facciano sparire una prova che inchioda un innocente", "rinforzi: stanotte c'è da fermare una banda, e il capitano è sul libro paga della banda", "un colpevole credibile per un furto, entro stasera, che non sia il vero colpevole"], "offre": ["un tratto di mura senza sorveglianza, in un punto e a un'ora precisa", "il nome di chi ha venduto i PG alle autorità", "le chiavi della prigione, in prestito per un'ora", "un avvertimento in tempo: domani all'alba vengono a cercarvi", "i turni delle ronde di tutta la settimana", "protezione: nel suo quartiere nessuno tocca chi paga"], "segreto": ["mette da parte ogni moneta per comprare la libertà di un parente in prigione", "è sul libro paga di due bande rivali, e le aizza l'una contro l'altra per tenerle deboli", "ha le prove che il capitano vende armi ai predoni, ma denunciarlo costerebbe il posto a tutto il presidio", "per pietà ha fatto entrare in città un Toccato ferito, e da allora in città si muore di notte", "le mazzette comprano l'olio per le lanterne del quartiere, che la città non paga più", "in un'altra città c'è una taglia sulla sua testa, per aver ucciso un esattore"], "battuta": ["«Corruzione? No. Tariffa.»", "«Una moneta per guardare, due per non vedere, tre per dimenticare.»", "«La legge è per chi può permettersela. Io vendo l'alternativa.»", "«Qui comando io finché il sole è alto. Poi comandano loro.»", "«Pagate me, o pagate il capitano. Io almeno vi do il resto.»", "«Non ho visto niente. Però l'ho visto bene, se capite.»"]}, {"id": "capobanda", "label": "Capobanda in lutto", "cult": ["resistenti", "senzaporta"], "stat": ["Luogotenente dei Coltelli Seghettati", "Assassino Avvelenatore", "Maestro Assassino"], "chi": ["ha preso il comando della banda il giorno del funerale del suo compagno, e nessuno ha fiatato", "comanda una banda di ladri dalla cucina di casa, tra una zuppa e un ordine", "porta il lutto da un anno e ha giurato di toglierlo solo quando l'assassino sarà sottoterra", "governa tre vicoli con regole più severe di quelle della città, e più rispettate", "tiene la banda unita come una famiglia: chi tradisce sparisce, chi soffre mangia", "ha trasformato la banda in una scorta per le botteghe che la città ha abbandonato"], "aspetto": ["abiti neri da lutto, cuciti alla perfezione, e un coltello a serramanico infilato nella fascia", "un anello nuziale su una catenella al collo, insieme a una chiave", "parla piano, e la stanza si zittisce per sentire", "versa sempre un bicchiere in più e lo lascia sul tavolo, pieno", "un ventaglio di pizzo nero, sempre chiuso, che usa per indicare", "occhi asciutti e mani che non stanno mai ferme: rammendano, sbucciano, affilano"], "vuole": ["il nome di chi ha ucciso il suo compagno, entro stanotte", "che i PG trattino una tregua con la banda rivale, a nome della sua", "che i PG ritrovino un membro della banda sparito con la cassa", "che i PG rubino dalla caserma il registro dove c'è il nome di tutta la banda", "rispetto: che i PG chiedano il permesso prima di lavorare nei suoi vicoli", "che i PG proteggano il funerale di un membro della banda, dove i nemici verranno di sicuro"], "offre": ["venti coltelli pronti a muoversi a un suo cenno", "un nascondiglio in città che le guardie non hanno mai trovato", "il furto di qualunque cosa, entro tre giorni", "un debito di sangue: chi aiuta la banda resta sotto la sua protezione per sempre", "informazioni su chi si muove di notte in tutta la città", "documenti falsi, sigilli e lasciapassare dalla stamperia della banda"], "segreto": ["ha ucciso il proprio compagno, e la caccia all'assassino tiene unita la banda", "il compagno è tornato dalla morte e vive nascosto in cantina, e la banda non ne sa niente", "tratta in segreto con le guardie per consegnare la banda in cambio della libertà dei figli", "l'assassino del compagno è il luogotenente più leale della banda, e lo ha già capito", "i furti della banda tengono in vita il quartiere: senza, la gente morirebbe di fame quest'inverno", "vuole lasciare tutto e sparire, ma non sa a chi lasciare la banda senza scatenare una guerra"], "battuta": ["«Mangiate. Poi parliamo di chi deve morire.»", "«Il mio compagno avrebbe riso di voi. Io no. Io prendo appunti.»", "«Nessuno ruba nei miei vicoli. Tranne me.»", "«Il lutto mi dona, dicono. Anche la vendetta.»", "«Siete in casa mia. Giù il cappello, e via le mani dalle armi.»", "«Ho pianto una notte. Il resto dell'anno lavoro.»"]}, {"id": "fuggiasco", "label": "Fuggiasco", "cult": ["resistenti", "montanari"], "stat": ["Teppista Comune", "Ombra dei Coltelli Seghettati", "Ladro Mascherato"], "chi": ["ha scavalcato le mura della prigione stanotte e ha ancora la catena alla caviglia", "ha passato anni in una miniera-prigione, e oggi rivede il cielo per la prima volta", "scappa da una condanna per un delitto che ammette senza vergogna", "durante la fuga ha lasciato indietro un compagno di cella ferito, e non smette di pensarci", "corre da tre giorni senza dormire, con i cani della prigione alle calcagna", "ha guidato una rivolta in prigione, e adesso decine di detenuti sono sparsi per la regione"], "aspetto": ["polsi piagati dai ferri, avvolti in stracci", "testa rasata male, a chiazze, con un coltello", "mangia con le mani, in fretta, proteggendo il piatto col braccio", "un numero tatuato sul collo, mezzo grattato via", "sobbalza a ogni rumore di metallo", "pallore da cella e occhi socchiusi anche all'ombra, come se il sole facesse male"], "vuole": ["un nascondiglio, adesso: le guardie sono a due strade da qui", "uno scalpello o una lima, subito, per togliersi i ferri", "che i PG portino un messaggio alla sua famiglia: non deve aspettarsi il suo ritorno", "che i PG aiutino a liberare chi è rimasto dentro, stanotte, prima del trasferimento", "abiti, un nome nuovo e un posto su un carro che parte prima dell'alba", "che i PG trovino chi ha testimoniato il falso al suo processo"], "offre": ["la pianta dei cunicoli della prigione, con il punto debole del muro", "metà di un bottino sepolto prima dell'arresto", "i nomi dei carcerieri corrotti, e il loro prezzo", "una lealtà senza condizioni, finché i PG non la tradiscono", "notizie su un prigioniero che i PG conoscono, o cercano", "il racconto di cosa scavano davvero nella miniera della prigione"], "segreto": ["è colpevole, e di qualcosa di peggio di quanto crede la legge", "è innocente, e il vero colpevole siede nel consiglio cittadino", "la fuga è stata organizzata dalle guardie stesse, per seguirne le tracce fino ai complici", "ha liberato anche un prigioniero molto pericoloso, che ora gira per le stesse strade", "in prigione ha ucciso una guardia per salvare un ragazzo: se torna dentro, c'è la forca", "c'è una taglia sulla sua testa che basterebbe a risolvere tutti i problemi dei PG"], "battuta": ["«Non vi chiedo di fidarvi. Vi chiedo di correre.»", "«Sei anni. Il cielo era più piccolo, prima?»", "«Non fermatevi per me. Ma se vi fermate, portatemi.»", "«Mangio, poi vi spiego. No: mangio, e basta.»", "«L'ultima persona che mi ha dato una mano è ancora là dentro. Pensateci.»", "«Ho scavato con un cucchiaio per due anni. Non ditemi che è impossibile.»"]}, {"id": "araldo", "label": "Araldo di una casata", "cult": ["celsiani", "montanari"], "stat": ["Cortigiano", "Duellante Arcano", "Consigliere di Corte"], "chi": ["annuncia i decreti di una famiglia potente nei villaggi che quella famiglia sta comprando", "porta ovunque il nome della sua casata, e la casata non ricorda più il suo", "deve consegnare una dichiarazione di guerra, e rallenta il viaggio di proposito", "conosce a memoria lo stemma, il motto e i debiti di ogni famiglia della regione", "precede il corteo della casata di mezza giornata, per avvisare, preparare e nascondere", "legge in piazza le condanne dei debitori della casata, e ogni volta perde un amico"], "aspetto": ["un tabarro coi colori della casata, così brillanti da far male agli occhi", "una tromba d'ottone ammaccata a tracolla e un rotolo di sigilli alla cintura", "una voce da piazza che non sa abbassare, nemmeno quando sussurra", "si schiarisce la gola tre volte prima di ogni frase importante", "un cavallo bianco tenuto meglio di chi lo cavalca", "guanti bianchi immacolati, cambiati a ogni tappa"], "vuole": ["che i PG portino il proclama in un villaggio dove l'ultimo araldo è finito appeso a un albero", "una scorta fino al castello, con un messaggio che nessuno deve leggere", "che i PG recuperino il sigillo della casata, rubato stanotte alla locanda", "che i PG trovino un erede della casata scappato con un amore sbagliato, prima che arrivi il corteo", "che i PG cambino una parola del proclama, una sola, per salvare un villaggio", "che i PG convincano un villaggio a inginocchiarsi senza spargere sangue"], "offre": ["un lasciapassare con il sigillo della casata, che apre porte e chiude bocche", "un'udienza con un membro della casata, breve e indimenticabile", "i pettegolezzi di corte: chi ama chi, chi odia chi, chi deve a chi", "il contenuto dei proclami prima che vengano letti", "un posto nel corteo, sotto la protezione delle bandiere della casata", "una lettera di raccomandazione falsa, ma scritta con l'inchiostro vero"], "segreto": ["il proclama che porta è falso: lo ha scritto per salvarsi la pelle", "la casata è sull'orlo della rovina, e solo gli araldi lo sanno", "il messaggio sigillato che porta ordina la sua stessa morte all'arrivo", "ama un membro di una famiglia nemica e le passa i proclami in anticipo", "il proclama impone a un villaggio di consegnare le sue braci alla casata: leggerlo significa condannare il villaggio", "ha sangue illegittimo della casata, e un diritto di successione che nessuno conosce"], "battuta": ["«Udite, udite! No, davvero, ascoltate: è importante.»", "«Io porto le parole. Il peso lo portate voi.»", "«Non si uccide il messaggero. È una regola antica, e molto saggia.»", "«La casata vi saluta. La casata vi osserva. La casata vi manda il conto.»", "«Ho letto questo proclama in nove villaggi. In tre mi hanno tirato pietre.»", "«Mi pagano per dire queste parole, non per crederci.»"]}, {"id": "eremita", "label": "Eremita dell'Umbra", "cult": ["resistenti", "elfi", "sotterranei"], "stat": ["Mago dall'Anima Infranta", "Adepto del Culto", "Spettro Sussurrante"], "chi": ["vive nel cuore della zona d'ombra, dove nessun altro resiste più di una notte", "ha costruito una capanna sul confine della tempesta e conta quante volte il confine avanza", "medita in una grotta da undici anni, mangiando ciò che i pellegrini lasciano all'ingresso", "accoglie chi è stato segnato dall'Umbra e insegna a convivere con ciò che ora porta dentro", "parla con la tempesta come con una vecchia conoscenza, e sostiene che la tempesta risponda", "custodisce un santuario degli dèi velati che nessun villaggio ricorda più"], "aspetto": ["una lanterna spenta al collo, che a volte si accende da sola", "pelle grigia come la cenere, unghie lunghe e scure", "parla sempre al plurale: noi, ci, nostro", "un mantello fatto di nastri di stoffa, ognuno legato da un pellegrino diverso", "piedi scalzi che non lasciano impronte sulla neve", "ride a metà delle frasi, per cose che sente solo dentro di sé"], "vuole": ["che i PG portino via dalla zona d'ombra un pellegrino che non riesce più a uscirne", "olio, sale e candele: le scorte che nessun villaggio porta più", "che i PG ascoltino la tempesta in silenzio per un'ora, e poi raccontino cosa hanno sentito", "che i PG seppelliscano una cosa che la tempesta ha lasciato davanti alla sua porta", "che i PG fermino un gruppo di cacciatori di Toccati che sta salendo verso il suo rifugio", "che i PG portino un avvertimento al villaggio: l'Umbra tornerà tra sette giorni, e più forte"], "offre": ["un riparo dove la tempesta non entra, per motivi che non spiega", "una tecnica di respiro: chi la impara, durante un riposo breve rimuove uno Stress in più", "la strada attraverso la zona d'ombra, con le soste sicure", "una risposta della tempesta: una sola domanda, una sola risposta", "il nome vero di una cosa che dà la caccia ai PG", "un sacchetto di sale nero: tracciato in cerchio, tiene fuori le ombre per una notte"], "segreto": ["non può lasciare questo luogo: ovunque vada, la tempesta segue i suoi passi", "nutre la tempesta con i ricordi dei pellegrini, e in cambio la tempesta risparmia il villaggio a valle", "i pellegrini che non tornano non si sono persi: li trattiene per sempre, come compagnia", "conosce il modo per fermare la tempesta per una generazione, e costa la vita di chi lo compie", "in gioventù, per curiosità, ha aperto la prima crepa da cui è uscita l'Umbra", "tiene nascosto con sé un bambino nato dentro la tempesta, che non ha mai visto la luce"], "battuta": ["«Non siete i primi a salire fin qui. Siete i primi a farlo con tanto rumore.»", "«La tempesta non è arrabbiata. Ha fame. È diverso.»", "«Sedete. Respirate. No, più piano. Lei vi sente.»", "«Ho smesso di contare gli anni. Conto le tempeste. Siamo a centoventi.»", "«Laggiù chiamano follia quello che qui si chiama attenzione.»", "«Avete portato il sale? Senza sale non si parla.»"]}, {"id": "ricordi", "label": "Mercante di ricordi", "cult": ["celsiani", "elfi", "senzaporta"], "stat": ["Mercante", "Spia", "Sacerdote del Dolore"], "chi": ["compra ricordi con un rito di cera calda e li rivende a chi ha perso i propri", "toglie a pagamento i ricordi che fanno troppo male, e li conserva in fiale numerate", "gira i campi profughi offrendo pane in cambio di un ricordo felice", "custodisce l'ultimo ricordo di molti morti che tornano, e lo vende alle loro famiglie", "ricorda tutto ciò che compra, e da anni non ricorda più niente di suo", "fa da testimone nei processi, rivivendo davanti ai giudici i ricordi comprati alle vittime"], "aspetto": ["una cassettina di legno piena di fiale tappate con la cera, ognuna con un nome", "occhi di due colori diversi, e nessuno dei due sembra suo", "dimentica il vostro nome a ogni frase e se lo fa ripetere sorridendo", "dita lunghe e fredde che vi sfiorano la tempia, come per sentire la febbre", "profumo di cera calda e di qualcosa che vi ricorda l'infanzia", "cambia voce a seconda dell'ultimo ricordo che ha bevuto"], "vuole": ["un ricordo di uno dei PG: il più felice, o il più terribile", "che i PG ritrovino una fiala rubata, che contiene il ricordo di un omicidio", "che i PG convincano una persona a vendere un ricordo che non vuole cedere", "una scorta: qualcuno dà la caccia a chi possiede un certo ricordo, e quel ricordo è nella sua cassetta", "che i PG riconsegnino un ricordo al legittimo proprietario, che senza non sa più chi è", "che i PG sorveglino il suo banco stanotte: un cliente vuole indietro ciò che ha venduto"], "offre": ["un ricordo comprato da un morto: la strada, il volto o il nascondiglio che i PG cercano", "l'oblio di una paura: chi accetta rimuove tutto lo Stress, ma dimentica anche qualcos'altro", "un'abilità presa in prestito: i ricordi di un fabbro, di un ladro, di un mago, per un giorno", "il ricordo di un luogo che nessun vivente ha mai visto", "la prova di un tradimento, chiusa in una fiala da far bere a un giudice", "la verità su qualcosa che uno dei PG ha dimenticato, e che forse era meglio dimenticare"], "segreto": ["uno dei ricordi in vendita appartiene a uno dei PG, che non sa di averlo perso", "chi vende troppi ricordi diventa un guscio vuoto, e i gusci vuoti finiscono a servire uno dei suoi clienti", "toglie gli incubi ai superstiti di un massacro, e con quei ricordi spariscono anche le uniche prove", "custodisce il ricordo che scagionerebbe un innocente condannato, ma il proprietario ha pagato perché non esca mai", "la sua identità è fatta solo di ricordi comprati, e il primo proprietario li rivuole indietro", "beve di nascosto i ricordi felici dei clienti, e le fiale che restituisce sono annacquate"], "battuta": ["«Ogni ricordo ha un prezzo. Quelli brutti costano di più a tenerli.»", "«Avete un bel ricordo d'infanzia? Ve lo pago bene. Non vi mancherà.»", "«Non so chi sono. Ma so chi eravate voi, ieri.»", "«Dimenticare è un lusso. Io lo vendo a rate.»", "«Questo l'ho comprato da un soldato. Volete sentirlo? Dentro fa freddo.»", "«Scusate, ci conosciamo? Ah, sì. Mi avete venduto qualcosa.»"]}, {"id": "taglie", "label": "Cacciatore di taglie", "cult": ["montanari", "senzaporta", "resistenti"], "stat": ["Cecchino dei Coltelli Seghettati", "Cacciatore di Mortali", "Maestro Assassino"], "chi": ["porta i ricercati alla giustizia, vivi se possibile, e conta le monete solo a lavoro finito", "tiene un mazzo di ritratti di ricercati e ogni mattina ne pesca uno a caso per scegliere la preda", "dà la caccia ai morti che tornano con una taglia ancora aperta: per la legge, la condanna vale", "lavora solo per le famiglie delle vittime, a qualunque prezzo possano pagare", "insegue da sette anni la stessa persona, e ha cominciato a rispettarla", "vende i propri servigi a entrambe le parti di ogni faida, e consegna a chi paga prima"], "aspetto": ["un mantello con decine di ritratti cuciti all'interno, come fodera", "catene arrotolate sulla spalla, lucide d'uso", "un cane da traccia con un occhio solo che non si allontana mai più di tre passi", "mastica foglie di menta e sputa dopo ogni nome che pronuncia", "guarda le mani della gente prima del viso, sempre", "una balestra ben oliata e vestiti che non vedono acqua da settimane"], "vuole": ["aiuto per stanare una preda rintanata in un tempio, dove le armi non possono entrare", "sapere se i PG hanno visto la persona del ritratto che tiene in mano", "una mano per trascinare fino in città un prigioniero grosso che morde", "che i PG si facciano da parte: la preda è uno di loro, o qualcuno che proteggono", "soci per una taglia sola: una preda troppo pericolosa per chi lavora senza compagni", "che i PG testimonino davanti al giudice che la cattura è avvenuta secondo le regole"], "offre": ["il nome e il nascondiglio di qualunque ricercato della regione", "l'elenco delle taglie in corso: alcune riguardano persone che i PG conoscono", "una pista: chi ha messo una taglia sulla testa dei PG, e per quanto", "un prigioniero in catene che dice di avere informazioni preziose", "le tecniche dell'inseguimento: come si legge una pista in mezzo a una città", "una parte della taglia, se i PG fanno il lavoro sporco"], "segreto": ["la sua preda è innocente, e lo sa, ma la taglia salverebbe la sua famiglia", "c'è una taglia anche sulla sua testa, più alta di tutte quelle che riscuote", "consegna i ricercati a qualcuno che non li porta in tribunale ma in un laboratorio", "ha già incassato un acconto per uno dei PG, e aspetta solo il momento giusto", "l'ultima preda è un parente stretto, e la taglia l'ha messa la sua stessa famiglia", "porta sempre le prede morte, anche quando si arrendono: i morti non testimoniano"], "battuta": ["«Niente di personale. Il personale costa extra.»", "«Vivo o morto, dice il foglio. Io preferisco vivo: si porta da solo.»", "«Bella faccia. Ne ho una quasi uguale in tasca. Quasi.»", "«Correte pure. Mi piace quando corrono: lasciano tracce.»", "«Ho tre regole: mai di domenica, mai i bambini, mai a credito.»", "«La legge non mi interessa. Mi interessa il sigillo in fondo al foglio.»"]}, {"id": "prodigio", "label": "Prodigio senza maestro", "cult": ["celsiani", "resistenti", "elfi"], "stat": ["Elementale Minore del Caos", "Mago dall'Anima Infranta", "Mago da Battaglia"], "chi": ["ha dato fuoco al fienile di famiglia con uno starnuto, e ora il villaggio non sa cosa farne", "ha quattordici anni e fa fiorire i campi dove passa, anche in pieno inverno", "ha lasciato l'Ateneo dopo una settimana, perché i maestri avevano paura di quello che faceva", "parla con le fiamme della Pira, e le fiamme si piegano verso la sua voce", "spegne ogni luce quando ha paura, e ultimamente ha paura spesso", "sente i pensieri della gente vicina come un brusio che non si spegne mai"], "aspetto": ["capelli che si sollevano da soli quando monta la rabbia", "polpastrelli anneriti, come se avesse toccato il sole", "una coperta sulle spalle anche d'estate, e i bicchieri vicini si coprono di brina", "occhi che cambiano colore con l'umore, e tutto il villaggio sa leggerli", "si morde le unghie fino a sanguinare, e le gocce di sangue fanno scintille", "un'eco leggera dopo ogni parola, come se parlasse in un tempio vuoto"], "vuole": ["qualcuno che insegni a controllare il potere prima del prossimo incidente", "un passaggio fuori dal villaggio, prima che il consiglio decida cosa farne", "che i PG ritrovino il suo animale, sparito dopo l'ultimo incidente", "che i PG convincano la famiglia che non c'è nessuna maledizione", "che i PG fermino un adulto che vuole usare il suo potere per una vendetta", "che i PG mostrino un incantesimo vero, di quelli che si studiano, per capire come si fa"], "offre": ["un'esplosione di potere grezzo, una volta sola, nel momento sbagliato o in quello giusto", "la capacità di sentire la magia: dice chi la usa e dove, anche se nascosta", "una fiamma accesa con un soffio, che non si spegne per una notte intera", "un'amicizia sincera e feroce: chi la conquista ha al suo fianco una forza della natura", "una visione confusa ma vera di un pericolo in arrivo", "il potere di aprire una porta, una serratura, un sigillo: qualunque cosa, ma una volta sola"], "segreto": ["il potere viene da qualcosa nell'Umbra che chiede di essere ringraziato ogni notte", "ha già ucciso qualcuno per errore, e il villaggio ha nascosto il corpo", "l'Ateneo vuole quel potere per farne un'arma, e ha già pagato la famiglia", "il potere consuma la sua vita: ogni incantesimo costa un mese", "porta il segno di una stirpe antica che, secondo le profezie, riaprirà la porta degli dèi velati", "il consiglio del villaggio ha già deciso di vendere questo prodigio a dei mercanti di schiavi"], "battuta": ["«Non l'ho fatto apposta. Neanche le altre volte.»", "«Se mi arrabbio, scappate. Non scherzo: scappate.»", "«Lo sento ronzare, qui dietro gli occhi. Voi no?»", "«Insegnatemi. Prima che impari da me, e male.»", "«Mia madre dice che è un dono. Allora perché piange?»", "«Posso accenderlo. Spegnerlo, ancora no.»"]}, {"id": "superstite", "label": "Superstite di un villaggio scomparso", "cult": ["resistenti", "montanari", "elfi"], "stat": ["Teppista Comune", "Fantasma", "Soldato Scelto"], "chi": ["viene da un villaggio che una notte è sparito, case, gente e campanile, lasciando solo un prato", "cerca qualcuno che si ricordi del suo villaggio, ma tutti dicono che lì non c'è mai stato niente", "porta in una bisaccia l'unica cosa rimasta: la piccola campana della chiesa, senza batacchio", "dorme di giorno e di notte torna sul prato dove sorgeva casa, ad aspettare", "quella notte era l'unica persona fuori dal villaggio, a caccia, e non ha mai smesso di sentirsi in colpa", "racconta a chiunque la storia del suo villaggio, ogni volta con un dettaglio in meno"], "aspetto": ["abiti di una foggia che da queste parti nessuno porta più", "polvere bianca nei capelli che non va via nemmeno col bagno", "si volta di scatto quando qualcuno chiama un nome che somiglia al suo", "una chiave di casa appesa al collo, e nessuna porta da aprire", "parla al passato anche delle cose di oggi", "un'ombra appena più chiara di quella degli altri"], "vuole": ["che i PG passino una notte sul prato vuoto e raccontino cosa vedono", "un testimone: qualcuno in città giura di aver visto vivo, ieri, un abitante del villaggio", "che i PG trovino un archivio che provi l'esistenza del villaggio", "che i PG seguano il suono di campana che arriva ogni notte dalla nebbia", "che i PG affrontino chi vende al mercato oggetti presi dal villaggio scomparso", "una scorta fino al confine, dove un Senzaporta dice di sapere dove sono finiti tutti"], "offre": ["sentieri e scorciatoie che nessuna mappa riporta più", "una ricetta, una canzone, un nodo da pescatore: tutto ciò che resta di un popolo", "un oggetto del villaggio che si scalda quando l'Umbra è vicina", "una lealtà totale, perché i PG sono i primi ad aver creduto alla sua storia", "il punto esatto in cui il villaggio è sparito, e cosa c'è sotto il prato", "un'eredità: le terre del villaggio adesso sono sue, e sono fertili"], "segreto": ["il villaggio non è sparito: è ancora lì, un passo di lato, e ci si può entrare", "quella notte ha fatto un patto per salvarsi, e il prezzo è stato il villaggio", "esiste solo finché qualcuno crede alla sua storia: quando nessuno ci crederà più, svanirà", "gli abitanti del villaggio sono i morti che tornano nella valle, e li riconosce uno per uno", "può riportare indietro il villaggio, ma solo al posto di un altro villaggio", "una settimana prima della sparizione ha venduto a qualcuno la posizione del villaggio"], "battuta": ["«C'era un campanile, lì. Lo vedete? No. Nemmeno io, più.»", "«Ricordatevi il mio nome. Vi prego. È importante che qualcuno lo ricordi.»", "«Non è morto nessuno. Sono solo andati via tutti insieme. Senza di me.»", "«Il pane di casa mia aveva il sale sopra. Qui nessuno lo fa così.»", "«Se una notte sentite una campana dove non c'è un campanile, non andate.»", "«Avevo una sorella. Credo. Sto cominciando a dimenticare la sua faccia.»"]}], "ambienti3": [{"id": "palude", "label": "Palude", "tipo": "Attraversamento", "nomi": ["Le Pozze Grigie", "L'Acquitrino dei Lamenti", "La Torbiera Nera", "Il Pantano delle Lanterne", "La Bassa dei Salici Annegati", "Le Canne di Mezzanotte"], "desc": ["Acqua nera fino alle ginocchia, alberi morti che sembrano mani, e lucciole che non si comportano come lucciole.", "Una distesa di canne alte e pozze immobili, dove ogni passo affonda e ogni suono arriva da troppo lontano.", "Nebbia bassa, tronchi marci e un odore dolciastro. Sotto la superficie, qualcosa si muove con calma.", "Passerelle di tavole marce corrono da un isolotto all'altro. A metà strada qualcuno ha appeso un campanello, e suona da solo."], "impulsi": ["inghiottire chi si ferma", "nascondere il sentiero", "attirare con false luci", "far perdere l'orientamento", "custodire ciò che vi è affondato", "far marcire le provviste"], "feat": [["Fango che Risucchia", "Passiva", "Chi si muove oltre distanza Prossima in un solo movimento deve superare un Tiro Agilità ({D}) o diventare Trattenuto nel fango finché un alleato non lo tira fuori."], ["Luci Ingannatrici", "Azione", "Spendete una Paura: luci danzanti attirano un PG. Deve superare un Tiro Reazione di Istinto ({D}) o muoversi verso di esse, staccandosi dal gruppo."], ["Sanguisughe", "Reazione", "Quando un PG fallisce un tiro con Paura mentre è nell'acqua, marca uno Stress: qualcosa gli si è attaccato sotto i vestiti, e si stacca solo col fuoco o col sale."], ["Ciò che Riposa sul Fondo", "Azione", "Spendete una Paura: un avversario emerge dall'acqua entro distanza Ravvicinata da un PG e diventa subito protagonista."], ["Isolotti Sicuri", "Passiva", "Qua e là affiorano dossi di terra ferma. Un PG che supera un Tiro Istinto ({D}) traccia un percorso tra di essi: fino alla fine della scena, chi lo segue si muove senza affondare e ha vantaggio ai tiri per attraversare la palude."], ["Gas di Palude", "Azione", "Spendete una Paura: una bolla di gas verdastro affiora accanto a un PG, che marca uno Stress per la nausea. Se c'è una fiamma libera entro distanza Prossima, il gas esplode: tutti entro distanza Prossima devono superare un Tiro Reazione di Agilità ({D}) o subire {DMG} danni fisici. Anche i PG possono farlo esplodere apposta, con una torcia e un buon lancio."]], "domande": ["Che cosa avete perso nella palude l'ultima volta che ci siete passati?", "Quale canzone canticchiate per non sentire i rumori?", "Chi di voi ha già visto queste luci, e cosa è successo?", "Cosa avete visto affiorare dall'acqua e non avete detto agli altri?", "Quale animale della palude avete mangiato per sopravvivere, e che sapore aveva?", "Chi vi ha insegnato a camminare sul fango senza affondare, e cosa vi ha chiesto in cambio?"], "avv": ["Zanzare Giganti", "Melma Verde", "Zombi Barcollante", "Fantasma", "Anguille Elettriche", "Banshee", "Ammaliatore della Lanterna"]}, {"id": "rovine", "label": "Rovine del Vecchio Mondo", "tipo": "Esplorazione", "nomi": ["La Basilica Spezzata", "Le Sale di Cenere", "Il Foro dei Senza Nome", "La Reggia Senza Tetto", "La Scalinata dei Re Minori", "L'Osservatorio Muto"], "desc": ["Colonne spezzate, mosaici di dèi con il volto cancellato, e un silenzio che sembra trattenere il fiato.", "Ciò che resta di una città che credeva di essere eterna: archi, statue, scale che salgono nel vuoto.", "Muri anneriti dal fuoco di un'altra epoca. Sotto le macerie, stanze intatte che nessuno apre da secoli.", "Un'enorme porta di bronzo giace di piatto sull'erba. Sotto di essa si sente scorrere dell'acqua."], "impulsi": ["custodire segreti", "crollare sotto il peso del tempo", "punire i profanatori", "mostrare il passato a chi lo cerca", "attirare i saccheggiatori", "chiudersi alle spalle di chi entra"], "feat": [["Pavimento Marcio", "Reazione", "Quando un PG tira con Paura muovendosi qui, il pavimento cede: deve superare un Tiro Reazione di Agilità ({D}) o cadere al livello inferiore e subire {DMG} danni fisici."], ["Eco del Passato", "Passiva", "Un PG che tocca un muro inciso può effettuare un Tiro Conoscenza ({D}): in caso di successo vede per un istante com'era questo luogo, e nota un dettaglio utile."], ["Saccheggiatori Rivali", "Azione", "Spendete una Paura: un gruppo rivale arriva da un altro ingresso, deciso a prendere ciò che i PG cercano."], ["Guardiano Dimenticato", "Azione", "Spendete una Paura: una statua o un'armatura si anima per proteggere una stanza, e diventa subito protagonista."], ["Meccanismo Antico", "Passiva", "Leve, contrappesi e porte a scomparsa funzionano ancora. Un PG che supera un Tiro Conoscenza ({D}) ne capisce uno e può usarlo una volta per scena: chiudere una porta in faccia a un inseguitore, far cadere una grata, aprire un passaggio. In caso di fallimento il meccanismo scatta lo stesso, ma nel modo sbagliato."], ["Iscrizione che Morde", "Azione", "Spendete una Paura: la scritta più vicina a un PG si accende come brace. Deve superare un Tiro Reazione di Conoscenza ({D}) o marcare uno Stress e restare Vulnerabile finché un alleato non lo chiama per nome."]], "domande": ["Quale dio era adorato qui, e perché ne avete paura?", "Chi della vostra famiglia è morto cercando queste rovine?", "Che cosa sperate di trovare, e cosa temete di trovare?", "Quale leggenda su questo posto si raccontava nel vostro villaggio?", "Quale oggetto di questo luogo è finito, chissà come, nella casa della vostra infanzia?", "Cosa c'era scritto sull'arco d'ingresso, e chi di voi sa leggerlo?"], "avv": ["Tiratore Scheletrico", "Cavaliere Scheletrico", "Armatura Stregata", "Guardiano Spettrale", "Guardia Scelta Tumulata", "Necrosacerdote Tumulato", "Sentinella della Cripta"]}, {"id": "citta", "label": "Quartiere in tensione", "tipo": "Sociale", "nomi": ["Il Vicolo dei Tintori", "La Piazza del Pozzo", "Il Borgo delle Braci", "Il Mercato Coperto", "Il Ponte delle Botteghe", "La Salita dei Cordai"], "desc": ["Bancarelle strette, panni stesi tra le case e cento occhi che fingono di non guardare.", "Un quartiere dove tutti si conoscono, tutti si devono qualcosa, e nessuno parla con gli estranei.", "Strade affollate, guardie nervose, e la sensazione che basti una parola per far scoppiare tutto.", "Un banditore legge un editto che nessuno vuole ascoltare, mentre i bambini gli tirano bucce di cipolla."], "impulsi": ["spettegolare", "proteggere i propri", "approfittare dei forestieri", "esplodere alla prima scintilla", "nascondere i ricercati", "trovare un capro espiatorio"], "feat": [["Mille Occhi", "Passiva", "Qualsiasi cosa i PG facciano in pubblico, entro sera lo sa tutto il quartiere."], ["Folla Agitata", "Azione", "Spendete una Paura: la folla si muove tutta insieme. I PG entro distanza Ravvicinata da un punto scelto devono superare un Tiro Reazione di Forza ({D}) o essere separati dal gruppo."], ["Il Prezzo dell'Informazione", "Passiva", "Chi cerca informazioni qui ha vantaggio al tiro solo se paga, in monete o in favori. Chi non paga ottiene solo voci, e una è falsa."], ["Ronda", "Reazione", "Quando un PG tira con Paura durante un'azione illegale, una pattuglia gira l'angolo."], ["Debito di Strada", "Passiva", "Qui ogni favore viene ricordato. Un PG che aiuta qualcuno del quartiere senza chiedere nulla può, una volta per sessione, chiedere in cambio un nascondiglio, un'informazione o un testimone pronto a giurare il falso."], ["Il Colpevole Perfetto", "Azione", "Spendete una Paura: qualcuno urla che è stato un forestiero. Un PG a scelta diventa il colpevole di qualcosa che non ha fatto; finché non lo chiarisce, ha svantaggio ai Tiri Presenza con la gente del quartiere."]], "domande": ["Chi in questo quartiere vi deve un favore, e chi lo deve a voi?", "Quale odore vi ricorda casa, qui?", "Chi di voi è già stato cacciato da questo posto, e perché?", "Cosa vendono qui che non dovrebbero vendere?", "Quale insegna di bottega vi fa sempre sorridere, e perché?", "Chi comanda davvero, qui, anche se non ha nessun titolo?"], "avv": ["Bandito dei Coltelli Seghettati", "Guardia Armata", "Capo delle Guardie", "Mercante", "Ladro Mascherato", "Spia", "Demone Mutaforma"]}, {"id": "santuario", "label": "Santuario della Pira", "tipo": "Sociale", "nomi": ["Il Cerchio di Brace", "Il Santuario del Fuoco Lento", "La Cappella delle Ceneri", "L'Ultima Fiamma", "La Pira dei Nove Ceppi", "Il Focolare dei Penitenti"], "desc": ["Un fuoco sacro in un cerchio di pietre annerite, e attorno a esso la vita di un villaggio che non osa allontanarsi.", "Un tempio piccolo e fumoso, pieno di candele votive e di persone che pregano a bassa voce.", "Un falò alto quanto una casa, custodito giorno e notte, con l'Umbra che preme ai margini della luce.", "Uomini e donne con le mani bendate si passano ciocchi di legno in fila, uno dopo l'altro, senza fermarsi mai."], "impulsi": ["proteggere chi sta nella luce", "chiedere un prezzo", "diffidare dei forestieri", "tenere viva la fiamma a ogni costo", "giudicare", "trasformare la paura in devozione"], "feat": [["Luce Sacra", "Passiva", "Entro distanza Ravvicinata dal fuoco, le creature dell'Umbra e i morti che tornano hanno svantaggio ai tiri attacco."], ["Offerta Dovuta", "Passiva", "Chi entra nel cerchio senza un'offerta ha svantaggio ai Tiri Presenza con i fedeli."], ["Fiamma che Vacilla", "Azione", "Spendete una Paura: il fuoco si abbassa all'improvviso. Avviate un conto alla rovescia (4): quando si innesca, l'Umbra entra nel cerchio e i fedeli cercano un colpevole."], ["Rito del Respiro", "Passiva", "Se i PG partecipano a un rito per alimentare la fiamma, ognuno può rimuovere uno Stress. Il rito si può fare una sola volta per riposo lungo."], ["Scintille Sospette", "Reazione", "Quando un PG usa la magia in vista del fuoco e tira con Paura, la fiamma prende per un istante il colore del suo incantesimo. Tutti i fedeli l'hanno visto, e qualcuno corre a chiamare i custodi."], ["La Prova della Mano", "Azione", "Spendete una Paura: un custode della Pira chiede a un PG di dimostrare che non è Toccato dall'Umbra tenendo la mano sopra la fiamma. Se rifiuta, i fedeli lo trattano da sospetto. Se accetta, deve superare un Tiro Reazione di Istinto ({D}) o marcare un PF mentre la folla mormora."]], "domande": ["Che offerta portate al fuoco, e che cosa significa per voi?", "Chi avete visto bruciare su una Pira come questa?", "Cosa avete promesso l'ultima volta che avete pregato davvero?", "Chi tra i fedeli vi riconosce, e da dove?", "Che cosa non bruciereste mai, nemmeno per tenere viva la fiamma?", "Chi di voi ha dubitato degli dèi davanti a una Pira, e chi l'ha sentito?"], "avv": ["Guardia Armata", "Capo delle Guardie", "Iniziato del Culto", "Adepto del Culto", "Zanna del Culto", "Spettro Sussurrante", "Campione Consacrato"]}, {"id": "foresta", "label": "Foresta ostile", "tipo": "Esplorazione", "nomi": ["Il Bosco Muto", "La Selva dei Rami Bianchi", "Il Fitto", "La Foresta che Ascolta", "Il Bosco delle Campane di Corteccia", "La Macchia dei Nidi Vuoti"], "desc": ["Alberi così alti che il giorno sembra crepuscolo. Nessun uccello canta, ma qualcosa fischia tra i rami.", "Una foresta dove i sentieri cambiano di notte e i tronchi portano incisioni che nessuno ricorda di aver fatto.", "Radici enormi, muschio luminoso, e l'impressione costante di essere osservati da molto in alto.", "Le cortecce portano segni di artigli più in alto di dove arriva un orso, e il vento sa di resina e di carne."], "impulsi": ["confondere i viandanti", "proteggere i suoi abitanti", "nutrirsi di chi si perde", "ricordare chi l'ha ferita", "tacere all'improvviso", "mettere alla prova chi porta un'ascia"], "feat": [["Sentieri che Cambiano", "Passiva", "Per orientarsi serve un Tiro Istinto ({D}); in caso di fallimento il gruppo si ritrova dove era un'ora prima."], ["Silenzio Improvviso", "Azione", "Spendete una Paura: ogni suono cessa. Fino alla fine della scena i PG non possono parlarsi a voce e hanno svantaggio ai tiri per accorgersi dei pericoli."], ["Rami che Afferrano", "Reazione", "Quando un PG fallisce un tiro con Paura, una radice lo rende Trattenuto finché non supera un Tiro Forza ({D})."], ["Abitanti del Bosco", "Azione", "Spendete una Paura: creature della foresta compaiono entro distanza Lontana e osservano i PG. Non attaccano, per ora: aspettano di vedere cosa faranno."], ["La Lingua degli Alberi", "Passiva", "Un PG che si ferma ad ascoltare e supera un Tiro Istinto ({D}) capisce cosa disturba la foresta: un albero avvelenato, una tana profanata, un cacciatore di troppo. Se i PG rimediano, la foresta li lascia passare: fino all'uscita il gruppo ha vantaggio ai tiri per orientarsi e per nascondersi."], ["Caduta del Gigante", "Azione", "Spendete una Paura: un albero morto si schianta. Chi si trova sulla sua traiettoria, entro distanza Ravvicinata, deve superare un Tiro Reazione di Agilità ({D}) o subire {DMG} danni fisici e restare Trattenuto sotto i rami. Il tronco abbattuto divide il campo in due."]], "domande": ["Cosa vi hanno insegnato da bambini sui boschi come questo?", "Quale albero avete inciso qui, tanto tempo fa?", "Chi di voi sente di essere già stato qui, anche se non è possibile?", "Che cosa lasciate come pegno alla foresta per passare?", "Quale suono, qui, vi ha fatto mettere mano all'arma senza motivo?", "Chi di voi ha fatto un torto a un bosco, e come fa la foresta a saperlo?"], "avv": ["Lupo Terribile", "Soldato Silvano", "Treant Minore", "Giovane Driade", "Valdenhax", "Treant delle Querce", "Driade"]}, {"id": "miniera", "label": "Miniera o sotterraneo", "tipo": "Esplorazione", "nomi": ["La Miniera di Ferrovivo", "Le Gallerie Cantanti", "Il Pozzo Settimo", "La Vena Profonda", "Il Ventre di Granito", "La Discenderia dei Lumi Spenti"], "desc": ["Gallerie strette, travi che scricchiolano e l'eco di picconi che nessuno sta usando.", "Un dedalo di cunicoli scavati in fretta, poi abbandonati in ancora più fretta.", "Aria calda e pesante, cristalli nelle pareti e, in fondo, una luce che non dovrebbe esserci.", "Un montacarichi pende di traverso sopra un pozzo senza fondo, e la catena oscilla anche se non c'è vento."], "impulsi": ["crollare", "inghiottire la luce", "nascondere ciò che è stato trovato", "far perdere la strada", "risvegliare ciò che dorme", "separare chi scende da chi resta sopra"], "feat": [["Crollo", "Azione", "Spendete una Paura: il soffitto cede. I PG entro distanza Prossima da un punto scelto devono superare un Tiro Reazione di Agilità ({D}) o subire {DMG} danni fisici; il passaggio alle loro spalle è bloccato."], ["Buio Totale", "Passiva", "Senza una fonte di luce, ogni tiro per vedere, orientarsi o reagire ha svantaggio."], ["Aria Cattiva", "Reazione", "Quando un PG tira con Paura in una galleria profonda, marca uno Stress: l'aria è irrespirabile, e le fiamme diventano azzurre."], ["Vena Preziosa", "Passiva", "Con un Tiro Conoscenza ({D}) un PG riconosce un filone prezioso: vale una manciata d'oro, se riescono a portarlo fuori."], ["Carrelli e Binari", "Passiva", "I vecchi binari scendono ancora in pendenza. Un PG che supera un Tiro Astuzia ({D}) libera un carrello: può usarlo per fuggire, per trasportare un ferito o per lanciarlo lungo la galleria, e ogni avversario sulla sua strada subisce {DMG} danni fisici."], ["Eco Bugiarda", "Azione", "Spendete una Paura: un rumore rimbalza nei cunicoli e sembra arrivare da dietro il gruppo. Ogni PG che non supera un Tiro Reazione di Istinto ({D}) si volta dalla parte sbagliata: il prossimo attacco contro di lui ha vantaggio."]], "domande": ["Chi conoscete che è sceso qui e non è risalito?", "Quale rumore vi spaventa più del buio?", "Cosa cercavano i minatori, davvero?", "Chi di voi ha già lavorato in un posto come questo?", "Quale canto dei minatori conoscete, e chi ve l'ha insegnato?", "Cosa vi hanno detto di non toccare mai, quaggiù?"], "avv": ["Ogre di Caverna", "Ragnetti Tessombra", "Melma Verde", "Mangiaruggine", "Spettro di Pietra", "Titano di Pietra", "Elementale Maggiore della Terra"]}, {"id": "campo", "label": "Accampamento nemico", "tipo": "Attraversamento", "nomi": ["Il Campo dei Lupi", "Le Tende Rosse", "Il Forte di Pali", "Il Bivacco della Cenere", "Il Recinto dei Corvi", "La Radura delle Lance Piantate"], "desc": ["Tende, fuochi, cani e sentinelle annoiate. Al centro, un padiglione più grande degli altri.", "Una palizzata di tronchi appuntiti, un cancello sorvegliato e troppa gente armata per essere un caso.", "Un campo di predoni allestito tra le rovine di una fattoria. Si beve, si gioca, e ogni tanto qualcuno urla.", "Fumo di carne arrosto, risate sguaiate e, da qualche parte dietro le tende, un fabbro che batte senza sosta."], "impulsi": ["sorvegliare", "dare l'allarme", "festeggiare", "punire i traditori", "spartire il bottino", "lasciar passare chi sembra uno di loro"], "feat": [["Sentinelle", "Passiva", "Muoversi senza essere visti richiede un Tiro Astuzia ({D}); con un fallimento con Paura, qualcuno grida."], ["Allarme", "Azione", "Spendete una Paura: suona il corno. Avviate un conto alla rovescia (3): quando si innesca, tutto il campo è in armi."], ["Cani da Guardia", "Reazione", "Quando un PG si avvicina con il vento alle spalle, i cani ne sentono l'odore e abbaiano: la sentinella più vicina si gira."], ["Prigionieri", "Passiva", "Ci sono prigionieri legati al palo. Liberarli dà alleati, ma rallenta la fuga."], ["Il Campione del Campo", "Azione", "Spendete una Paura: il più grosso del campo sfida a gran voce uno dei PG, per gioco o perché l'ha riconosciuto. Tutti si girano a guardare. Se il PG accetta, nessuno interviene finché il duello dura; se rifiuta, il campo intero gli è addosso."], ["Fuoco tra le Tende", "Passiva", "Tende, foraggio e botti d'olio bruciano in fretta. Un PG che appicca un incendio crea un diversivo: per il resto della scena i tiri per muoversi Nascosti hanno vantaggio. Ma il fuoco non sceglie, e anche ciò che i PG cercano potrebbe bruciare."]], "domande": ["Chi conoscete tra i prigionieri?", "Quale bandiera sventola sul padiglione, e cosa vi ricorda?", "Chi di voi ha già vissuto in un campo come questo?", "Cosa vi hanno rubato queste persone?", "Chi di voi ha un debito con il capo di questo campo?", "Quale canzone cantano attorno al fuoco, e perché la conoscete anche voi?"], "avv": ["Bandito dei Coltelli Seghettati", "Cecchino dei Coltelli Seghettati", "Luogotenente dei Coltelli Seghettati", "Mercenario", "Drappello di Arcieri", "Berserker Alfa", "Gigante Lottatore"]}, {"id": "tempesta", "label": "Tempesta d'Umbra", "tipo": "Evento", "nomi": ["La Tempesta di Colori", "Il Fronte Nero", "La Notte Senza Fuochi", "Il Vento delle Voci", "La Marea Viola", "L'Ora dei Ritornati"], "desc": ["Il cielo cambia colore all'orizzonte e il vento porta voci che chiamano per nome.", "Una muraglia di nubi viola avanza più veloce di un cavallo. Dove passa, le ombre si allungano.", "La luce si spegne a ondate. Nel buio, le forme dei morti camminano accanto ai vivi.", "Il vento si ferma di colpo. Poi tutte le fiamme si piegano nella stessa direzione, come se qualcuno le chiamasse."], "impulsi": ["inghiottire la luce", "corrompere", "separare", "chiamare i morti", "mettere alla prova la speranza", "cancellare i sentieri e i ricordi"], "feat": [["Ondata d'Umbra", "Azione", "Spendete una Paura: ogni PG che non è vicino a una fonte di luce sacra deve superare un Tiro Reazione di Istinto ({D}) o marcare 2 Stress."], ["Voci Familiari", "Reazione", "Quando un PG tira con Paura, sente la voce di qualcuno che ha perso. Se la segue, si separa dal gruppo."], ["Rifugio", "Passiva", "C'è una casa, una grotta o una Pira dove ripararsi. Il gruppo deve completare un Conto alla Rovescia di Progresso (4) per raggiungerla; avanza a ogni tiro riuscito per orientarsi, proteggersi o portare avanti i più deboli."], ["Ciò che Cammina nella Tempesta", "Azione", "Spendete 2 Paure: un avversario dell'Umbra compare entro distanza Lontana e diventa subito protagonista."], ["Il Ritmo delle Ondate", "Passiva", "La tempesta pulsa come un cuore. Un PG che supera un Tiro Istinto ({D}) ne capisce il ritmo: fino alla fine della scena, lui e chi lo segue hanno vantaggio ai Tiri Reazione contro la tempesta."], ["Lampo Senza Colore", "Azione", "Spendete una Paura: un lampo pallido cade dove si trova un PG. Lui e chiunque entro distanza Prossima devono superare un Tiro Reazione di Agilità ({D}) o subire {DMG} danni magici. Per il resto della scena, le ombre dei colpiti si muovono in ritardo."]], "domande": ["Di chi è la voce che sentite nel vento?", "Cosa avete giurato di fare se la tempesta vi avesse risparmiati, l'ultima volta?", "Quale ricordo vi tiene a galla quando la luce si spegne?", "Chi di voi ha già visto qualcuno portato via dalla tempesta?", "Cosa vi siete legati addosso per non lasciarlo alla tempesta?", "Quale preghiera agli dèi velati recitate anche se non ci credete più?"], "avv": ["Zombi Barcollante", "Guardiano Spettrale", "Arciere Spettrale", "Teschio del Caos", "Urco", "Spettro Sussurrante", "Legione Macabra"]}, {"id": "ponte", "label": "Ponte sospeso in rovina", "tipo": "Attraversamento", "nomi": ["Il Ponte delle Mille Funi", "La Passerella del Vento", "Il Filo dell'Abisso", "Il Ponte dei Pellegrini Caduti", "La Catena di Mezzo", "Il Varco delle Assi Rotte"], "desc": ["Tavole grigie legate con corde sfilacciate, sospese sopra una gola così profonda che il fiume, laggiù, sembra un capello d'argento.", "Il ponte geme a ogni raffica e ondeggia come un'amaca. A metà mancano tre assi di fila.", "Due catene arrugginite reggono ciò che resta di un ponte di pietra: lastre che dondolano nel vuoto, tenute insieme da fil di ferro e speranza.", "Centinaia di nastri votivi sbiaditi sono annodati alle funi, e frusciano tutti insieme quando qualcuno mette piede sulla prima asse."], "impulsi": ["punire chi corre", "costringere a guardare in basso", "dividere chi attraversa", "spezzarsi nel momento peggiore", "amplificare ogni passo", "portare via ciò che non è legato"], "feat": [["Ogni Passo Conta", "Passiva", "Chi attraversa piano non deve tirare. Chi corre, combatte o porta qualcuno in spalla sul ponte deve superare un Tiro Agilità ({D}) a ogni spostamento, o resta aggrappato a ciò che trova e diventa Vulnerabile finché non si rimette in piedi."], ["La Fune Cede", "Azione", "Spendete una Paura: uno dei sostegni principali si spezza e il ponte si inclina di colpo. Ogni creatura sul ponte deve superare un Tiro Reazione di Agilità ({D}) o scivolare oltre il bordo e restare appesa nel vuoto. Per risalire serve un Tiro Forza ({D}) o la mano di un alleato."], ["Raffica", "Azione", "Spendete una Paura: un colpo di vento attraversa la gola. Ogni PG sul ponte sceglie se lasciar volare via un oggetto che tiene in mano o marcare uno Stress per tenerlo stretto. Fino alla fine del turno, tutti gli attacchi a distanza hanno svantaggio."], ["Asse Spaccata", "Reazione", "Quando un PG tira con Paura sul ponte, un'asse si spacca proprio davanti o dietro di lui: si apre un buco largo un salto. Chi vuole superarlo deve fare un Tiro Agilità ({D})."], ["Tagliare i Ponti", "Passiva", "Il ponte è un'arma per chi sta su una sponda. Un PG che raggiunge un'estremità può tagliare i sostegni: chi è ancora sopra, amici compresi, deve superare un Tiro Reazione di Agilità ({D}) o sbattere contro la parete insieme al ponte e subire {DMG} danni fisici. Nessun inseguitore passerà più da qui."], ["Nidi nella Parete", "Azione", "Spendete una Paura: dalle pareti della gola si alzano in volo creature disturbate dal rumore. Compaiono entro distanza Ravvicinata dal PG più lontano da una sponda e diventano subito protagoniste."]], "domande": ["Chi di voi soffre di vertigini, e come fa a nasconderlo agli altri?", "Cosa avete visto cadere da questo ponte senza sentirlo arrivare in fondo?", "Chi lo ha costruito, secondo le storie, e che prezzo ha pagato?", "Cosa lascereste andare per primo, se doveste alleggerirvi in fretta?", "Chi vi aspetta dall'altra parte, e perché non può venire lui da voi?", "Quale preghiera, battuta o filastrocca recitate quando mettete piede sulla prima asse?"], "avv": ["Arpia", "Falco", "Cecchino dei Coltelli Seghettati", "Stormo di Diavoli Piumati", "Aquila Gigante", "Gargoyle", "Roc"]}, {"id": "cimitero", "label": "Cimitero dove i morti tornano", "tipo": "Evento", "nomi": ["Il Campo delle Croci Storte", "Il Giardino dei Sepolti Due Volte", "Il Prato dei Nomi Graffiati", "La Collina delle Lapidi Calde", "Il Chiostro delle Ossa Inquiete", "L'Ossario del Lume Spento"], "desc": ["La terra di una fossa fresca si gonfia e si sgonfia piano, come un petto che respira.", "Lapidi inclinate in tutte le direzioni, fiori secchi e una pala piantata a metà lavoro, col manico ancora caldo.", "Campanelle di ferro pendono dalle tombe, legate a fili che scendono sotto terra. Stanotte qualcuna suona.", "Nebbia all'altezza delle caviglie e, tra le tombe, impronte di piedi nudi che vanno tutte verso il cancello."], "impulsi": ["restituire ciò che è stato sepolto", "reclamare i vivi come fossero suoi", "ricordare ogni torto", "chiamare per nome", "trattenere chi scava", "tornare a casa"], "feat": [["Il Risveglio", "Passiva", "Avviate un Conto alla Rovescia (6) all'inizio della scena: avanza ogni volta che un PG tira con Paura, e a ogni avanzamento una tomba si apre. Quando si innesca, tutti i morti del cimitero sono in piedi e marciano verso le case dei vivi."], ["Mani dalla Terra", "Azione", "Spendete una Paura: mani grigie spuntano dal terreno attorno a un punto. Ogni PG entro distanza Prossima deve superare un Tiro Reazione di Agilità ({D}) o subire {DMG} danni fisici e diventare Trattenuto. Per liberarsi serve un Tiro Forza ({D}) o un alleato che tagli le dita."], ["Un Volto Conosciuto", "Azione", "Spendete una Paura: tra i morti in piedi, un PG riconosce qualcuno che ha amato o tradito. Marca uno Stress, e finché quel morto cammina ha svantaggio ai tiri per colpirlo."], ["Terra Benedetta", "Passiva", "Alcune tombe portano ancora i segni di una benedizione. Un PG che supera un Tiro Conoscenza ({D}) le riconosce: entro distanza Prossima da esse i morti non entrano, e chi vi si rifugia può riprendere fiato."], ["Rimettere a Riposo", "Passiva", "Ogni morto torna per un motivo: un nome sbagliato sulla lapide, un anello rubato dalla bara, una promessa non mantenuta. Un PG che scopre il motivo di un morto e lo soddisfa lo fa ricadere a terra senza combattere, e ottiene una Speranza."], ["Fossa Aperta", "Reazione", "Quando un PG tira con Paura muovendosi tra le tombe, il terreno cede e lui finisce in una fossa, Vulnerabile, con qualcosa che si muove sotto le assi della bara."]], "domande": ["Chi di voi ha qualcuno sepolto qui, e cosa c'è scritto sulla sua lapide?", "Cosa avete messo nella bara di qualcuno, e perché ora vi preoccupa?", "Quale usanza funebre del vostro popolo i morti di qui non hanno ricevuto?", "Chi vi ha insegnato a riconoscere un morto che sta per tornare?", "Cosa promettete ai morti perché restino sotto terra?", "Quale morto non vorreste mai vedere rialzarsi, e perché?"], "avv": ["Zombi Marcio", "Zombi Barcollante", "Orda di Zombi", "Guerriero Scheletrico", "Fantasma", "Cacciatore di Mortali", "Dullahan"]}, {"id": "mercato", "label": "Mercato nero sotterraneo", "tipo": "Sociale", "nomi": ["Il Mercato delle Fogne Asciutte", "La Fiera del Sottosuolo", "Il Bazar dei Senza Lanterna", "Il Pozzo dei Baratti", "La Cripta dei Prezzi Giusti", "Il Mercato dei Topi d'Oro"], "desc": ["Bancarelle ricavate dentro vecchie nicchie funerarie, lumi a olio coperti di stoffa rossa, e prezzi detti sottovoce, mai scritti.", "Un canale prosciugato pieno di gente incappucciata. Si paga in monete, in segreti, in giorni di lavoro.", "Gabbie coperte che respirano, barattoli che bisbigliano, e un uomo che vende lingue, solo lingue, senza dire di cosa.", "Fumo dolce di pipa, odore di muffa e di spezie rare. Ogni tanto la volta trema: sopra, passa un carro."], "impulsi": ["vendere qualunque cosa a chiunque", "far pagare il doppio a chi ha fretta", "difendere la regola del silenzio", "sparire alla prima torcia della ronda", "trasformare un affare in un debito", "tenere d'occhio chi fa troppe domande"], "feat": [["La Legge del Mercato", "Passiva", "Qui non si sguainano armi. Chi lo fa per primo diventa nemico di tutti: le bancarelle chiudono e chiunque ha un motivo per colpirlo. Chi viene aggredito senza aver aggredito gode invece della protezione del mercato."], ["Merce Introvabile", "Passiva", "Qui si trova quasi tutto: un veleno raro, un lasciapassare, una mappa, il nome di un traditore. Un PG che supera un Tiro Presenza ({D}) trova chi lo vende. Il prezzo non è mai solo in monete: un favore, un ricordo, un oggetto a cui tiene."], ["Mani Leste", "Reazione", "Quando un PG tira con Paura in mezzo alla folla, si accorge che gli manca qualcosa: una borsa, un'arma secondaria, una lettera. Il ladro è già a distanza Ravvicinata, e corre."], ["Retata", "Azione", "Spendete una Paura: dal pozzo d'ingresso arrivano fischietti. Avviate un conto alla rovescia (3): quando si innesca, le guardie scendono e arrestano chiunque sia ancora qui. I mercanti spariscono da uscite che i PG non conoscono, e qualcuno gliele mostra solo a pagamento."], ["Asta al Rialzo", "Azione", "Spendete una Paura: qualcuno offre di più per la stessa cosa che vogliono i PG. È disposto a rilanciare ancora, e se perde li aspetterà fuori."], ["Il Padrone Vuole Parlarvi", "Azione", "Spendete una Paura: un emissario di chi comanda il mercato invita un PG a bere qualcosa, adesso, in una stanza sul retro. Rifiutare non è previsto: chi rifiuta avrà svantaggio ai Tiri Presenza con tutti i mercanti fino a quando non si scusa."]], "domande": ["Chi di voi ha già venduto qualcosa qui, e di cosa si è pentito?", "Quale oggetto vedete su una bancarella che dovrebbe trovarsi a casa vostra?", "Qual è la parola d'ordine per entrare, e chi ve l'ha data?", "Chi vi deve dei soldi, quaggiù, e si nasconde da voi?", "Cosa non comprereste mai, nemmeno se vi salvasse la vita?", "Quale voce gira su di voi tra i mercanti?"], "avv": ["Mercante", "Ombra dei Coltelli Seghettati", "Ladro Mascherato", "Assassino Avvelenatore", "Magnate", "Spia", "Demone dell'Avarizia"]}, {"id": "piena", "label": "Fiume in piena o guado", "tipo": "Attraversamento", "nomi": ["Il Guado dei Sassi Bianchi", "La Bocca del Torrente", "Il Passo dell'Acqua Rossa", "Il Fiume Senza Ponte", "Le Rapide del Mulino Vecchio", "Il Guado delle Corde"], "desc": ["L'acqua color fango corre più veloce di un cavallo, trascinando rami, steccati e una culla vuota.", "Il rombo copre ogni voce. Le pietre del guado si vedono appena, lucide e scure, a un salto l'una dall'altra.", "Sulla riva opposta, case basse con l'acqua alle finestre e qualcuno che agita un panno dal tetto.", "Piove da tre giorni. Il fiume si è già mangiato metà della strada, e ora assaggia l'altra metà."], "impulsi": ["trascinare via", "separare le due rive", "salire senza preavviso", "portare a galla ciò che era sepolto", "spezzare le corde", "restituire i corpi più a valle"], "feat": [["Corrente", "Passiva", "Chi è in acqua senza un appiglio deve superare un Tiro Forza ({D}) ogni volta che agisce, o viene trascinato a valle fino a distanza Lontana."], ["Corda Tesa", "Passiva", "Un PG che porta una corda sull'altra riva e la fissa con un Tiro Agilità ({D}) o un Tiro Forza ({D}) crea un passaggio: chi attraversa aggrappato ha vantaggio a ogni tiro contro la corrente."], ["Relitto alla Deriva", "Azione", "Spendete una Paura: un tronco, un carro o un pezzo di tetto arriva a tutta velocità. Un PG in acqua o sul guado deve superare un Tiro Reazione di Agilità ({D}) o subire {DMG} danni fisici e perdere l'appiglio."], ["Ondata di Piena", "Azione", "Spendete una Paura: l'acqua si alza di un palmo, poi di un braccio. Avviate un conto alla rovescia (3): quando si innesca il guado sparisce, e chi non ha raggiunto una riva si ritrova in acqua alta."], ["Grida dalla Corrente", "Reazione", "Quando un PG tira con Paura vicino all'acqua, sente qualcuno chiedere aiuto più a valle: un bambino, un animale, un nemico ferito. Aiutarlo costa tempo; ignorarlo costa uno Stress."], ["Ciò che Porta la Piena", "Passiva", "Il fiume ha scoperchiato cantine e magazzini. Un PG che setaccia la riva e supera un Tiro Istinto ({D}) trova qualcosa di utile incastrato tra i rami: una cassa sigillata, un'arma, una barca rovesciata ma ancora buona."]], "domande": ["Chi di voi non sa nuotare, e lo ha detto agli altri?", "Cosa avete giurato di non lasciare mai indietro, anche se pesa troppo?", "Chi vive sull'altra riva, e perché dovete arrivarci oggi?", "Quale storia raccontano i barcaioli su ciò che abita questo fiume?", "Cosa avete perso in un'altra piena, tanto tempo fa?", "Come chiamate il fiume quando siete arrabbiati con lui?"], "avv": ["Kelpie", "Bestia Branchiata Dentisega", "Zombi Marcio", "Anguille Elettriche", "Ammaliatore della Lanterna", "Elementale Maggiore dell'Acqua", "Madre delle Acque"]}, {"id": "monastero", "label": "Monastero assediato", "tipo": "Evento", "nomi": ["L'Eremo delle Sette Campane", "Il Chiostro del Silenzio Rotto", "La Rocca dei Fratelli Grigi", "Il Convento sul Dente", "L'Abbazia delle Api", "Il Romitorio della Pira Alta"], "desc": ["Mura alte, porta sprangata, e dalle feritoie i monaci lanciano tegole, pentole e preghiere.", "Le campane suonano senza sosta. Fuori, nel campo d'orzo, qualcosa si raduna in silenzio.", "Monaci con la tonaca rimboccata corrono con secchi d'acqua, mentre un vecchio bibliotecario impenna frecce con le pagine di un libro sacro.", "Il cortile è pieno di contadini rifugiati, capre e bambini. Sulle mura ci sono più torce che uomini."], "impulsi": ["resistere fino all'alba", "cedere nel punto più debole", "trasformare ogni oggetto in un'arma", "costringere a scegliere chi salvare", "custodire ciò che gli assedianti vogliono", "aprire una porta dall'interno"], "feat": [["L'Assalto", "Passiva", "Avviate un Conto alla Rovescia di Conseguenza (5): avanza ogni volta che un PG tira con Paura. Quando si innesca, le mura cedono in un punto e la battaglia entra nel cortile."], ["Scale alle Mura", "Azione", "Spendete una Paura: una scala si appoggia ai merli entro distanza Ravvicinata da un PG. Se nessuno la respinge con un Tiro Forza ({D}) prima del prossimo turno del GM, ne salgono degli assedianti."], ["Tutti alle Armi", "Passiva", "Monaci e rifugiati sono spaventati, ma pronti. Un PG che supera un Tiro Presenza ({D}) li organizza: una volta per scena respingono da soli un assalto nel punto scelto dai PG, e chi li guida ottiene una Speranza."], ["Fuoco sul Tetto", "Azione", "Spendete una Paura: frecce incendiarie piovono sulla biblioteca, sul granaio o sulla cappella (scegliete voi). Se i PG non intervengono entro la fine della scena, quel luogo è perduto con tutto ciò che contiene."], ["La Sbarra Segata", "Reazione", "Quando un PG tira con Paura vicino alla porta principale, si accorge che la sbarra è stata segata fino a metà. Qualcuno, dentro, vuole far entrare gli assedianti."], ["Le Cantine dei Monaci", "Passiva", "Sotto il monastero corrono cantine e un vecchio passaggio che sbuca lontano dalle mura. Un PG che supera un Tiro Conoscenza ({D}) o un Tiro Istinto ({D}) lo trova: può servire per fuggire, per portare fuori i rifugiati o per colpire gli assedianti alle spalle."]], "domande": ["Chi di voi è cresciuto tra mura come queste?", "Cosa custodiscono i monaci che gli assedianti vogliono a ogni costo?", "Quale monaco vi ha salvato la vita una volta, e ora è troppo vecchio per combattere?", "Perché vi siete chiusi dentro invece di scappare quando potevate?", "Cosa portereste via per primo, se il monastero dovesse cadere?", "Chi tra gli assedianti conoscete per nome?"], "avv": ["Orda di Zombi", "Coscritto", "Drappello di Arcieri", "Cavaliere del Reame", "Capitano Spettrale", "Figli della Notte", "Legione di Zombi"]}, {"id": "festa", "label": "Corte di un nobile in festa", "tipo": "Sociale", "nomi": ["La Villa delle Fontane Accese", "Il Palazzo dei Cento Specchi", "La Corte del Banchetto Lungo", "Il Giardino delle Maschere", "La Sala del Lampadario Nero", "La Tenuta delle Viti d'Argento"], "desc": ["Musica d'archi, calici che non restano mai vuoti e un pavimento così lucido che ci si specchia la paura degli ospiti.", "Maschere dorate, risate troppo forti, e camerieri che si muovono come soldati.", "Un pavone bianco passeggia tra le tavole imbandite. Nessuno guarda verso la finestra, dove il cielo ha il colore sbagliato.", "Lampadari a cento bracci, arazzi di cacce antiche e, in fondo alla sala, uno scranno vuoto con il cuscino ancora caldo."], "impulsi": ["giudicare dall'aspetto", "trasformare un insulto in un duello", "nascondere il marcio sotto l'oro", "comprare chiunque", "spettegolare a mezza voce", "ignorare il mondo che muore là fuori"], "feat": [["L'Etichetta", "Passiva", "Chi non conosce le regole della corte ha svantaggio ai Tiri Presenza con i nobili. Un PG che supera un Tiro Conoscenza ({D}) sa come comportarsi, e per il resto della scena lo sa anche chi gli sta accanto."], ["Pettegolezzo Utile", "Passiva", "Ogni ospite sa qualcosa di un altro. Un PG che passa una portata a chiacchierare e supera un Tiro Presenza ({D}) scopre un segreto da usare come leva su un nobile presente."], ["Il Guanto", "Azione", "Spendete una Paura: un nobile offeso, a torto o a ragione, schiaffeggia un PG con un guanto. Rifiutare è un disonore per tutto il gruppo; accettare significa combattere fino al primo sangue davanti a tutti."], ["Veleno nel Calice", "Azione", "Spendete una Paura: un ospite importante beve e impallidisce. Avviate un conto alla rovescia (3): se nessuno trova l'antidoto o il colpevole prima che si inneschi, la vittima crolla, e tutti gli sguardi vanno sui forestieri."], ["La Parola Sbagliata", "Reazione", "Quando un PG tira con Paura in una conversazione, dice la cosa sbagliata alla persona sbagliata: la sala tace per un lungo istante, e un nobile diventa suo nemico dichiarato per il resto della serata."], ["Dietro gli Arazzi", "Passiva", "Il palazzo è pieno di corridoi di servizio. Un PG vestito da servitore, o che supera un Tiro Astuzia ({D}), si sposta tra le stanze senza essere notato e può origliare ciò che si dice nelle sale private."]], "domande": ["Chi di voi è stato invitato davvero, e chi si è imbucato?", "Quale nobile presente ha rovinato la vita a qualcuno che amate?", "Cosa indossate stasera, e a chi l'avete preso in prestito?", "Quale piatto vi ricorda una casa che non c'è più?", "Cosa festeggia il padrone di casa, ufficialmente, e cosa invece in segreto?", "Chi di voi sa ballare, e chi finge?"], "avv": ["Cortigiano", "Nobile Minore", "Duellante Arcano", "Consigliere di Corte", "Dignitario", "Maestro Assassino", "Vampiro Dominante"]}, {"id": "quarantena", "label": "Villaggio in quarantena", "tipo": "Sociale", "nomi": ["Il Borgo Chiuso", "La Contrada delle Porte Inchiodate", "Il Villaggio delle Croci Bianche", "Le Case di Calce", "Il Paese del Fumo Amaro", "La Valle dei Pozzi Murati"], "desc": ["Ogni porta ha una croce di gesso, alcune ne hanno due. Dalle finestre, occhi che seguono ogni vostro passo.", "Una barricata di carri rovesciati sbarra la strada, e un uomo con una balestra e un fazzoletto sulla bocca vi ordina di fermarvi.", "Falò di erbe amare a ogni incrocio, campane mute e, in piazza, una lista di nomi che si allunga ogni mattina.", "Il fornaio passa il pane con una pala lunga tre metri. Nessuno si tocca, nessuno si guarda negli occhi."], "impulsi": ["tenere fuori il contagio", "cercare un colpevole", "nascondere i malati", "barattare la vita con il silenzio", "temere qualsiasi forestiero", "scappare di notte"], "feat": [["Il Cordone", "Passiva", "Nessuno entra, nessuno esce. Passare la barricata richiede un permesso, un inganno o un Tiro Astuzia ({D}) col favore del buio. Chi viene sorpreso a passare è trattato come un appestato."], ["Il Contagio", "Reazione", "Quando un PG tira con Paura toccando un malato, un cadavere o qualcosa che gli è appartenuto, marca uno Stress. Se gli succede una seconda volta, ha svantaggio ai Tiri Forza fino al prossimo riposo lungo."], ["Caccia all'Untore", "Azione", "Spendete una Paura: la gente ha deciso chi è il colpevole. Una folla con forconi e torce marcia verso una casa, una persona o un PG. Se nessuno la ferma, prima di sera brucerà qualcosa."], ["La Causa Nascosta", "Passiva", "Il male ha una causa che si può trovare: un pozzo avvelenato, una carcassa nel canale, un oggetto maledetto. Avviate un Conto alla Rovescia di Progresso (3): avanza ogni volta che un PG indaga e tira con Speranza, e quando si innesca i PG sanno come fermare il contagio."], ["Fuga nella Notte", "Azione", "Spendete una Paura: una famiglia tenta di forzare il cordone e supplica i PG di aiutarla. Le guardie hanno l'ordine di tirare a vista, su chiunque."], ["Chi Porta Speranza", "Passiva", "Chi porta cibo, medicine o notizie dal mondo di fuori viene accolto come un santo: ha vantaggio ai Tiri Presenza con gli abitanti per il resto della scena."]], "domande": ["Chi di voi ha già visto questo male, e dove?", "Chi avete lasciato fuori dal cordone, e vi sta aspettando?", "Quale rimedio della nonna conoscete, e funziona davvero?", "Perché siete entrati, sapendo che uscire sarebbe stato difficile?", "Chi in questo villaggio vi deve la vita, e chi vi incolpa?", "Cosa sareste disposti a bruciare per fermare il contagio?"], "avv": ["Teppista Comune", "Guardia Armata", "Capo delle Guardie", "Branco di Ratti", "Zombi Barcollante", "Alveare Ambulante", "Araldo della Pestilenza"]}, {"id": "cenere", "label": "Deserto di cenere", "tipo": "Attraversamento", "nomi": ["La Piana Grigia", "Il Mare di Fuliggine", "Le Dune Spente", "La Distesa dei Camini Morti", "Il Campo delle Statue di Carbone", "La Landa del Vento Caldo"], "desc": ["Cenere fino alle caviglie, morbida come farina, e un orizzonte che tremola di calore anche se il sole non si vede.", "Tronchi carbonizzati piantati come dita. Sotto la crosta grigia, il terreno è ancora tiepido.", "Il vento solleva vortici di polvere nera che danzano da soli. In bocca, sapore di ferro e di fumo.", "Una città intera ridotta a sagome: sui muri superstiti restano impresse le ombre di persone che non ci sono più."], "impulsi": ["seppellire le tracce", "accecare", "togliere il fiato", "nascondere le braci sotto la crosta", "far sembrare ogni direzione uguale", "conservare l'ultimo istante dei morti"], "feat": [["La Traversata", "Passiva", "Il gruppo deve completare un Conto alla Rovescia di Progresso (5) per attraversare la piana. Ogni volta che il conto avanza, ogni PG deve bere una razione d'acqua o marcare uno Stress."], ["Crosta Sottile", "Reazione", "Quando un PG tira con Paura camminando, la crosta di cenere cede su una sacca di braci: deve superare un Tiro Reazione di Agilità ({D}) o subire {DMG} danni fisici."], ["Turbine Nero", "Azione", "Spendete una Paura: un turbine di cenere investe il gruppo. Fino alla fine della scena nessuno vede oltre distanza Prossima, e ogni PG deve superare un Tiro Reazione di Forza ({D}) o venire spinto lontano dagli altri."], ["L'Ultimo Istante", "Passiva", "Sagome di persone e animali sono impresse su sassi e tronchi, ferme nell'ultimo gesto. Un PG che le studia e supera un Tiro Istinto ({D}) capisce dove stavano fuggendo: verso un rifugio, un pozzo o un deposito che c'è ancora."], ["Ciò che Nuota nella Cenere", "Azione", "Spendete una Paura: la cenere si gonfia come un'onda e qualcosa nuota verso il gruppo da sotto la superficie. Compare entro distanza Ravvicinata da un PG e diventa subito protagonista."], ["Vetro Nero", "Passiva", "Dove il fuoco è stato più forte, la sabbia si è fatta vetro nero e tagliente. Un PG che ne raccoglie può ricavarne punte o specchi: una volta per scena ha vantaggio a un tiro per abbagliare, segnalare a distanza o ferire."]], "domande": ["Cosa c'era qui prima del fuoco, secondo chi ve l'ha raccontato?", "Chi di voi ha visto questo fuoco arrivare, e cosa è riuscito a salvare?", "Con cosa vi coprite la bocca, e chi ve l'ha cucito?", "Quale canzone cantate per tenere il passo quando l'orizzonte sparisce?", "Cosa avete promesso di riportare indietro da questa traversata?", "Chi di voi sa trovare l'acqua dove non ce n'è, e chi gliel'ha insegnato?"], "avv": ["Melma Rossa", "Elementale Minore del Fuoco", "Scorpione Gigante", "Squalo di Terra", "Verme delle Sabbie", "Titano del Fuoco", "Drago Vulcanico: Tiranno della Cenere"]}, {"id": "torre", "label": "Torre del mago abbandonata", "tipo": "Esplorazione", "nomi": ["La Torre Storta", "La Guglia dei Vetri Viola", "La Torre del Maestro Assente", "La Spirale di Ardesia", "La Torre che Conta i Gradini", "Il Faro dei Libri"], "desc": ["Una torre inclinata come un dito che indica qualcosa all'orizzonte. Le finestre si accendono una alla volta, dal basso verso l'alto.", "Dentro, le scale salgono più a lungo di quanto la torre sia alta, e i ritratti seguono chi passa con gli occhi.", "Libri aperti su ogni gradino, tazze di tè ancora calde e una scopa che spazza da sola lo stesso angolo, da anni.", "Polvere che cade verso l'alto, un orologio che batte all'indietro e un odore di pergamena bruciata che non va via."], "impulsi": ["mettere alla prova chi sale", "riordinarsi quando nessuno guarda", "proteggere il lavoro del maestro", "far scattare incantesimi dimenticati", "ingannare con le proprie stanze", "cercarsi un nuovo padrone"], "feat": [["Stanze che Cambiano", "Passiva", "Ogni volta che i PG tornano sui propri passi, la stanza non è più quella di prima. Per raggiungere la cima il gruppo deve completare un Conto alla Rovescia di Progresso (5): avanza di 1 a ogni tiro riuscito per salire, e di 2 se il tiro sfrutta qualcosa scoperto nella torre."], ["Grimori Sbadati", "Passiva", "Una volta per scena, un PG può sfogliare i libri e superare un Tiro Conoscenza ({D}) per imparare un trucco della torre: una parola che apre una porta, ferma un servitore animato o accende una luce che non si spegne. In caso di fallimento, legge ad alta voce la pagina sbagliata."], ["Servitori Fedeli", "Azione", "Spendete una Paura: oggetti animati (armature, scope, statue, sedie) si radunano per cacciare gli intrusi. Compaiono entro distanza Ravvicinata da un PG e diventano subito protagonisti."], ["Glifo di Guardia", "Reazione", "Quando un PG tira con Paura aprendo una porta, un cassetto o un libro, un glifo nascosto esplode: lui e chi gli sta entro distanza Prossima devono superare un Tiro Reazione di Agilità ({D}) o subire {DMG} danni magici."], ["Incantesimo a Metà", "Azione", "Spendete una Paura: un incantesimo lasciato in sospeso si risveglia. Scegliete: la gravità si capovolge e chi non supera un Tiro Reazione di Agilità ({D}) cade verso il soffitto e subisce {DMG} danni fisici; oppure l'eco del vecchio maestro pone una domanda a un PG, e se la risposta non lo convince il PG marca 2 Stress."], ["La Torre Sceglie", "Passiva", "La torre cerca un nuovo padrone. Un PG che usa la magia qui e tira con Speranza sente le pareti rispondergli: una volta per sessione può chiedere alla torre di aprire, chiudere o spostare una stanza."]], "domande": ["Chi era il mago della torre, e cosa dicevano di lui nei villaggi vicini?", "Chi di voi è stato apprendista qui, anche solo per una stagione?", "Quale incantesimo di questo mago avete visto con i vostri occhi?", "Chi vi ha pregato di non toccare niente, quassù, e perché?", "Che cosa cercava il mago quando è scomparso?", "Quale oggetto della torre vi chiama per nome, sottovoce?"], "avv": ["Armatura Stregata", "Meccanorbe", "Poltergeist", "Mago dall'Anima Infranta", "Gargoyle", "Guerra in Scatola", "Arcimago"]}, {"id": "tetti", "label": "Inseguimento sui tetti", "tipo": "Evento", "nomi": ["I Tetti di Ardesia", "La Via dei Gatti", "Le Grondaie Alte", "Il Quartiere dei Comignoli", "La Strada di Sopra", "I Coppi del Borgo Vecchio"], "desc": ["Tegole bagnate di pioggia, panni stesi che sbattono come vele e, tre tetti più in là, una figura che corre senza voltarsi.", "Comignoli che fumano, terrazze strette e il vuoto dei vicoli che si apre ogni dieci passi.", "Il quartiere visto dall'alto: cupole, campanili, un gatto che vi guarda con disprezzo e una luna che fa luce a chi scappa.", "Sotto i piedi un mercato che grida, galline che volano via, e travi marce gettate da una casa all'altra."], "impulsi": ["costringere a saltare", "far perdere di vista", "cedere sotto il peso", "trascinare l'inseguimento in posti peggiori", "far cadere tutto in strada", "mettere qualcuno in mezzo"], "feat": [["La Corsa", "Passiva", "Avviate un Conto alla Rovescia di Progresso (4) per i PG e uno di Conseguenza (4) per l'altra parte. Ogni tiro riuscito dei PG fa avanzare il primo; ogni tiro con Paura fa avanzare il secondo. Se si innesca prima il primo, i PG raggiungono la preda o seminano chi li insegue; altrimenti la preda sparisce, o gli inseguitori li raggiungono."], ["Il Salto", "Passiva", "Tra un tetto e l'altro c'è il vuoto. Un PG che salta deve superare un Tiro Agilità ({D}). In caso di successo con Speranza guadagna terreno e può fare subito un'altra mossa; in caso di fallimento resta appeso alla grondaia, Vulnerabile."], ["Scorciatoia", "Passiva", "Chi conosce il quartiere, o supera un Tiro Istinto ({D}), trova una via che gli altri non vedono: un lucernario, una corda da bucato, una scala dentro un campanile. Il gruppo guadagna terreno senza correre rischi."], ["Tegole Sciolte", "Reazione", "Quando un PG tira con Paura correndo sui tetti, una fila di tegole gli scivola sotto i piedi: deve superare un Tiro Reazione di Agilità ({D}) o rotolare fino al bordo e subire {DMG} danni fisici. Le tegole cadono in strada, su qualcuno."], ["Qualcosa in Mezzo", "Azione", "Spendete una Paura: qualcosa si mette di traverso. Una donna stende le lenzuola, un fabbro esce sul terrazzo con un ferro rovente, uno stormo di piccioni esplode davanti alla faccia di un PG. Quel PG deve superare un Tiro Reazione di Agilità ({D}) o perdere terreno e marcare uno Stress."], ["Rinforzi dai Tetti", "Azione", "Spendete una Paura: chi scappa ha degli amici, o chi insegue ha dei rinforzi. Compaiono sui tetti vicini, entro distanza Lontana, e diventano subito protagonisti."]], "domande": ["Chi di voi è cresciuto correndo su questi tetti?", "Cosa ha rubato chi scappa, o cosa avete rubato voi?", "Chi vi vede dalla finestra mentre passate, e vi riconosce?", "Quale tetto del quartiere nessuno attraversa, e perché?", "Cosa vi cade di tasca durante la corsa, e chi lo troverà?", "Fin dove sareste disposti a saltare per non perderlo?"], "avv": ["Lacchè dei Coltelli Seghettati", "Ombra dei Coltelli Seghettati", "Guardia Arciere", "Ladro Mascherato", "Apprendista Assassino", "Gargoyle", "Lamia"]}, {"id": "velati", "label": "Tempio degli dèi velati", "tipo": "Esplorazione", "nomi": ["Il Tempio del Volto Coperto", "La Casa del Velo", "Il Santuario delle Bende", "La Navata dei Nomi Taciuti", "L'Altare Senza Sguardo", "Il Tempio dell'Attesa"], "desc": ["Statue di dèi coperte da veli di pietra scolpiti così bene che sembrano muoversi col vento. Nessuna ha un volto.", "Una navata lunghissima e buia, con un solo raggio di luce che cade su un altare vuoto.", "Migliaia di preghiere scritte su strisce di carta, infilate nelle fessure dei muri e ingiallite. Nessuno ha mai risposto.", "Incenso freddo, l'eco di canti che nessuno sta cantando, e la sensazione che qualcuno stia per sollevare un velo."], "impulsi": ["nascondere il volto degli dèi", "punire chi guarda", "concedere una grazia per un prezzo", "custodire una risposta", "far dubitare", "aspettare chi è degno"], "feat": [["Non Guardate", "Passiva", "Sotto ogni velo c'è qualcosa che non dovrebbe essere visto. Un PG che ne solleva uno ottiene una risposta sincera a una domanda, ma deve superare un Tiro Reazione di Istinto ({D}) o marcare 3 Stress."], ["Preghiere Inascoltate", "Passiva", "Nelle crepe dei muri ci sono preghiere scritte da secoli di fedeli. Un PG che le legge e supera un Tiro Conoscenza ({D}) scopre chi veniva qui, cosa chiedeva, e dove è nascosta un'offerta che nessuno ha mai reclamato."], ["I Custodi del Velo", "Azione", "Spendete una Paura: i custodi del tempio, vivi o no, escono dalle nicchie entro distanza Ravvicinata e chiedono ai PG cosa sono venuti a prendere. Chi mente viene attaccato."], ["La Statua si Gira", "Azione", "Spendete una Paura: una statua velata ora è rivolta verso un PG. Fino alla fine della scena quel PG ha svantaggio ai tiri per nascondersi o per mentire, e sente un respiro sul collo."], ["Silenzio Sacro", "Reazione", "Quando un PG alza la voce, combatte o usa la magia nella navata e tira con Paura, l'eco lo ripete cento volte: tutto il tempio, e qualunque cosa lo abiti, sa dove si trova."], ["La Grazia", "Passiva", "Un PG che lascia sull'altare un'offerta che gli costa davvero (un ricordo, un oggetto amato, una ciocca di capelli) ottiene una Speranza e rimuove 2 Stress. Una volta soltanto: gli dèi velati non ascoltano due volte la stessa persona."]], "domande": ["Quale dio velato pregava la vostra famiglia, e cosa gli chiedeva?", "Chi di voi ha smesso di credere, e quando?", "Cosa avete visto, una volta, sotto un velo che non dovevate sollevare?", "Quale preghiera avete lasciato in un tempio come questo?", "Perché, secondo voi, gli dèi si sono coperti il volto?", "Cosa chiedereste agli dèi, se oggi rispondessero?"], "avv": ["Fantasma", "Armatura Stregata", "Gargoyle", "Guardiano Spettrale", "Sacerdote del Dolore", "Coro Santificato", "Oracolo del Fato"]}, {"id": "arena", "label": "Arena dei Senzaporta", "tipo": "Evento", "nomi": ["Il Cerchio dei Carri", "La Fossa del Pugno Chiuso", "Il Recinto delle Scommesse", "L'Anello di Polvere", "La Gabbia delle Lanterne", "Il Circo delle Ossa Dipinte"], "desc": ["Carri disposti in cerchio fanno da spalti. Sopra, gente che urla, scommette, mangia castagne e tira i gusci ai combattenti.", "Un anello di sabbia rossa sotto lanterne appese alle funi. Al centro, un palo con incisi i nomi dei campioni.", "Tamburi, odore di sudore e di frittelle, e un banditore con una voce così grossa che sembra uscire dalla terra.", "Una fossa scavata nella roccia, con gabbie lungo il bordo. In una, qualcosa graffia, impaziente."], "impulsi": ["dare spettacolo", "premiare l'audacia", "punire la noia", "ribaltare le scommesse", "mescolare onore e truffa", "portare la folla dalla parte di qualcuno"], "feat": [["La Folla Decide", "Passiva", "Quando un PG fa qualcosa di spettacolare e tira con Speranza, la folla lo acclama: ha vantaggio al prossimo tiro, e dagli spalti gli piove un'arma, un fiasco o un consiglio urlato."], ["Pollice Verso", "Azione", "Spendete una Paura: la folla si annoia e vuole sangue. Il banditore apre una gabbia: un avversario compare entro distanza Ravvicinata da un PG e diventa subito protagonista."], ["Incontro Truccato", "Azione", "Spendete una Paura: qualcuno ha scommesso contro i PG. Un sasso dagli spalti, sabbia negli occhi, una cinghia tagliata: un PG a scelta deve superare un Tiro Reazione di Istinto ({D}) o diventare Vulnerabile fino al suo prossimo attacco riuscito."], ["Mani dagli Spalti", "Reazione", "Quando un PG tira con Paura vicino al bordo, decine di mani lo afferrano e lo ributtano dentro: cade a terra Vulnerabile, e gli manca qualcosa dalla cintura."], ["La Parola del Cerchio", "Passiva", "Nel cerchio la parola data vale più dell'oro. Chi vince un incontro può chiedere una cosa a chi ha perso, davanti a tutti, e i Senzaporta faranno in modo che venga pagata."], ["Scommettere su Sé Stessi", "Passiva", "Prima di un incontro, un PG può scommettere sul gruppo e annunciarlo alla folla. Se il gruppo vince, ottiene una Speranza e una borsa piena; se perde, marca uno Stress e deve un favore al banco."]], "domande": ["Chi di voi ha già combattuto in un cerchio come questo, e con quale nome?", "Quale campione di quest'arena vi ha battuto, o salvato?", "Cosa avete scommesso, e chi vi ha prestato i soldi?", "Quale canzone dei Senzaporta conoscete abbastanza bene da cantarla con la folla?", "Perché siete scesi nell'arena invece di guardare dagli spalti?", "Cosa c'è nell'ultima gabbia, secondo le voci?"], "avv": ["Maestro d'Armi", "Masque Muerte", "Cinghialorso", "Berserker Iniziato", "Gigante Lottatore", "Minotauro Demolitore", "Chimera"]}], "incarichi3": [{"id": "salvataggio", "label": "Salvataggio", "chi": ["una madre che non dorme da tre giorni", "un capovillaggio che parla sottovoce, lontano dalle orecchie del consiglio", "un vecchio soldato con una gamba sola e troppo orgoglio per chiedere due volte", "un Custode della Pira con le mani ancora sporche di cenere", "un mercante che ha già pagato qualcuno per cercare, e quel qualcuno non è tornato", "una sposa ancora vestita per le nozze che non ci sono state", "un fabbro che ha chiuso bottega e porta ancora il grembiule bruciacchiato", "una levatrice che ha fatto nascere mezzo villaggio e ne conosce ogni segreto"], "cosa": ["riportare a casa una ragazza sparita nella palude tre notti fa", "tirare fuori un prigioniero da un campo di predoni prima dell'alba", "ritrovare la guida di una carovana sparita sulla strada dei monti", "riportare indietro un cartografo sparito oltre l'ultima Pira del confine", "recuperare un bambino portato via da qualcosa che camminava sui tetti", "riprendere un guaritore rapito da una banda che ha il capo ferito a morte", "liberare una novizia chiusa in un mulino abbandonato da una setta che aspetta la luna nuova", "scendere in una miniera allagata dove un minatore batte sui tubi da due giorni"], "ma": ["chi va salvato se n'è andato di sua volontà, e non ha nessuna voglia di tornare", "dietro la sparizione c'è qualcuno con una buona ragione, e i PG la scopriranno a metà strada", "un conto alla rovescia (4) scandisce il tempo: allo zero, sarà troppo tardi", "qualcuno vicino al committente ha venduto la vittima, e farà di tutto perché non torni a parlare", "chi va salvato ha visto qualcosa che una fazione potente vuole resti sepolto", "un'altra squadra è già partita, pagata da qualcuno che non vuole sopravvissuti", "il committente non è chi dice di essere: cerca la vittima per finirla di persona", "chi va salvato torna con il segno dell'Umbra addosso, e al villaggio nessuno vorrà riaprirgli la porta"], "premio": ["tutto quello che c'è in casa del committente, che è poco ma è tutto", "una manciata d'oro a testa subito, e il resto al ritorno", "un oggetto di famiglia che vale molto più di quanto sembri", "un posto sicuro dove passare l'inverno, con il fuoco sempre acceso", "una lama vecchia ma mai sconfitta, rimasta appesa sopra un camino per tre generazioni", "una mappa dei sentieri che le pattuglie non controllano", "la promessa di ricambiare: un giorno, una volta, senza fare domande", "una cassa di provviste che di questi tempi vale più dell'oro"]}, {"id": "scorta", "label": "Scorta", "chi": ["un mercante nervoso che conta le monete due volte", "una sacerdotessa senza tempio, con un'icona velata legata sulla schiena", "uno studioso dell'Ateneo Celsiano con più bauli che buon senso", "un nobile decaduto che viaggia sotto falso nome, e lo fa malissimo", "una vedova che porta tutto quello che le resta su un solo carro", "un capocarovana dei Senzaporta che ha perso metà delle sue guardie in una notte", "un Custode della Pira in viaggio per la prima volta lontano dal suo fuoco", "un giovane erede circondato da servitori che non sanno tenere una spada"], "cosa": ["accompagnare un carro chiuso a chiave fino alla prossima città murata", "portare un gruppo di civili attraverso una palude dove la strada è sparita", "scortare una persona a un incontro segreto in un mulino in rovina", "portare un carico di braci consacrate a un villaggio rimasto senza fuoco", "guidare una fila di muli carichi su un passo di montagna prima della prima neve", "trasportare una bara sigillata fino al cimitero di famiglia, a cinque giorni di strada", "accompagnare un prigioniero in catene davanti a chi lo deve giudicare", "condurre una chiatta lungo il fiume, sotto tre ponti controllati da pedaggiatori armati"], "ma": ["uno dei viaggiatori è una spia, e lascia segni lungo la strada per chi li segue", "la strada sicura è crollata e resta solo quella che tutti evitano", "il committente ha venduto il percorso a una banda: per motivi suoi, il viaggio deve fallire", "qualcosa nei bagagli attira i morti: ogni notte ce n'è uno in più dietro al gruppo", "a metà strada arriva un ordine di fermarsi, firmato da qualcuno che i PG non possono ignorare", "una tempesta d'Umbra si muove sulla stessa strada, un giorno dietro di loro", "all'arrivo, chi doveva ricevere il gruppo è morto da una settimana, e qualcuno ha preso il suo posto", "le guardie già assoldate dal committente obbediscono in segreto a un altro padrone"], "premio": ["metà subito, metà all'arrivo, contata davanti a testimoni", "il diritto di scegliere una cosa qualsiasi dai bagagli del committente", "una lettera di presentazione per qualcuno che conta, alla fine della strada", "cavalcature fresche e due settimane di provviste per ripartire", "una quota di quanto il committente guadagnerà all'arrivo, se guadagnerà qualcosa", "una mappa delle strade sicure, corretta a mano da chi le ha percorse per vent'anni", "un posto alla tavola del committente, e un debito di riconoscenza scritto e firmato", "un'arma raccolta su un campo di battaglia che nessuno ricorda più"]}, {"id": "recupero", "label": "Recupero", "chi": ["un nobile decaduto che ha venduto tutto tranne l'orgoglio", "un collezionista che parla solo attraverso un servo", "un Custode della Pira che non dovrebbe chiedere quello che chiede", "un ex compagno d'armi di uno dei PG, ora con un occhio di vetro", "una studiosa dell'Ateneo che parla troppo in fretta e guarda sempre la porta", "un'antiquaria cieca che riconosce gli oggetti dal suono che fanno", "un ladro in pensione con le dita rotte, che non può più farlo da solo", "una sacerdotessa che tiene il conto delle reliquie perdute su un rotolo lungo due metri"], "cosa": ["recuperare una reliquia dall'altare di un tempio sprofondato nel fango", "riprendere un libro rubato prima che venga battuto all'asta domani notte", "ritrovare la spada di un eroe caduto e riportarla dove deve stare", "sfilare un anello dal dito di un morto che, dicono, non resta mai nella sua tomba", "sottrarre un documento dallo studio di una famiglia potente durante una festa", "ripescare un forziere dal relitto di una chiatta affondata nel lago", "riportare indietro una campana sacra portata via da un villaggio di predoni", "strappare una maschera d'argento al capo di una banda che la porta come trofeo"], "ma": ["l'oggetto è già nelle mani di un gruppo rivale, che sta per andarsene", "il legittimo proprietario non è chi li ha ingaggiati, e lo verrà a sapere presto", "prenderlo sveglia ciò che lo custodiva, che da quel momento segue le tracce dei PG", "ce ne sono due identici, e nessuno, nemmeno il committente, sa quale sia quello vero", "l'oggetto sussurra a chi lo porta, e ogni notte chiede di essere riportato indietro", "il committente vuole distruggerlo appena lo avrà in mano, e i PG potrebbero non essere d'accordo", "chi lo custodisce adesso gli vuole bene davvero, e non è affatto un cattivo", "qualcuno ha messo una taglia sul primo che lo tocca"], "premio": ["un oggetto a scelta tra quelli che il committente tiene sotto chiave", "oro sufficiente per vivere un anno senza lavorare", "la risposta a una domanda che i PG si portano dietro da tempo", "un Ramo Benedetto, ancora verde", "metà di quello che l'oggetto frutterà alla vendita", "il nome di chi possiede un altro oggetto, ancora più prezioso, e dove lo tiene", "un debito cancellato: quello di uno dei PG con qualcuno di poco raccomandabile", "una chiave che apre qualcosa, e il committente giura di non sapere cosa"]}, {"id": "indagine", "label": "Indagine", "chi": ["un capo delle guardie stanco e sotto pressione", "una vedova che non crede alla versione ufficiale", "un oste che sente troppe cose e dorme troppo poco", "un predicatore spaventato che ha smesso di predicare", "un becchino che vede tutto e non dice mai niente, fino a oggi", "una notaia che tiene il registro di tutti i morti del distretto", "un consigliere cittadino che si presenta senza scorta e con il cappuccio alzato", "una lavandaia che lava i panni di mezza città e ne conosce ogni macchia"], "cosa": ["scoprire chi sta uccidendo i Custodi della Pira, uno a settimana", "capire perché i morti di un quartiere non tornano più", "trovare chi ha avvelenato il pozzo prima che la folla impicchi qualcuno a caso", "smascherare un impostore che siede nel consiglio della città", "scoprire dove finiscono i bambini che spariscono nelle notti di nebbia", "capire chi ha dato fuoco al granaio comune, e perché solo a quello", "trovare l'origine delle monete false che stanno affamando il mercato", "scoprire perché un intero villaggio giura che uno dei suoi abitanti non è mai esistito"], "ma": ["il colpevole è qualcuno che i PG conoscono e stimano", "chi li ha ingaggiati vuole un colpevole, non la verità", "ogni pista porta a una fazione che è meglio non sfidare", "mentre indagano succede di nuovo, e stavolta c'è un testimone che accusa i PG", "il colpevole lo ha fatto per evitare qualcosa di molto peggio, e ha ragione", "le prove sono state piazzate: qualcuno vuole che i PG trovino proprio quel colpevole", "i colpevoli sono due, e nessuno dei due sa dell'altro", "il committente sa già tutto: vuole solo vedere fin dove arrivano i PG"], "premio": ["la taglia che pende sul colpevole, e il committente sa a chi chiederla", "l'amicizia del committente, che in questa città vale più dell'oro", "l'accesso a un archivio che pochi hanno visto", "un favore da riscuotere presso una fazione", "la chiave di una casa vuota in città, con il tetto buono e una cantina asciutta", "il silenzio su qualcosa che uno dei PG ha fatto qui, tempo fa", "un sacchetto di monete vere, pesate una per una davanti ai PG", "un nome: quello di chi sta chiedendo dei PG da quando sono arrivati in città"]}, {"id": "difesa", "label": "Difesa", "chi": ["un capovillaggio con la voce rotta e un'ascia appena comprata", "un Custode della Pira che non ha più legna né aiutanti", "una guaritrice che non vuole lasciare i suoi malati", "una famiglia di Senzaporta che ha piantato le tende nel posto sbagliato", "una priora che ha chiuso il convento ai pellegrini e lo ha aperto ai feriti", "un mugnaio che non abbandonerà la sua ruota nemmeno da morto", "una vecchia guardiana del ponte che ha fatto pagare il pedaggio a tre generazioni", "una giovane comandante della milizia, che fino a ieri era la vice"], "cosa": ["resistere per tre notti, finché non arrivano i rinforzi", "tenere accesa la Pira durante una tempesta d'Umbra che durerà fino all'alba", "fermare una banda di predoni che ha promesso di tornare con la luna piena", "respingere l'assedio di un branco di bestie che l'Umbra ha reso furbe", "tenere lontani i morti di un vecchio campo di battaglia, che stanotte si rialzano tutti insieme", "fortificare in un solo giorno un posto mai pensato per combattere, prima che arrivi una colonna di razziatori", "difendere il raccolto da gente che ha fame quanto il villaggio, ed è armata meglio", "tenere il ponte che il nemico deve attraversare per arrivare alle case"], "ma": ["tra chi va difeso c'è un traditore, pronto ad aprire la strada al nemico", "i rinforzi promessi non arriveranno, e qualcuno lo sa già", "il nemico vuole una cosa precisa che è nascosta qui, e se ne andrebbe se l'avesse", "difendere tutti è impossibile: a un certo punto bisognerà scegliere chi lasciare indietro", "metà della gente vuole fuggire e metà restare, e litigano proprio quando serve stare uniti", "il nemico ha le sue ragioni: qualcuno di qui gli ha fatto un torto terribile", "l'unico modo per vincere è uscire e colpire il capo nemico nel suo campo", "tra i difensori c'è qualcuno che è già morto una volta, e non l'ha detto a nessuno"], "premio": ["un titolo onorario e un posto per sempre nella comunità", "le provviste migliori e un carro per ripartire", "una reliquia custodita da generazioni, che non è mai uscita da qui", "la protezione della comunità per qualcuno a cui i PG tengono", "le armi dei nemici caduti, e nessuna domanda su cosa ne farete", "i nomi dei PG incisi sulla pietra della porta, e un brindisi ogni anno", "il diritto di tornare qui in qualsiasi momento, con chiunque, anche se ricercati", "una brace consacrata, di quelle che qui si tengono per i giorni peggiori"]}, {"id": "negoziato", "label": "Negoziato", "chi": ["un consigliere di una famiglia nobile che sorride sempre, anche quando minaccia", "una capocarovana dei Senzaporta con dieci anelli e nessuna fretta", "un portavoce di una comunità affamata, magro come un manico di scopa", "un capo di predoni stanco di combattere", "una giudice di villaggio che nessuno ascolta più", "un monaco che ha fatto voto di silenzio e scrive tutto su una lavagnetta", "un mercante che perde soldi ogni giorno che le cose restano come sono", "una matriarca che non alza mai la voce, e non ne ha bisogno"], "cosa": ["portare di persona una proposta di tregua al nemico", "convincere due villaggi rivali a dividersi l'acqua dell'unico pozzo", "comprare la libertà di un prigioniero senza scatenare una guerra", "fare da garanti a un accordo tra due fazioni che si odiano", "convincere una banda di disertori a tornare sotto le armi, o almeno a smettere di saccheggiare", "trattare con qualcosa che vive nel bosco e pretende un tributo ogni inverno", "ottenere il passaggio attraverso le terre di un signore che odia gli stranieri", "far firmare la pace a due famiglie prima del funerale che le metterà nella stessa stanza"], "ma": ["una delle parti vuole la guerra e farà di tutto per sabotare l'incontro", "chi li manda non vuole davvero un accordo: vuole una scusa", "il prezzo chiesto è qualcosa che i PG non possono dare", "durante l'incontro qualcuno viene ucciso, e tutti guardano i PG", "l'altra parte ha già un accordo segreto con qualcuno, e i PG sono solo una copertura", "l'altra parte accetta solo con un pegno: uno dei PG resta come ospite finché il patto regge", "chi siede al tavolo non è più quello che comanda davvero", "l'accordo è giusto, ma rovinerà una terza parte che nessuno ha invitato al tavolo"], "premio": ["una percentuale di quanto l'accordo farà guadagnare", "il passaggio sicuro nei territori di entrambe le parti", "un'informazione che vale più dell'accordo stesso", "un sigillo personale del committente, che apre porte e chiude bocche", "ospitalità per sempre sotto il tetto del committente", "un cavallo per ciascuno, di quelli che non si spaventano nemmeno davanti ai morti", "un favore che una persona potente non potrà rifiutare", "la gratitudine di chi è vivo grazie ai PG, e la lista di chi invece adesso li odia"]}, {"id": "caccia", "label": "Caccia a una bestia", "chi": ["un pastore che ha perso metà del gregge in una notte", "una cacciatrice con il braccio al collo, furiosa di non poterci andare lei", "un nobile che vuole la testa da appendere in sala, intera e senza buchi", "un Custode della Pira che ha visto la bestia girare attorno al fuoco senza paura", "uno studioso dell'Ateneo con un quaderno pieno di disegni di impronte", "una conciatrice che paga a peso di pelle", "un capovillaggio che ha già mandato tre cacciatori, e nessuno è tornato", "un carbonaio con la casa sventrata e una figlia da sfamare"], "cosa": ["abbattere un lupo grande come un cavallo che caccia solo nelle notti di nebbia", "uccidere un orso che ha imparato ad aprire le porte", "trovare e uccidere qualcosa che trascina le pecore nel lago e non lascia nemmeno le ossa", "stanare un rapace gigante che ha fatto il nido sul campanile", "fermare un cinghiale grosso come un carro che carica le case di notte", "cacciare una bestia Toccata dall'Umbra che chiama con la voce delle sue vittime", "uccidere un serpente che si è fatto la tana nel pozzo del villaggio", "abbattere una creatura che nessuno ha mai visto bene, ma che lascia impronte di mani umane"], "ma": ["la bestia ha dei piccoli, e un bambino del villaggio li tiene nascosti nel fienile", "qualcuno la nutre di nascosto, e non vuole perderla", "non è una sola: sono due, e la seconda è più grande", "la bestia sta fuggendo da qualcosa di peggio, che arriverà quando lei sarà morta", "qualcuno al villaggio l'ha resa così con un rito andato storto, e ha paura che si sappia", "un'altra squadra di cacciatori vuole la stessa preda, e non si fa scrupoli con i concorrenti", "ferita, la bestia scappa verso l'unico posto dove i PG non vorrebbero mai seguirla", "la bestia un tempo era una persona, e qualcuno al villaggio la riconosce"], "premio": ["la pelle, i denti e tutto quello che si può vendere della bestia", "una taglia raccolta casa per casa, in monete di tutti i conii", "un arco che non ha mai mancato un colpo, a sentire chi lo regala", "carne affumicata per un mese e un fienile asciutto dove dormire", "un cane da caccia addestrato, fedele e un po' troppo intelligente", "una mappa delle tane e dei passaggi del bosco, segnata in vent'anni di caccia", "un'ampolla di sangue di una bestia simile, cacciata anni fa, che chiude le ferite", "la gratitudine di una valle intera, che offrirà da bere ai PG per anni"]}, {"id": "vendetta", "label": "Vendetta", "chi": ["una vedova vestita di nero che non piange più", "un ragazzo con la spada del padre, troppo grande per lui", "un vecchio mercenario che non riesce più a stringere un'arma", "un Custode della Pira che ha smesso di pregare e ha cominciato ad affilare", "una ex cortigiana con un elenco di nomi ricamato su un fazzoletto", "un fratello rimasto solo, che ha venduto la casa per pagare i PG", "una capobanda in disgrazia che non ha più uomini, solo rancore", "un locandiere che ha seppellito suo figlio la settimana scorsa"], "cosa": ["trovare l'uomo che ha dato fuoco a una fattoria con la famiglia dentro, e fargliela pagare", "rovinare un mercante che ha costruito la sua fortuna su un tradimento", "portare indietro vivo il capo della banda che ha razziato un villaggio, perché guardi in faccia i sopravvissuti", "umiliare in pubblico un duellante che non ha mai perso, perché l'ultima volta ha vinto a tradimento", "bruciare il magazzino di una famiglia che ha affamato un quartiere per alzare i prezzi", "scovare un disertore che ha venduto il suo reparto al nemico, e ora vive sotto un altro nome", "smascherare davanti a tutti un Custode che lascia fuori dal cerchio chi non gli piace", "dare la caccia a un negromante che ha riportato indietro un morto amato, ma non tutto intero"], "ma": ["il bersaglio è cambiato davvero: adesso metà del villaggio vive del suo lavoro", "il committente non racconta tutto: la prima colpa fu sua", "il bersaglio sa che stanno arrivando, e ha assoldato qualcuno a sua volta", "il bersaglio ha una famiglia che non sa niente, e che si metterà in mezzo", "la stessa vendetta è già stata promessa a qualcun altro, che non vuole concorrenti", "una volta compiuta, il committente non avrà più ragioni per vivere, e lo sa benissimo", "il bersaglio è protetto da una fazione che lo considera troppo utile per perderlo", "il bersaglio è innocente: il vero colpevole gli ha cucito addosso la colpa"], "premio": ["i risparmi di una vita, cuciti nell'orlo di un mantello", "un'arma appartenuta a una delle vittime, che nessuno ha più osato usare", "il nascondiglio di un tesoro che nessuno ha mai toccato", "un segreto sul bersaglio che vale una fortuna a chi sa a chi venderlo", "metà di quello che il bersaglio possiede, se si riesce a prenderlo", "una promessa scritta col sangue: il committente farà una cosa qualsiasi chiesta dai PG, una volta sola", "le chiavi di una casa che nessuno verrà mai a reclamare", "un anello con sigillo che apre una porta in città, e una sola"]}, {"id": "spedizione", "label": "Spedizione", "chi": ["una cartografa dell'Ateneo con mappe piene di buchi e di macchie di vino", "un vecchio esploratore che non ricorda come è tornato dall'ultimo viaggio", "un mercante che fiuta l'affare prima ancora di sapere quale sia", "un Custode della Pira che non ha mai visto altro che il suo fuoco, e vuole venire anche lui", "una giovane nobile che vuole vedere il mondo prima del matrimonio combinato", "un monaco che ha fatto voto di vedere il mondo prima di morire, e ha fretta", "un capovillaggio con un villaggio che muore di fame e nessun'altra idea", "una minatrice con le mani nere e in tasca un sasso che non dovrebbe esistere"], "cosa": ["mappare la valle oltre il passo, dove le Pire non arrivano più", "raggiungere una città sepolta di cui parla una sola cronaca, e tornare con le prove", "trovare la sorgente del fiume che da un mese scorre caldo e rossastro", "scendere nella voragine fino al fondo, o almeno fino a dove si sente l'acqua", "attraversare il deserto di cenere e piantare un segnale sulla torre dall'altra parte", "trovare un passaggio sicuro attraverso la palude, abbastanza largo per i carri", "seguire uno stormo che ogni anno sparisce sempre nello stesso punto del cielo", "raggiungere un'isola del lago che compare solo nelle notti senza vento"], "ma": ["qualcuno ci è già stato, e ha lasciato segnali che dicono di tornare indietro", "il luogo è abitato, e chi ci vive non vuole essere scoperto", "le provviste bastano per arrivare, non per tornare: bisognerà trovare cibo sul posto", "il committente non vuole una mappa: vuole che i PG aprano qualcosa che lui non osa aprire", "la guida assoldata ci è già stata, e mente su cosa è successo l'ultima volta", "quello che troveranno vale abbastanza da scatenare una guerra, se si viene a sapere", "una spedizione rivale è partita un giorno prima, ed è armata meglio", "lì il tempo scorre in un altro modo: al ritorno saranno passate settimane, non giorni"], "premio": ["i nomi dei PG sulla mappa, e una parte di ciò che si troverà", "una quota di qualunque cosa frutterà la scoperta, per sempre", "attrezzatura da spedizione di prima qualità, che resta ai PG", "il primo diritto di scelta su tutto quello che si riporterà indietro", "una bussola che non indica il nord, ma la Pira più vicina", "oro, tanto, ma solo al ritorno", "tutte le notizie che il committente ha raccolto in anni: nomi, rotte, nascondigli", "un mulo che sa ritrovare la strada di casa da qualunque punto del mondo"]}, {"id": "infiltrazione", "label": "Infiltrazione", "chi": ["una spia in pensione che vuole chiudere un ultimo conto", "un servitore che ha visto troppo e trema ancora", "un mercante rovinato che giura di sapere chi l'ha rovinato", "una sacerdotessa che non si fida più nemmeno del proprio ordine", "un capo delle guardie che non può muoversi senza un ordine scritto", "una ladra con il braccio ingessato e un piano già pronto", "un nobile minore che vuole sapere cosa si dice di lui alle sue spalle", "un ex membro di una setta, con il marchio ancora sul polso"], "cosa": ["entrare a una festa in maschera e scoprire chi incontra il padrone di casa a mezzanotte", "farsi assumere come guardie in una villa e copiare un registro", "unirsi a una setta per una notte di iniziazione, e uscirne con i nomi dei capi", "entrare in un campo di predoni fingendosi disertori, e scoprire quando attaccheranno", "intrufolarsi nell'archivio chiuso dell'Ateneo e trovare un fascicolo con un certo nome", "farsi arrestare e passare una notte in prigione per parlare con un detenuto", "imbarcarsi su una chiatta di contrabbandieri e scoprire dove scaricano", "sostituire per un giorno i servitori di una casa nobile e ascoltare cosa si dice a tavola"], "ma": ["qualcuno all'interno riconosce uno dei PG, ma non dice niente: aspetta di vedere cosa fanno", "il posto è già pieno di infiltrati, di almeno due parti diverse", "per restare credibili, i PG dovranno fare qualcosa di cui si vergogneranno", "chi li manda li ha già venduti: dentro li stanno aspettando", "una volta dentro, scoprono che il committente è uno dei bersagli", "un innocente li scopre per primo, e tacere lo metterà in pericolo", "l'informazione cercata è falsa: qualcuno l'ha preparata apposta perché venisse rubata", "uscire sarà molto più difficile che entrare: a una certa ora le porte si chiudono, e non si riaprono fino all'alba"], "premio": ["oro contato in anticipo, lasciato in un nascondiglio che conosceranno solo i PG", "un nome falso, con tanto di documenti, per ciascun PG", "una copia di tutto quello che troveranno, da usare come preferiscono", "il nome di chi sta seguendo i PG da qualche settimana", "un travestimento perfetto, fatto su misura e riutilizzabile", "un contatto dentro, che resterà fedele ai PG anche dopo", "un favore da una persona potente, che non potrà rifiutarlo", "una mappa dei passaggi segreti della città, quelli veri"]}], "viaggi": [{"id": "strada", "label": "Strada maestra", "tempo": ["Sole basso e polvere: chi cammina in coda arriva grigio come una statua.", "Pioggerella fine che non smette mai, e i carri affondano nel fango fino al mozzo.", "Vento caldo da sud che porta odore di fumo, ma non si vede nessun incendio.", "Mattina di brina: i solchi delle ruote sono lastre di ghiaccio che scricchiolano.", "Cielo color rame e silenzio: sulla strada non passa nessuno da ore, e non è normale."], "eventi": ["Un posto di blocco improvvisato chiede un pedaggio che cambia a seconda della faccia di chi paga.", "Un carro ribaltato blocca la strada: il carrettiere è sparito, i buoi no, e il carico si muove sotto il telo.", "Un messaggero vi supera al galoppo, poi torna indietro e vi chiede da quale città venite, con la mano sulla spada.", "Una famiglia di profughi chiede di viaggiare con voi fino alla prossima Pira, e la nonna non sta in piedi.", "Un impiccato al bivio ha ancora in tasca una lettera sigillata che nessuno ha osato prendere.", "Una processione funebre vi viene incontro: la bara è aperta e il morto vi saluta con la mano.", "Due bande si fronteggiano sul ponte di pietra, e ognuna vi chiede di schierarvi prima che volino le frecce.", "Un venditore ambulante ha proprio l'oggetto che vi serve, e lo vende a un prezzo che non è in denaro."], "scoperte": ["Una pietra miliare cava con dentro una scorta di frecce e la mappa delle pattuglie.", "Una stazione di posta abbandonata, con la dispensa ancora piena e un camino che tira bene.", "Un altarino di un dio velato con offerte fresche: chi lascia un dono sincero ottiene una Speranza.", "Tracce di una carovana passata ieri: dodici carri, e uno molto più pesante degli altri.", "Un cippo con le distanze scalpellate e riscritte a mano: qualcuno ha segnato una scorciatoia.", "Un cavallo sellato che pascola da solo, con le bisacce piene e un sigillo nobiliare sulla sella."], "pericoli": ["Imboscata dai fossati ai lati della strada: ogni PG deve superare un Tiro Reazione di Istinto ({D}) o inizia lo scontro Vulnerabile.", "Il ponte di legno cede sotto il carro: serve un Tiro Forza ({D}) per trattenerlo, in caso di fallimento metà delle provviste finisce nel torrente.", "Un falso pellegrino vi segue da giorni: spendete una Paura, e stanotte qualcosa di prezioso sparisce dai bagagli.", "Le guardie di un signore locale vi fermano per un controllo: con un Tiro Presenza ({D}) fallito vi sequestrano le armi più vistose.", "Una ruota si spacca al tramonto: Tiro Astuzia ({D}) per ripararla prima del buio, altrimenti ognuno marca uno Stress per la notte all'addiaccio.", "Il pozzo della stazione di posta è stato avvelenato: chi ha bevuto deve superare un Tiro Reazione di Forza ({D}) o marca uno Stress e ha svantaggio al prossimo tiro."], "avv": ["Bandito dei Coltelli Seghettati", "Luogotenente dei Coltelli Seghettati", "Cavaliere del Reame", "Dullahan", "Araldo della Guerra"]}, {"id": "palude", "label": "Palude", "tempo": ["Nebbia gialla che sale dall'acqua a metà mattina: si vede solo a distanza Ravvicinata.", "Caldo umido, zanzare a nuvole, e i vestiti non si asciugano mai.", "Pioggia tiepida e fitta che fa ribollire le pozze come pentole.", "Aria ferma e odore di uova marce: ogni tanto una bolla scoppia con un sospiro.", "Gelo notturno che copre l'acqua di una pellicola sottile, e sotto qualcosa si muove."], "eventi": ["Un barcaiolo offre un passaggio sulla sua chiatta, e in cambio chiede un capello a ciascuno di voi.", "Una casa su palafitte con il fuoco acceso e la tavola apparecchiata esattamente per quanti siete.", "Un uomo affondato fino al petto nelle sabbie mobili chiede aiuto, e giura di non essere solo là sotto.", "Un pescatore di anguille è stato morso da qualcosa, e da ieri il morso ha cominciato a parlare.", "Due cadaveri legati schiena contro schiena su un isolotto, freschi, con la bocca piena di monete.", "Il sentiero di tronchi finisce in mezzo all'acqua: qualcuno l'ha smontato da poco, e i tronchi galleggiano ancora lì.", "Dei cavatori di torba vi supplicano di cacciare la cosa che dorme sotto il loro pontile e russa.", "Un airone enorme vi segue di albero in albero, e ogni volta che si posa un ramo si spezza."], "scoperte": ["Un barchino capovolto ma intatto tra le canne, con i remi legati sotto.", "Un isolotto asciutto con i resti di un accampamento e un fascio di frecce ancora buone.", "Erbe amare che crescono solo qui: masticate, rimuovono uno Stress, ma lasciano la lingua nera per un giorno.", "Una statua mezza sommersa di un dio velato: dietro il velo qualcuno ha inciso una mappa della palude.", "Una pozza d'acqua dolce in mezzo all'acqua marcia, protetta da un cerchio di sassi bianchi.", "Il relitto di una chiatta di contrabbandieri: nel doppio fondo, una cassetta di braci consacrate ancora calde."], "pericoli": ["Sabbie mobili sotto un velo di lenticchie d'acqua: chi è in testa deve superare un Tiro Reazione di Agilità ({D}) o rimane Trattenuto finché qualcuno non lo tira fuori.", "Sanguisughe grosse come un pollice: ogni PG che ha guadato marca uno Stress, a meno che qualcuno non riesca in un Tiro Conoscenza ({D}) per staccarle col fuoco.", "Luci che imitano le vostre lanterne nella nebbia: con un Tiro Istinto ({D}) fallito il gruppo le segue e perde mezza giornata.", "Febbre di palude: il primo PG che tira con Paura ha svantaggio ai Tiri Forza fino al prossimo riposo lungo.", "L'acqua sale durante la notte: avviate un conto alla rovescia (3) per trovare un punto asciutto prima di perdere le provviste.", "Qualcosa trascina sott'acqua l'animale da soma: spendete una Paura, e il PG più vicino deve scegliere subito se tuffarsi o lasciarlo andare."], "avv": ["Zanzare Giganti", "Kelpie", "Anguille Elettriche", "Ammaliatore della Lanterna", "Abominio Cefilite"]}, {"id": "montagna", "label": "Montagna", "tempo": ["Vento a raffiche che strappa i mantelli e si porta via ogni parola.", "Nevischio obliquo e cielo bianco: non si distingue il bordo del sentiero dal vuoto.", "Aria limpida e gelida: si vede a giorni di distanza, compreso chi vi sta seguendo.", "Nuvole basse che attraversano il gruppo, bagnate e fredde come stracci.", "Disgelo improvviso: ruscelli ovunque, e il rombo lontano di qualcosa che si stacca."], "eventi": ["Un pastore cieco vi chiede di riportargli una capra scappata sulla cengia più stretta della valle.", "Un ponte di corda tra due guglie, e dall'altra parte qualcuno che lo sta tagliando con calma.", "Un monastero sbarrato dall'interno: i monaci parlano dalle feritoie e chiedono notizie di un mondo che credono finito.", "Un rifugio di cacciatori costruito con ossa di gigante al posto delle travi, con il fuoco ancora caldo e nessuno dentro.", "Un'aquila grande come un cavallo vi sorvola tre volte, poi si posa su una roccia e aspetta.", "Una slavina ha appena sepolto una carovana: dalla neve spunta una mano che si muove ancora.", "Una guarnigione di confine vi chiede di portare una lettera al forte successivo, perché i loro messaggeri non arrivano mai.", "Due montanari si sfidano a duello su una cengia: chi perde cade, e vi chiedono di fare da testimoni."], "scoperte": ["Una grotta asciutta con la legna già accatastata e un'incisione: chi la usa ne lasci altrettanta.", "Una vena di metallo lucente scoperta da una frana recente, ancora intatta.", "Un vecchio sentiero di contrabbandieri, segnato da pietre impilate, che taglia mezza giornata di cammino.", "Una sorgente calda dove un riposo breve rimuove uno Stress in più.", "Il nido abbandonato di un grande rapace, pieno di oggetti brillanti rubati in anni di caccia.", "Il corpo congelato di un esploratore, con il diario aperto all'ultima pagina scritta."], "pericoli": ["Una cornice di neve cede: il PG in testa deve superare un Tiro Reazione di Agilità ({D}) o scivola verso il vuoto e marca un PF.", "Il freddo morde di notte: senza un fuoco, ogni PG deve superare un Tiro Reazione di Forza ({D}) o marca uno Stress.", "L'aria sottile toglie il fiato: chi tira con Paura ha svantaggio ai Tiri Forza finché il gruppo non scende di quota.", "Spendete una Paura: una scarica di sassi piomba dall'alto, e chi è entro distanza Ravvicinata dal punto d'impatto deve superare un Tiro Reazione di Agilità ({D}) o subisce {DMG} danni fisici.", "Il sentiero è sparito sotto la neve fresca: Tiro Istinto ({D}) per ritrovarlo, in caso di fallimento il viaggio dura un giorno in più.", "Qualcosa ha scelto il gruppo come preda e lo segue dall'alto: avviate un conto alla rovescia (4), allo zero attacca durante il turno di guardia più debole."], "avv": ["Arpia", "Troll di Montagna", "Aquila Gigante", "Titano del Gelo", "Grifone"]}, {"id": "foresta", "label": "Foresta", "tempo": ["Luce verde e fioca sotto le chiome: a mezzogiorno sembra già il tramonto.", "Pioggia che non arriva a terra: la si sente sulle foglie per ore, poi gocciola tutta insieme.", "Nebbia tra i tronchi: i rumori arrivano dalle direzioni sbagliate.", "Vento d'autunno che stacca foglie rosse a mucchi e cancella i sentieri.", "Afa immobile, nessun canto d'uccello, solo il ronzio degli insetti."], "eventi": ["Un albero abbattuto di traverso sul sentiero, il taglio è fresco e nel tronco è piantata una freccia con un nastro rosso.", "Dei taglialegna vi chiedono aiuto: ogni albero che abbattono ricresce in una notte, e ora cresce anche dentro le loro capanne.", "Un cervo bianco vi osserva da una radura, poi si allontana piano, come per farsi seguire.", "Decine di bambole di rami appese ai rami bassi, tutte girate verso il vostro accampamento di ieri.", "Un carbonaio vi offre ospitalità, ma il suo forno è troppo grande per il solo carbone.", "Una battuta di caccia di nobili vi scambia per selvaggina, o finge di farlo.", "Un cerchio di funghi alti fino al ginocchio, e dentro una persona addormentata che non si sveglia.", "Un vecchio albero cavo parla con la voce di qualcuno morto da poco, e vi chiede di abbatterlo."], "scoperte": ["Un melo selvatico fuori stagione, carico di frutti dolcissimi.", "Il rifugio di un cacciatore, con trappole pronte e una scorta di carne secca.", "Un sentiero degli animali che porta a una pozza d'acqua pulita e taglia mezza giornata.", "Una pietra coperta di muschio e di rune: con un Tiro Conoscenza ({D}) si capisce dove comincia il bosco che non va attraversato.", "Resina d'ambra che brucia a lungo e tiene lontani gli insetti: basta come torcia per tre notti.", "Un'armatura arrugginita stretta tra le radici di una quercia, con lo stemma ancora leggibile."], "pericoli": ["Il gruppo si perde: Tiro Istinto ({D}) per ritrovare la strada, in caso di fallimento girate a vuoto fino a sera e ognuno marca uno Stress.", "I rovi si chiudono alle vostre spalle: il PG in coda deve superare un Tiro Reazione di Agilità ({D}) o è Trattenuto.", "Un nido di vespe in un tronco cavo, urtato per sbaglio: ogni PG entro distanza Prossima marca uno Stress, a meno che non scappi subito.", "Una tagliola nascosta tra le foglie: il PG che la fa scattare marca un PF e si muove a fatica fino al prossimo riposo.", "Il bosco non vi vuole: spendete una Paura, e durante la notte gli alberi si spostano fino a chiudere il campo in un cerchio.", "Funghi luminosi crescono attorno al campo mentre dormite: chi dorme sul lato del bosco non rimuove Stress con questo riposo."], "avv": ["Lupo Terribile", "Berretto Rosso Macellaio", "Valdenhax", "Treant delle Querce", "Strega Barbagianni"]}, {"id": "rovine", "label": "Rovine e terre bruciate", "tempo": ["Pioggia nera, sporca di fuliggine, che lascia striature sulla pelle.", "Vento che solleva cenere e carta bruciata: pagine di libri volano ovunque.", "Sole impietoso su pietre annerite che restano calde anche di notte.", "Fumo basso che esce dalle crepe nel terreno: qui sotto qualcosa brucia ancora.", "Cielo grigio e piatto, nessuna ombra: è difficile capire che ora sia."], "eventi": ["Una campana suona da una torre crollata a metà: lassù c'è qualcuno, o qualcosa.", "Saccheggiatori rivali hanno trovato un ingresso e vi offrono di dividere il bottino, se fate voi da esca.", "Un vecchio è rimasto nella sua casa bruciata e rifiuta di andarsene: dice che sta aspettando qualcuno.", "Una statua senza testa vi segue: ogni volta che vi girate è un po' più vicina.", "Un mosaico appena ripulito mostra la vostra compagnia, disegnata secoli fa, mentre fugge da qualcosa.", "Una colonna di fumo nero si alza da dietro la collina: qualcuno ha appena dato fuoco a qualcosa di grosso.", "Un muro intero è coperto di nomi incisi, e l'ultimo è scritto con pittura ancora fresca.", "Ragazzini selvatici che vivono nelle cantine vi rubano un oggetto, poi vi sfidano a riprenderlo."], "scoperte": ["Una cantina intatta sotto le macerie, con botti di vino vecchio di un secolo.", "Una fucina abbandonata, con l'incudine e gli attrezzi ancora buoni.", "Un archivio bruciato a metà: le pagine salve parlano di un passaggio sotto la città.", "Il braciere intatto di una Pira spenta: riaccenderlo dà al gruppo una notte al sicuro dall'Umbra.", "Una cassaforte murata, troppo pesante da portare via, con una serratura a simboli.", "Un orto inselvatichito tra le rovine, pieno di verdure e di erbe medicinali."], "pericoli": ["Il pavimento cede su una cantina: il PG che cammina davanti deve superare un Tiro Reazione di Agilità ({D}) o cade e marca un PF.", "Spendete una Paura: un muro pericolante crolla mentre il gruppo ci passa sotto, Tiro Reazione di Agilità ({D}) o {DMG} danni fisici.", "Cenere velenosa nell'aria: chi fruga tra le macerie senza coprirsi il volto marca uno Stress.", "Una vecchia trappola di guerra ancora armata: Tiro Conoscenza ({D}) per riconoscerla prima che scatti contro chi fa strada.", "Le rovine rimbombano: ogni rumore forte fa avanzare di 1 un conto alla rovescia (4), e allo zero si sveglia ciò che dorme qui sotto.", "Braci nascoste sotto la cenere si riaccendono col vento: avviate un conto alla rovescia (3) prima che il fuoco vi tagli la via d'uscita."], "avv": ["Guerriero Scheletrico", "Masnada di Grimmling", "Gargoyle", "Sentinella della Cripta", "Legione Macabra"]}, {"id": "fiume", "label": "Fiume e lago", "tempo": ["Foschia sull'acqua al mattino: il sole la scioglie solo a mezzogiorno.", "Vento di traverso che alza onde corte e cattive anche sul lago.", "Piena: acqua torbida e veloce che si porta dietro alberi interi.", "Bonaccia: il lago è uno specchio perfetto, e nel riflesso il cielo ha un altro colore.", "Pioggia sottile e fredda che rende scivolosi barche e pontili."], "eventi": ["Un traghettatore chiede un pedaggio diverso a ciascuno: a uno una moneta, a un altro un ricordo.", "Una zattera alla deriva porta una gabbia, e nella gabbia qualcuno che supplica di non essere liberato.", "Dei pescatori litigano su una rete troppo pesante da tirare su: dentro c'è qualcosa che si muove.", "Il guado è in mano a una famiglia di pedaggiatori con le balestre già cariche.", "Una nave mercantile arenata su una secca chiede aiuto per alleggerire un carico che non vuole mostrare.", "Un mulino ad acqua gira al contrario, e il mugnaio giura che il fiume ha cominciato a risalire verso la sorgente.", "Un campanile sommerso emerge dal lago con l'acqua bassa, e qualcuno lassù vi fa segnali con uno specchio.", "Una bambina sulla riva opposta grida e indica qualcosa sott'acqua, poi sparisce tra le canne."], "scoperte": ["Una barca a fondo piatto nascosta tra le canne, con remi e una rete.", "Una secca piena di anguille grasse: cibo per tre giorni, se qualcuno sa pescare.", "Un pontile sommerso che fa da guado segreto, visibile solo con l'acqua bassa.", "Un isolotto con un tempietto e una fonte: chi beve rimuove uno Stress.", "Un relitto sul fondale, con una cassa ancora legata al timone.", "Lo scheletro di un pesce enorme arenato sulla riva, perfetto come riparo per la notte."], "pericoli": ["La corrente afferra un PG durante il guado: Tiro Forza ({D}) per resistere, in caso di fallimento finisce a valle e marca uno Stress.", "La barca imbarca acqua: avviate un conto alla rovescia (3) per toccare riva prima di perdere il carico.", "Spendete una Paura: qualcosa di grosso urta lo scafo da sotto, e un PG deve superare un Tiro Reazione di Agilità ({D}) o finisce in acqua.", "Il ghiaccio del lago scricchiola: chi attraversa per ultimo deve superare un Tiro Reazione di Agilità ({D}) o sprofonda e marca un PF.", "Acqua avvelenata a valle di un villaggio morto: chi beve senza bollirla ha svantaggio ai Tiri Forza fino al prossimo riposo lungo.", "La nebbia scende sull'acqua e le barche si perdono di vista: con un Tiro Istinto ({D}) fallito il gruppo si divide in due."], "avv": ["Atototl", "Bestia Branchiata Dentisega", "Sirena", "Tritone Maledetto", "Madre delle Acque"]}, {"id": "cenere", "label": "Deserto di cenere", "tempo": ["Una tempesta di cenere all'orizzonte, alta come una montagna, che avanza lenta.", "Caldo secco di giorno, e di notte un freddo che spacca le labbra.", "Aria ferma e grigia: la cenere sospesa fa sembrare il sole una moneta opaca.", "Vento costante che cancella le vostre tracce in pochi minuti.", "Un acquazzone raro e breve che trasforma la cenere in un fango colloso."], "eventi": ["Una carovana di Senzaporta vi offre acqua in cambio di una storia vera, che non abbiano mai sentito.", "Un cavallo scheletrico ancora sellato vaga da solo, con le bisacce piene di sale e una mappa macchiata di sangue.", "Una città sepolta fino ai tetti: dai comignoli esce aria calda e odore di pane.", "Dei pellegrini bendati camminano verso il centro del deserto, e vi chiedono di guidarli.", "Una torre di vetro fuso spunta dalle dune, e dentro si vede una figura immobile che vi guarda.", "Un custode armato vende l'acqua del suo pozzo a peso d'oro, e ha appena mandato via una famiglia allo stremo.", "Le tracce di un enorme verme scavatore girano in cerchio attorno al vostro campo.", "Un esercito di statue di cenere fermo a metà passo, tutte rivolte verso la città da cui venite."], "scoperte": ["Una cisterna sepolta con acqua ancora dolce, se riuscite a scavare fino al coperchio.", "Una tenda abbandonata con una scorta di veli che proteggono gli occhi dalla cenere.", "La cassa toracica di una bestia colossale, che fa da riparo dal vento.", "Vetro fuso a forma di lama, affilatissimo: un'arma improvvisata che non si spunta mai.", "Una mappa incisa su una roccia, con le oasi segnate da piccoli fuochi.", "Un campo di fiori grigi che crescono nella cenere: i semi, bolliti, sfamano per due giorni."], "pericoli": ["Sete: per ogni giorno senza una fonte, ogni PG deve superare un Tiro Reazione di Forza ({D}) o marca uno Stress.", "La tempesta di cenere vi raggiunge: avviate un conto alla rovescia (4) per trovare riparo, allo zero ognuno marca un PF.", "La cenere nasconde fosse ancora roventi: il PG in testa deve superare un Tiro Reazione di Agilità ({D}) o ci affonda fino al ginocchio e marca un PF.", "Miraggi: con un Tiro Istinto ({D}) fallito il gruppo insegue un'oasi che non esiste e perde mezza giornata.", "Spendete una Paura: le vostre tracce hanno attirato qualcosa che nuota sotto la cenere, ed emerge entro distanza Ravvicinata.", "La cenere entra ovunque: gli attacchi a distanza hanno svantaggio finché qualcuno non pulisce le armi con un Tiro Astuzia ({D})."], "avv": ["Scorpione Gigante", "Squalo di Terra", "Mangiaruggine", "Verme delle Sabbie", "Drago Vulcanico: Tiranno della Cenere"]}, {"id": "umbra", "label": "Terre dell'Umbra", "tempo": ["Il cielo pulsa di colori sbagliati, come un livido che respira.", "Neve nera che non si scioglie sulla pelle, ma sul metallo sì, e fuma.", "Un silenzio così fitto che si sente il cuore dei compagni battere.", "Vento che porta voci: frasi spezzate, dette da persone che non sono qui.", "Luce senza sole: tutto è illuminato, ma niente proietta un'ombra."], "eventi": ["Una Pira spenta in un villaggio vuoto, e intorno le impronte fresche di chi ci ha ballato attorno.", "Un morto tornato cammina accanto a voi per ore, senza parlare, e se accelerate accelera anche lui.", "La casa dove è cresciuto uno di voi, intatta, in mezzo al nulla, con la luce accesa.", "Un gruppo di Toccati dall'Umbra vi offre riparo per la notte, e il loro fuoco è freddo.", "Il sentiero si divide: da una parte sentite voci amiche, dall'altra un pianto di bambino.", "Un dio velato di pietra alto come una torre, e il suo velo si muove anche senza vento.", "Un esploratore dell'Ateneo, solo e affamato, si offre di guidarvi in cambio di cibo e protezione.", "La notte cade di colpo a metà pomeriggio, e nel buio qualcosa comincia ad avvicinarsi."], "scoperte": ["Il braciere da viaggio di un Custode morto, con tre braci ancora vive: ognuna tiene lontana l'Umbra per una notte.", "Un rifugio scavato nella roccia, con simboli di protezione ancora intatti sulla soglia.", "Il diario di un Custode che ha attraversato queste terre, con le soste sicure segnate a margine.", "Un albero d'argento senza foglie: tra le sue radici l'Umbra non riesce a entrare.", "Un frammento d'Umbra solidificata, freddo al tatto: all'Ateneo vale una fortuna, ma chi lo tiene in tasca sogna male.", "Una campana di bronzo appesa a un palo: suonata, fa tacere le voci nel vento per un'ora."], "pericoli": ["Un'ondata d'Umbra: ogni PG lontano da una luce consacrata deve superare un Tiro Reazione di Istinto ({D}) o marca 2 Stress.", "Il terreno dimentica la strada: Tiro Conoscenza ({D}) per orientarsi, in caso di fallimento tornate al campo della notte prima.", "Quando un PG tira con Paura, rivive il suo ricordo peggiore come se fosse adesso e marca uno Stress.", "Spendete una Paura: i morti si alzano attorno al campo e compaiono entro distanza Lontana.", "La luce si consuma in fretta: avviate un conto alla rovescia (4), allo zero le torce sono finite e la prossima notte sarà al buio.", "Una voce chiama uno di voi per nome dal buio: con un Tiro Presenza ({D}) fallito il PG la segue e si separa dal gruppo."], "avv": ["Fantasma", "Zombi Barcollante", "Urco", "Spettro Sussurrante", "Ombra Recisa"]}], "locande4": {"a": [["Il Tizzone", "m"], ["La Lanterna", "f"], ["Il Corvo", "m"], ["La Brace", "f"], ["Il Chiodo", "m"], ["Lo Scudo", "m"], ["La Campana", "f"], ["La Ruota", "f"], ["La Pira", "f"], ["La Botte", "f"], ["Il Mulo", "m"], ["La Civetta", "f"], ["Il Ponte", "m"], ["La Forca", "f"], ["Il Gallo", "m"], ["La Macina", "f"], ["L'Orso", "m"], ["La Candela", "f"], ["Il Velo", "m"], ["Il Salice", "m"]], "b": {"m": ["Stanco", "Spento", "Ubriaco", "Storto", "Muto", "Zoppo", "Guercio", "Affamato", "Bugiardo", "Fortunato", "Insonne", "Vedovo", "Bruciato", "Allegro", "d'Oro", "Senza Fondo", "di Cenere", "che Ride", "Senza Nome", "Nascosto"], "f": ["Stanca", "Spenta", "Ubriaca", "Storta", "Muta", "Zoppa", "Guercia", "Affamata", "Bugiarda", "Fortunata", "Insonne", "Vedova", "Bruciata", "Allegra", "d'Oro", "Senza Fondo", "di Cenere", "che Ride", "Senza Nome", "Nascosta"]}, "tono": ["accogliente e rumorosa, con musica fino a tardi e un cane che balla sui tavoli", "silenziosa e sospettosa: tutti smettono di parlare quando entrate", "fortificata, con le finestre sbarrate e una balestra carica sotto il bancone", "elegante e decaduta, con tovaglie lise e prezzi da palazzo", "affollata di profughi che dormono anche sotto i tavoli", "fumosa e piena di giocatori d'azzardo che puntano anche gli anelli di famiglia", "ricavata nello scafo di una nave rovesciata, a giorni di cammino dal mare", "dove si mangia in silenzio per rispetto dei morti, che ogni tanto si siedono a tavola", "che una volta era un tempio, e usa ancora l'altare come bancone", "piena di cacciatori che si vantano sotto le teste impagliate che li fissano", "mezza crollata, con un lato aperto sul cielo e un albero che cresce in mezzo alla sala", "così pulita da mettere a disagio, con una regola scritta su ogni parete"], "specialita": ["zuppa di radici e pane nero ancora caldo", "birra scura di palude, densa come fango", "stufato di non chiedete cosa", "vino annacquato servito in coppe d'argento", "focaccia alle erbe amare che fa sognare", "carne affumicata di una bestia che non esiste sui libri", "anguille in gelatina, ancora un po' vive", "sidro di mele selvatiche che brucia la gola", "frittelle di castagne cotte sulle braci della Pira", "un liquore verde distillato di nascosto, che non viene mai servito due volte alla stessa persona", "uova sode marinate nell'aceto e nel pepe, a dozzine", "polenta con formaggio di capra e miele scuro", "pesce di lago cotto nell'argilla, da rompere col martello", "un brodo che bolle senza interruzione da undici anni", "grappa alla vipera, con la vipera ancora nella bottiglia", "pane e lardo, l'unica cosa che c'è, ma ce n'è tanto"], "stasera": ["una carovana di Senzaporta che cerca affari e trova guai", "un gruppo di soldati che festeggia una vittoria che nessuno ha visto", "un forestiero incappucciato che paga in monete antiche", "un bardo che canta una canzone su uno dei PG, sbagliando tutto", "due famiglie rivali ai lati opposti della sala, e un matrimonio da organizzare tra loro", "un cacciatore di taglie con un ritratto che somiglia a metà della sala", "una veglia funebre, con il morto seduto a capotavola e nessuno che lo guarda negli occhi", "una gara di bevute con in palio un cavallo, e la campionessa in carica ha ottant'anni", "un erudito dell'Ateneo che offre da bere a chiunque gli racconti un sogno", "un gruppo di pellegrini che non mangia, non beve e fissa la porta", "una partita a dadi in cui un uomo sta perdendo la casa, mentre la moglie guarda in silenzio", "un Custode della Pira che cerca volontari per una notte di guardia, pagati in braci", "un ragazzino che vende mappe del tesoro tutte diverse, tutte false tranne una", "una compagnia di saltimbanchi rimasta senza carro e con un attore in meno", "un ferito che entra barcollando, crolla sul pavimento e stringe una chiave nel pugno", "un esattore delle tasse con due guardie, e tutta la sala che fa finta di non avere un soldo"], "oste": ["morde ogni moneta prima di metterla via", "non ha mai messo piede fuori dalla locanda da quando è stata costruita, e se ne vanta", "tiene una spada dietro il bancone e un elenco di chiunque l'abbia vista sguainata", "ha perso la voce e parla con una lavagnetta piena di insulti già scritti", "cucina divinamente ma caccia via chiunque chieda il sale", "ha seppellito tre soci nell'orto, e giura che sono morti di vecchiaia", "ricorda il nome di chiunque sia passato di qui, anche vent'anni fa", "cancella i debiti degli avventori in cambio di storie, e le scrive tutte in un registro", "manda avanti la locanda insieme a un fantasma che lava i bicchieri", "contrabbanda braci consacrate dalla cantina", "non dorme mai, e di notte spazza la sala cantando sottovoce", "si rifiuta di servire chiunque porti un'arma con un nome"]}, "trappole4": [{"id": "pozzo", "label": "Pozzo con spuntoni", "descrizione": ["Una fessura sottile corre tra le lastre, troppo dritta per essere una crepa.", "Su un quadrato di pavimento la polvere non si posa: scivola giù, attraverso fessure invisibili.", "Battendo il tallone, un tratto del pavimento risponde con un'eco lunga e un odore di ruggine vecchia."], "innesco": ["il peso di due persone sullo stesso tratto", "un passo di corsa: chi cammina piano passa, chi corre no", "la porta d'uscita aperta mentre qualcuno è ancora in mezzo alla sala", "un piede sulla lastra che sembra la più solida di tutte"], "indizio": ["un guanto incastrato tra due lastre, con le dita rivolte verso il basso", "segni di gesso a terra lasciati da qualcuno che l'aveva trovata, cancellati a metà", "un filo d'aria fredda che sale dal pavimento e fa piegare la fiamma", "il bordo di una lastra sbeccato, come morso da una leva"], "disinnesco": ["Un Tiro Astuzia ({D}) per incastrare una lama nel cardine della botola: resta chiusa finché nessuno la toglie.", "Un Tiro Forza ({D}) per gettare di traverso un'asse, una porta divelta o uno scudo e creare un ponte sopra il tratto cavo.", "Un Tiro Conoscenza ({D}) per capire lo schema delle lastre sicure: chi mette i piedi dove li mette il PG passa senza rischi, uno alla volta."], "effetto": "Il pavimento si spalanca: chi è sopra deve superare un Tiro Reazione di Agilità ({D}) o precipitare sugli spuntoni, subire {DMG} danni fisici e restare Trattenuto sul fondo finché qualcuno non lo tira su."}, {"id": "pendolo", "label": "Lama a pendolo", "descrizione": ["Nel soffitto si apre una fenditura lunga quanto il corridoio, nera e profonda.", "Una mezzaluna d'acciaio è sospesa in alto, immobile, coperta di ragnatele dappertutto tranne che sul filo.", "A mezza altezza, le due pareti del corridoio hanno solchi lucidi, come se qualcosa le sfiorasse da secoli."], "innesco": ["una lastra che si abbassa di un dito sotto il tallone", "una corda tesa all'altezza del ginocchio", "la luce di una torcia che raggiunge l'occhio di vetro sopra l'arco", "il silenzio: scatta se nel corridoio nessuno sta parlando"], "indizio": ["un ticchettio regolare dietro le pareti, come un orologio che si carica", "frammenti di ossa e di legno tagliati di netto, tutti alla stessa altezza", "un vecchio elmo spaccato in due, con il pennacchio ancora intatto", "olio fresco che cola da una fessura del soffitto: qualcuno lo tiene in funzione"], "disinnesco": ["Un Tiro Forza ({D}) per infilare una lancia o una spranga nella fenditura e bloccare la lama prima che scenda.", "Un Tiro Astuzia ({D}) per tagliare il cavo che tiene carico il meccanismo senza farlo scattare.", "Un Tiro Agilità ({D}) per contare il ritmo e passare tra un'oscillazione e l'altra; chi segue subito dietro il PG ha vantaggio."], "effetto": "La lama cala dal soffitto in un arco sibilante: chi è nel corridoio deve superare un Tiro Reazione di Agilità ({D}) o subire {DMG} danni fisici, e torna a passare ogni volta che un PG nel corridoio tira con Paura."}, {"id": "allagamento", "label": "Stanza che si allaga", "descrizione": ["Le pareti sono incrostate di sale e di alghe secche fino all'altezza del collo.", "Bocche di bronzo a forma di pesce, spalancate, circondano la stanza appena sotto il soffitto.", "Il pavimento scende verso il centro come il fondo di una vasca, e la porta ha una guarnizione di cuoio tutto attorno."], "innesco": ["un forziere o un oggetto sollevato dal suo piedistallo", "la porta che si richiude alle spalle dell'ultimo", "una catena tirata, che sembra quella di un lampadario", "il tempo: scatta dopo che qualcuno è rimasto dentro per qualche minuto"], "indizio": ["linee incise sulle pareti a intervalli regolari, come le tacche di un pozzo", "pesciolini morti e secchi negli angoli", "un gorgoglio lontano dietro i muri, come una gola che deglutisce", "un odore di fondale e di fango che in un posto asciutto non ha senso"], "disinnesco": ["Un Tiro Forza ({D}) per tenere aperta la porta con una trave o un corpo: l'acqua entra, ma defluisce nel corridoio e non supera la vita.", "Un Tiro Astuzia ({D}) per trovare da dove entrerà l'acqua e tapparlo con stracci, cera e mantelli prima che prenda pressione.", "Un Tiro Conoscenza ({D}) per individuare lo scarico nascosto sotto il pavimento e aprirlo: la stanza si svuota in pochi istanti."], "effetto": "Le porte si sigillano e l'acqua irrompe con forza: chi è dentro deve superare un Tiro Reazione di Forza ({D}) o essere sbattuto contro le pareti e subire {DMG} danni fisici, e avviate un Conto alla Rovescia (4) prima che la stanza sia piena fino al soffitto."}, {"id": "gas", "label": "Gas soporifero", "descrizione": ["Lungo le pareti corrono tubi di rame coperti di verderame, che finiscono in piccoli ugelli rivolti verso il centro.", "Sopra la porta pende un'ampolla di vetro grande come una testa, piena di un fumo lattiginoso che si muove da solo.", "Un tappeto spesso copre il centro della sala, e ogni passo ne solleva un filo di polvere violetta."], "innesco": ["una porta aperta di colpo", "un passo sul tratto centrale della sala", "una fiamma accesa nella stanza", "un libro o un oggetto tolto da uno scaffale"], "indizio": ["un profumo di miele e camomilla, gradevole e fuori posto", "topi e pipistrelli morti, raggomitolati come se dormissero, senza un graffio", "uno sbadiglio che passa da un PG all'altro senza motivo", "una scritta graffiata a terra che si interrompe a metà parola"], "disinnesco": ["Un Tiro Astuzia ({D}) per trovare la sorgente del gas e sigillarla con cera e stracci bagnati prima che si svuoti.", "Un Tiro Conoscenza ({D}) per riconoscere la miscela: un panno imbevuto di aceto o di vino sul viso dà a tutto il gruppo vantaggio per resistere.", "Un Tiro Istinto ({D}) per sentire dove passa la corrente d'aria e aprire uno sfogo: il gas si disperde prima di fare danni."], "effetto": "Una nube dolciastra riempie la stanza: chi la respira deve superare un Tiro Reazione di Istinto ({D}) o crollare Addormentato finché qualcuno non lo scuote, e chi dorme ancora quando il gas si posa subisce {DMG} danni fisici e si sveglia senza ricordare l'ultima ora."}, {"id": "rune", "label": "Rune esplosive", "descrizione": ["Sulla soglia corre una fila di rune minuscole, incise così fini da sembrare graffi.", "Un sigillo di cera rossa chiude il passaggio, e sotto la cera qualcosa pulsa di luce arancione.", "Le lettere di un'iscrizione sulla parete brillano appena, come braci sotto la cenere, quando ci si avvicina."], "innesco": ["una mano che tocca la superficie incisa", "qualcuno che legge l'iscrizione ad alta voce", "chiunque abbia un battito: i morti passano senza danno", "una magia lanciata entro distanza Ravvicinata"], "indizio": ["un odore di zolfo e di capelli bruciati", "la polvere a terra disposta a raggiera, spazzata da un'esplosione vecchia", "un formicolio ai denti di chi pratica la magia", "sagome umane annerite sulle pareti, con le braccia alzate"], "disinnesco": ["Un Tiro Conoscenza ({D}) per leggere le rune al contrario, a mezza voce, e scioglierle una alla volta.", "Un Tiro Astuzia ({D}) per raschiare via un solo segno chiave con la punta di un coltello, senza toccare gli altri.", "Un Tiro Incantesimo ({D}) per assorbire la carica in un oggetto, che resta caldo e pericoloso fino all'alba."], "effetto": "Le rune esplodono in un lampo di fuoco: chi è entro distanza Prossima deve superare un Tiro Reazione di Agilità ({D}) o subire {DMG} danni magici ed essere scagliato fino a distanza Ravvicinata."}, {"id": "rotante", "label": "Pavimento che ruota", "descrizione": ["Il pavimento della sala è un unico disco di pietra, separato dalle pareti da una scanalatura larga un dito.", "Un grande mosaico a forma di rosa dei venti copre il pavimento, ma le punte non indicano il nord.", "La stanza è perfettamente rotonda, con quattro porte identiche, e l'affresco sul soffitto sembra girare se lo si fissa."], "innesco": ["una porta aperta dall'interno", "il peso che si sposta oltre il centro della sala", "una leva nascosta in un portatorce che sembra uguale agli altri", "lo scoccare di ogni ora, come un orologio che nessuno può fermare"], "indizio": ["graffi ad arco sul pavimento, come quelli di una porta pesante", "impronte nella polvere che finiscono dritte contro un muro", "un ronzio di ingranaggi sotto i piedi, lento e profondo", "un mucchio di ossa schiacciato nella fessura lungo il bordo"], "disinnesco": ["Un Tiro Forza ({D}) per piantare una spranga tra il pavimento e la parete: la pietra geme, ma non gira.", "Un Tiro Conoscenza ({D}) per capire la sequenza delle rotazioni e sapere, ogni volta, quale porta porta dove.", "Un Tiro Astuzia ({D}) per trovare il fermo sotto una lastra del bordo e bloccarlo con un coltello: la sala resta ferma finché il coltello regge."], "effetto": "La sala gira di scatto con un boato di pietra: chi è dentro deve superare un Tiro Reazione di Agilità ({D}) o essere scaraventato contro le pareti e subire {DMG} danni fisici, e quando si ferma ogni porta dà su un luogo diverso da prima."}, {"id": "specchio", "label": "Specchio che intrappola", "descrizione": ["Uno specchio alto quanto una porta, con la cornice d'argento annerita, riflette la stanza ma non la luce delle torce.", "Il riflesso di chi si avvicina allo specchio si muove con un istante di ritardo.", "Nella stanza riflessa c'è una sedia in più, e qualcuno ci è seduto."], "innesco": ["uno sguardo nello specchio che dura più di un respiro", "un nome pronunciato davanti al vetro: viene preso chi lo porta", "chi volta le spalle allo specchio", "una mano che tocca il vetro"], "indizio": ["mani premute dall'altra parte del vetro, che compaiono solo nel riflesso", "un oggetto a terra davanti allo specchio, che nel riflesso non c'è", "la stanza riflessa più pulita e più nuova di quella vera", "una coperta che copriva lo specchio, scivolata a terra da poco"], "disinnesco": ["Un Tiro Astuzia ({D}) per coprire lo specchio con un mantello muovendosi a occhi chiusi, guidati dalla voce di un compagno.", "Un Tiro Conoscenza ({D}) per capire che lo specchio va girato verso il muro: se riflette solo pietra, si addormenta.", "Un Tiro Forza ({D}) per spezzare il vetro con un colpo solo; chi colpisce marca uno Stress per le schegge, ma chiunque fosse prigioniero ricade fuori."], "effetto": "Il vetro si fa liquido e risucchia il bersaglio: deve superare un Tiro Reazione di Istinto ({D}) o restare Intrappolato nel riflesso, dove vede e sente i compagni ma non può agire, e subisce {DMG} danni magici ogni volta che qualcuno lo chiama per nome."}, {"id": "campana", "label": "Campana che chiama i morti", "descrizione": ["Una campana di bronzo verde pende dal soffitto, e il batacchio è un femore legato con filo di ferro.", "In cima a un campanile senza scale, una campana senza corda oscilla appena, anche se non c'è vento.", "Una campanella d'argento è appoggiata su un altare di ossa, capovolta come una coppa e piena di cenere."], "innesco": ["un rumore forte nella sala: un grido, un colpo, una porta sbattuta", "una corrente d'aria entrata da una porta lasciata aperta", "una mano viva che la tocca, anche solo per fermarla", "il furto di una qualsiasi offerta lasciata nei paraggi"], "indizio": ["terra smossa nelle tombe intorno, dall'interno verso l'esterno", "un ronzio basso che vibra nelle ossa quando qualcuno alza la voce", "tutti i cadaveri dei dintorni con la testa girata verso la campana", "stracci imbottiti legati attorno al batacchio, ormai marci e strappati"], "disinnesco": ["Un Tiro Agilità ({D}) per arrampicarsi fino alla campana e fasciare il batacchio con un mantello: anche se qualcosa la scuote, non suona più.", "Un Tiro Forza ({D}) per tirare giù la campana e capovolgerla a terra: rovesciata non suona e non chiama.", "Un Tiro Conoscenza ({D}) per recitare il congedo dei morti tra un rintocco e l'altro: chi si stava alzando torna a giacere."], "effetto": "Il rintocco fa tremare le ossa: chi è entro distanza Ravvicinata deve superare un Tiro Reazione di Istinto ({D}) o subire {DMG} danni magici e marcare uno Stress, e al terzo rintocco i morti del luogo si alzano entro distanza Lontana."}, {"id": "cripta", "label": "Cripta che si sigilla", "descrizione": ["Una lastra di pietra enorme è sospesa sopra l'ingresso della cripta, trattenuta da catene arrugginite.", "Ai lati dell'ingresso corrono scanalature profonde, fatte per far scendere qualcosa di molto pesante.", "Dentro la cripta i sarcofagi sono tutti aperti, e sulle pareti ci sono tacche incise a gruppi di sette."], "innesco": ["il coperchio di un sarcofago sollevato", "l'ultimo del gruppo che supera la soglia", "una candela votiva spenta", "un oggetto prezioso tolto dalle mani di un morto"], "indizio": ["graffi di unghie sul lato interno dello stipite", "aria viziata e immobile, senza un filo di corrente", "un sarcofago vuoto con il coperchio appoggiato accanto e una targa senza nome, come in attesa", "un cadavere seduto vicino all'ingresso, con in grembo una lettera mai finita"], "disinnesco": ["Un Tiro Forza ({D}) per incastrare una trave o il coperchio di un sarcofago sotto il punto in cui scende la lastra: si ferma a un palmo da terra e lascia uno spiraglio.", "Un Tiro Conoscenza ({D}) per trovare la formula incisa per i sacerdoti che dovevano uscire: pronunciata, la lastra si risolleva.", "Un Tiro Astuzia ({D}) per sbloccare il contrappeso nascosto dietro una lapide e riaprire il passaggio dall'interno."], "effetto": "La lastra cala con un tonfo che toglie il fiato: chi è sulla soglia deve superare un Tiro Reazione di Agilità ({D}) o subire {DMG} danni fisici e restare Trattenuto sotto la pietra, mentre chi è dentro resta chiuso al buio con aria per poche ore."}, {"id": "ponte", "label": "Ponte che cede", "descrizione": ["Un ponte di corda e assi attraversa la voragine, e le assi centrali sono più nuove delle altre.", "Un ponte di pietra ad arco, elegante e sottile, ha una crepa che corre lungo la chiave di volta.", "Una passerella di legno attraversa l'acqua nera, sostenuta da pali che oscillano a ogni soffio di vento."], "innesco": ["il peso di più di due persone insieme", "il passo di chi arriva a metà", "chi corre o salta", "il vento che si alza quando qualcuno è già sopra"], "indizio": ["frammenti caduti in basso, freschi, senza polvere né muschio", "un gemito della struttura a ogni passo, sempre più acuto", "uccelli che volano sopra il ponte ma non ci si posano mai", "riparazioni recenti fatte male, come per invitare qualcuno a passare"], "disinnesco": ["Un Tiro Agilità ({D}) per passare per primi, leggeri, e fissare una corda di sicurezza sull'altra sponda: chi ci si tiene non cade.", "Un Tiro Istinto ({D}) per sentire dove la struttura cede e indicare agli altri dove non mettere i piedi.", "Un Tiro Forza ({D}) per alleggerire il carico facendo passare zaini e armature su una corda tesa: senza quel peso, il ponte regge."], "effetto": "Il ponte cede sotto i piedi: chi è sopra deve superare un Tiro Reazione di Agilità ({D}) per aggrapparsi a ciò che resta, altrimenti precipita e subisce {DMG} danni fisici, e il gruppo resta diviso tra le due sponde."}, {"id": "statua", "label": "Statua che lancia dardi", "descrizione": ["Una statua di guerriero inginocchiato tiene le mani giunte, e tra le dita ci sono fori neri.", "Un busto di antico notabile, in cima a una colonna, fissa il corridoio con la bocca socchiusa, come per dire qualcosa.", "Una dea velata di marmo regge una cesta, e nella cesta, al posto dei frutti, ci sono punte di ferro."], "innesco": ["chi le passa davanti senza inchinarsi", "un'arma estratta nella sala", "un'offerta presa dal piedistallo", "chi la tocca o le volta le spalle"], "indizio": ["dardi spezzati piantati nella parete opposta, tutti alla stessa altezza", "occhi di vetro che sembrano seguire chi si muove", "fori puliti e lucidi, in un luogo dove tutto il resto è polvere", "un cadavere davanti alla statua, piegato in un inchino che non ha finito"], "disinnesco": ["Un Tiro Astuzia ({D}) per riempire i fori di cera o di argilla senza far scattare il meccanismo.", "Un Tiro Forza ({D}) per far ruotare la statua sul piedistallo finché non guarda il muro.", "Un Tiro Presenza ({D}) per renderle omaggio con i gesti antichi: il meccanismo riconosce un fedele e tace."], "effetto": "Una raffica di dardi parte dalla pietra: ogni PG entro distanza Lontana sulla sua linea deve superare un Tiro Reazione di Agilità ({D}) o subire {DMG} danni fisici e restare Vulnerabile finché non spende un'azione per strapparsi via la punta."}, {"id": "catene", "label": "Rete di catene", "descrizione": ["Dal soffitto pendono matasse di catena arrotolate, lucide d'olio, pronte a cadere.", "Le pareti della sala sono foderate di catene arrugginite, tese come le corde di un'arpa.", "Al centro della sala c'è un ceppo di ferro con quattro catene che finiscono in ganci a forma di mano."], "innesco": ["un filo all'altezza della caviglia", "una gabbia o un forziere aperto", "un grido: le catene rispondono al rumore", "il peso sul tratto centrale del pavimento"], "indizio": ["un tintinnio lieve che risponde a ogni passo", "graffi a spirale sulle colonne, come se qualcosa le avesse strette", "gocce d'olio fresco sul pavimento, in un posto che nessuno pulisce", "uno scheletro avvolto nelle catene, sospeso a mezz'aria in un angolo"], "disinnesco": ["Un Tiro Astuzia ({D}) per bloccare l'argano con un cuneo: le catene si muovono, ma non si stringono.", "Un Tiro Forza ({D}) per strappare il perno da cui partono tutte le catene.", "Un Tiro Conoscenza ({D}) per capire che le catene cercano il ferro: chi lascia armi e armature fuori dalla sala passa senza essere toccato."], "effetto": "Le catene scattano come serpenti: chi è entro distanza Ravvicinata deve superare un Tiro Reazione di Agilità ({D}) o essere avvolto e Trattenuto, e subisce {DMG} danni fisici ogni volta che prova a liberarsi e fallisce."}, {"id": "illusione", "label": "Illusione di un passaggio", "descrizione": ["Un corridoio si apre dove la mappa diceva muro, illuminato da una luce calda e invitante.", "Una scala scende nel buio, con gradini perfetti e senza un granello di polvere.", "Un ponte di pietra largo e solido attraversa la voragine, esattamente dove serve."], "innesco": ["il primo passo sul falso pavimento", "il peso di chi ci si appoggia, convinto che regga", "chi ci entra di corsa, inseguito o in fuga", "una voce che grida «Di qua!»: l'illusione si rafforza quando qualcuno ci crede ad alta voce"], "indizio": ["la polvere sospesa nell'aria che si ferma a metà, come contro un vetro", "un sasso lanciato dentro che non fa alcun rumore", "le torce che là dentro non proiettano ombre", "una corrente d'aria che sale dal basso, da un punto dove non dovrebbe esserci niente"], "disinnesco": ["Un Tiro Istinto ({D}) per riconoscere il falso e trovare accanto il passaggio vero, più stretto e più buio.", "Un Tiro Conoscenza ({D}) per sciogliere la trama dell'incanto: l'immagine si strappa come una tenda e mostra cosa c'è davvero.", "Un Tiro Astuzia ({D}) per sondare il terreno con un bastone e segnare col gesso il bordo del vuoto."], "effetto": "Il passaggio svanisce sotto i piedi: chi ci è entrato deve superare un Tiro Reazione di Agilità ({D}) o cadere nel vuoto nascosto e subire {DMG} danni fisici, ritrovandosi solo e separato dal gruppo."}, {"id": "fuoco_capovolto", "label": "Fuoco sacro capovolto", "descrizione": ["Un braciere pende dal soffitto a testa in giù, e la sua fiamma brucia verso il basso, nera e fredda.", "Al centro della sala arde un fuoco sacro, ma le fiamme sono di un viola livido e il gelo sale dal pavimento.", "Candele votive allineate su un altare bruciano all'incontrario: la cera risale e la luce rende tutto più buio."], "innesco": ["una preghiera detta ad alta voce", "una fiamma vera portata vicino all'altare", "chi offre qualcosa al fuoco, come si fa davanti a una Pira", "un ferito che entra nella luce: il fuoco sente il sangue"], "indizio": ["brina sulle pareti, proprio accanto alla fiamma", "le ombre dei presenti che puntano verso il fuoco invece che lontano", "fedeli congelati in ginocchio, con il viso sereno e le labbra blu", "torce che si abbassano e tremano, piegate da un vento che non c'è"], "disinnesco": ["Un Tiro Conoscenza ({D}) per celebrare il rito della Pira al contrario, dalla fine all'inizio: la fiamma si raddrizza e torna calda.", "Un Tiro Forza ({D}) per soffocarla sotto terra consacrata o sotto la cenere di un fuoco sacro vero.", "Un Tiro Istinto ({D}) per offrirle un ricordo felice invece del calore: il PG marca uno Stress, e la fiamma si spegne sazia."], "effetto": "Il fuoco capovolto risucchia il calore dei vivi: chi è entro distanza Ravvicinata deve superare un Tiro Reazione di Forza ({D}) o subire {DMG} danni magici da gelo e restare Vulnerabile finché non si scalda a una fiamma vera."}, {"id": "budello", "label": "Budello vivente", "descrizione": ["Le pareti del passaggio sono lisce, umide e tiepide, e ogni tanto si contraggono.", "Il pavimento cede appena sotto i piedi, come un materasso, e dalle pieghe cola un liquido dolciastro.", "In fondo al cunicolo si intravede una sala piena di tesori lucidi, troppo puliti per un posto così."], "innesco": ["il calore di molti corpi nello stesso tratto", "una ferita aperta: la creatura sente il sangue", "un oggetto raccolto da terra", "chi si ferma troppo a lungo nello stesso punto"], "indizio": ["un battito profondo, che si sente appoggiando l'orecchio alla parete", "ossa levigate e lucide, senza un brandello di carne, raccolte in un angolo", "l'aria che va e viene a intervalli lenti, come un respiro", "monete e fibbie mezze sciolte, sparse a terra"], "disinnesco": ["Un Tiro Istinto ({D}) per capire il ritmo del respiro e attraversare quando la creatura espira e si rilassa.", "Un Tiro Conoscenza ({D}) per trovare il nodo di nervi sotto la parete: un colpo preciso, e il passaggio resta inerte per un'ora.", "Un Tiro Forza ({D}) per piantare una torcia accesa nella carne: la creatura si contrae, poi si spalanca e lascia passare chi corre."], "effetto": "Il passaggio si stringe come una gola: chi è dentro deve superare un Tiro Reazione di Forza ({D}) o restare Trattenuto tra le pareti e subire {DMG} danni fisici dagli acidi, finché un alleato non lo strappa fuori."}, {"id": "porta_mimetica", "label": "Porta mimetica", "descrizione": ["Una porta di quercia con borchie di ferro, perfetta, nell'unico punto della stanza dove una porta non serve.", "Una porta uguale alle altre, ma le venature del legno si muovono piano, come un respiro.", "Una porta socchiusa da cui filtrano una luce calda e un profumo di pane appena sfornato."], "innesco": ["una mano sulla maniglia", "una chiave infilata nella serratura", "chi bussa", "chi si ferma sulla soglia a guardare dentro"], "indizio": ["una maniglia tiepida e appena umida", "cardini che non sono fissati al muro", "piccoli denti gialli nella serratura, se la si guarda con la torcia", "graffi sul pavimento, come se la porta si fosse spostata da un muro all'altro"], "disinnesco": ["Un Tiro Istinto ({D}) per lanciarle da lontano cibo o un animale vivo, parlando piano: la creatura mangia, si sazia e torna a dormire contro il muro.", "Un Tiro Astuzia ({D}) per inchiodare i cardini al muro prima che la creatura si stacchi.", "Un Tiro Conoscenza ({D}) per riconoscere il punto molle sotto la serratura: un colpo lì, e la creatura si ritira nella pietra."], "effetto": "La porta si spalanca come una bocca: chi è entro distanza di Mischia deve superare un Tiro Reazione di Agilità ({D}) o essere afferrato dalla lingua appiccicosa, restare Trattenuto e subire {DMG} danni fisici a ogni morso finché non si libera."}], "complicazioni4": {"Combattimento": [["Lama incastrata", "L'arma del PG resta piantata nello scudo, nella trave o nell'osso del nemico. Può lasciarla e combattere con ciò che ha, oppure strapparla via con un Tiro Forza ({D}) restando Vulnerabile fino al suo prossimo tiro."], ["Rinforzi alle spalle", "Spendete una Paura: un secondo gruppo di avversari compare entro distanza Lontana, proprio dalla direzione in cui i PG pensavano di ritirarsi. La via di fuga adesso passa in mezzo al pericolo, o non c'è."], ["Il capo scappa", "Il comandante nemico fischia, si volta e corre via con qualcosa stretto sotto il braccio, lasciando i suoi a coprirgli la ritirata. I PG possono inseguirlo e lasciarsi dietro gli altri, o chiudere lo scontro e perderlo di vista."], ["Colpo che trapassa", "Il colpo va a segno fin troppo bene: attraversa il bersaglio e sta per raggiungere un alleato entro distanza Prossima. Il PG sceglie se trattenerlo e infliggere solo metà dei danni, o lasciarlo andare e far marcare uno Stress all'alleato."], ["Incendio", "Una lanterna rovesciata appicca il fuoco a paglia, tende o vecchie travi: avviate un Conto alla Rovescia (3), e a zero chi è entro distanza Ravvicinata dalle fiamme subisce {DMG} danni fisici. I PG possono spegnerlo perdendo tempo, o spingerci dentro i nemici."], ["Ostaggio", "Un avversario afferra un PNG indifeso e gli punta la lama alla gola: «Indietro, o lo apro.» Chi avanza rischia la vita dell'ostaggio; chi arretra lascia ai nemici il terreno migliore."], ["Disarmato", "Il colpo nemico fa volare via l'arma del PG, che rotola entro distanza Ravvicinata, in mezzo agli avversari. Recuperarla vuol dire attraversare il pericolo; lasciarla vuol dire arrangiarsi con una sedia, un sasso o i pugni."], ["Chiuso in mezzo", "Spendete una Paura: due avversari si muovono insieme e chiudono un PG tra loro. È Vulnerabile finché non si libera con un Tiro Agilità ({D}) o finché un alleato non arriva a coprirgli le spalle."], ["Pietà interessata", "Un avversario getta l'arma e implora pietà gridando un'informazione preziosa, mentre i suoi compagni approfittano della pausa per riorganizzarsi. Proteggerlo costa un'azione a un PG; ignorarlo significa perdere ciò che sa."], ["Sangue negli occhi", "Un taglio alla fronte acceca il PG con il suo stesso sangue: ha svantaggio ai tiri attacco finché non spende un'azione per pulirsi. Oppure combatte alla cieca, e ogni suo attacco mancato colpisce la cosa più vicina."], ["Il pavimento cede", "Il peso della mischia spacca assi o lastre: chi è entro distanza di Mischia dal punto più affollato deve superare un Tiro Reazione di Agilità ({D}) o precipitare al livello di sotto, insieme all'avversario più vicino e lontano dagli alleati."], ["Ordine urlato", "Un nemico grida un ordine e tutti gli avversari si muovono come un'onda: spendete una Paura per rendere protagonisti due avversari subito. I PG possono serrare i ranghi e reggere l'urto insieme, o sparpagliarsi e affrontarli uno a uno."]], "Esplorazione": [["Buio improvviso", "Una corrente d'aria spegne torce e lanterne tutte insieme, e nel buio qualcosa si sposta. Riaccendere costa tempo e fa rumore; procedere al tatto dà svantaggio a ogni tiro per orientarsi o notare pericoli."], ["Crollo alle spalle", "Un boato, una nube di polvere: il passaggio da cui sono arrivati è bloccato. Scavare richiede un Conto alla Rovescia (4) e fa un gran rumore; l'alternativa è andare avanti senza sapere se c'è un'altra uscita."], ["Rivali avanti", "Trovano un bivacco lasciato da pochi minuti: braci calde, una ciotola ancora piena e un diario con un coltello piantato su una pagina che parla dei PG. Possono correre per superare i rivali, o seguirli da lontano e lasciare che aprano la strada."], ["Rimasto solo", "Nel buio o nella nebbia, un PG si accorge di essere solo: gli altri sono a distanza Lontana, e tra loro c'è qualcosa che respira. Gridare riunisce il gruppo, ma sveglia anche quello."], ["Strettoia", "Il passaggio si restringe in una fessura dove si striscia di fianco: per attraversarla bisogna lasciare indietro zaini, armature pesanti o armi lunghe. Chi non vuole separarsene deve cercare un'altra strada, da solo."], ["La guida si ferma", "La guida impallidisce davanti a un segno inciso nella roccia che conosce e non vuole spiegare. Insistere la convince ad andare avanti per metà della paga promessa; lasciarla tornare indietro significa proseguire senza chi conosce la strada."], ["Caduto di sotto", "Un oggetto importante scivola nella crepa, nell'acqua o nel buio sotto il passaggio, e lo si vede ancora brillare in basso. Recuperarlo richiede un Tiro Agilità ({D}) e tempo che il gruppo forse non ha."], ["L'eco che imita", "Ogni volta che i PG fanno rumore, da lontano torna lo stesso suono, un istante dopo e un po' più vicino. Qualcosa li imita: avviate un Conto alla Rovescia (4), e a zero la cosa li ha raggiunti."], ["Muro nuovo", "Dove la mappa segnava una sala c'è un muro di mattoni freschi, e dall'altra parte qualcuno sta lavorando con un piccone. Abbatterlo fa rumore; cercare un'altra via significa entrare in una zona che nessuna mappa riporta."], ["Scia di sangue", "Una scia di sangue fresco attraversa il cammino e si infila in una spaccatura laterale. Qualcuno ferito, o qualcosa che ha appena mangiato: seguirla porta fuori strada, ignorarla significa lasciarsela alle spalle."], ["Nido calpestato", "Un PG mette il piede in un nido: uova, piccoli, qualcosa che pigola. Da lontano arriva un verso di risposta, furioso. Fuggire subito lascia tutto com'è; restare permette di prendere qualcosa di prezioso dal nido, a caro prezzo."], ["Ferita sporca", "Un PG si taglia su ferro arrugginito o su una spina nera e marca uno Stress: la ferita pulsa e prude. Può fermarsi a curarla subito, perdendo tempo, oppure ignorarla e marcare un altro Stress al prossimo tiro con Paura."]], "Sociale": [["La parola sbagliata", "Un PG usa un'espressione innocente che qui è un insulto pesante, e la sala si zittisce. Può scusarsi in pubblico e perdere la faccia, o tenere il punto e farsi un nemico."], ["Il testimone", "Spendete una Paura: entra qualcuno che ha visto i PG fare proprio ciò che ora stanno negando. Non dice niente, li guarda e aspetta. Comprarne il silenzio costa; affrontarlo davanti a tutti attira domande."], ["Offerta al rialzo", "Un terzo interlocutore si siede al tavolo e offre al PNG il doppio di quanto offrono i PG. Possono rilanciare con qualcosa che non volevano dare, o screditare il rivale con un Tiro Presenza ({D})."], ["Una faccia che ricorda", "Il PNG si irrigidisce: un PG gli ricorda qualcuno che lo ha tradito, nel viso o nei modi. Finché quel PG parla, i tiri sociali hanno svantaggio; deve tacere o guadagnarsi la fiducia in un altro modo."], ["Chiamato per nome", "Dal fondo della sala qualcuno saluta un PG ad alta voce, con il suo vero nome o con il nome di una vecchia vita. Rispondere conferma chi è; ignorarlo lo fa sembrare uno che ha qualcosa da nascondere."], ["La rissa accanto", "Al tavolo vicino volano bicchieri, e una sedia rotola fino ai piedi dei PG. Restarne fuori significa perdere il PNG nella confusione; intervenire significa scegliere da che parte stare."], ["Una piccola cosa in più", "Il PNG accetta troppo in fretta, e chiede solo un dettaglio in più: una firma, un nome, una stretta di mano davanti a testimoni. Rifiutare manda all'aria l'accordo; accettare lega i PG a qualcosa che ancora non conoscono."], ["Solo a uno", "Il PNG dirà la verità, ma soltanto a uno dei PG, da solo, in una stanza chiusa. Gli altri dovranno fidarsi di quello che racconterà: il gruppo deve scegliere chi entra."], ["Controllo", "Una pattuglia entra e chiede i documenti a tutti: avviate un Conto alla Rovescia (3) prima che arrivi al tavolo dei PG. Possono andarsene ora, lasciando il discorso a metà, o restare e mentire con un Tiro Presenza ({D})."], ["Lacrime vere", "Il PNG crolla e piange, sinceramente, e la richiesta diventa una supplica davanti a tutta la sala. Chi rifiuta marca uno Stress e passa per un mostro; chi accetta si prende un peso in più."], ["Il pettegolezzo corre", "Quello che i PG hanno appena detto viene ripetuto, storpiato, prima ancora che escano dalla porta. Domani circolerà una versione peggiore: possono rincorrerla per smentirla, o sfruttarla."], ["Giudici in pubblico", "Due PNG chiedono ai PG, davanti a tutti, di dire chi dei due ha ragione. Qualunque risposta diano, uno dei due diventa un nemico; tacere li fa sembrare deboli e fa ridere la sala."]], "Viaggio": [["La bestia zoppica", "Il mulo o il cavallo perde un ferro e zoppica: a questo ritmo il viaggio dura un giorno in più. Lasciare parte del carico lo salva; spingerlo rischia di perderlo del tutto."], ["Guado in piena", "Il fiume è salito nella notte e il guado è sotto un'acqua torbida e veloce. Attraversare adesso richiede un Tiro Forza ({D}) per ciascuno, e chi fallisce perde qualcosa nella corrente; aspettare costa un giorno."], ["Compagni di strada", "Una famiglia con un carretto chiede di viaggiare con i PG, perché ha paura di qualcuno. Accoglierla rallenta il gruppo e attira chi la cerca; respingerla significa lasciarla sola sulla strada."], ["Il bivacco occupato", "Il riparo dove volevano passare la notte è già preso da un gruppo armato che finge di non vederli. Dividere il fuoco con loro è un rischio; proseguire significa dormire all'aperto."], ["Il cielo si guasta", "Il cielo diventa color rame e il vento cambia di colpo: la tempesta arriverà entro un'ora. Correre verso un riparo costa uno Stress a ogni PG; fermarsi a prepararsi qui li lascia esposti alla prima raffica."], ["Pedaggio", "Sul ponte c'è una sbarra e tre figure armate chiedono un pedaggio assurdo: un oggetto a testa, scelto da loro. Pagare, trattare, guadare più a valle o passare con la forza."], ["Orme in più", "Accanto alle loro orme, sulla strada già percorsa, ci sono impronte nuove che vanno nella stessa direzione. Qualcuno li segue: tendergli un agguato costa mezza giornata, ignorarlo significa lasciarlo avvicinare."], ["Il ferito sul ciglio", "Un uomo ferito li chiama dal ciglio della strada, con accanto una borsa piena e nessuna traccia di aggressori. Fermarsi può voler dire un'imboscata; passare oltre può voler dire lasciar morire un innocente."], ["In tondo", "Al tramonto i PG riconoscono un albero spezzato: lo avevano superato all'alba. Hanno girato in tondo e ognuno marca uno Stress. Possono fidarsi della mappa, o dell'istinto di uno di loro con un Tiro Istinto ({D})."], ["Ruota spaccata", "La ruota del carro si spacca in un solco. Ripararla richiede un Tiro Astuzia ({D}) e qualche ora di sosta in un posto scoperto; abbandonare il carro significa portarsi in spalla solo ciò che serve davvero."], ["Porte sbarrate", "Il villaggio dove contavano di rifornirsi ha sbarrato le porte, e dalle mura qualcuno grida di andarsene. Dentro c'è ciò che serve, fuori arriva la notte: convincerli richiede un Tiro Presenza ({D}) e una buona ragione."], ["Tutto fugge", "Uno stormo, poi un branco di cervi, poi una marea di topi: tutto scappa nella direzione opposta alla loro. Spendete una Paura: qualcosa di grosso si avvicina entro distanza Remota. Nascondersi e aspettare, o voltarsi e correre con gli animali."]], "Infiltrazione": [["Cambio anticipato", "Il turno delle sentinelle cambia prima del previsto, e due guardie fresche si piazzano proprio sul percorso dei PG. Aspettare costa tempo; passare adesso richiede un Tiro Astuzia ({D}) con svantaggio."], ["Il cane", "Un cane alza il muso verso il nascondiglio dei PG e ringhia piano, ancora indeciso. Un boccone lo zittisce, se qualcuno ne ha uno; altrimenti abbaia, e avviate un Conto alla Rovescia (3) per l'allarme."], ["Porta sbarrata", "La porta che doveva essere aperta è sbarrata dall'interno, e dall'altra parte qualcuno russa. Svegliarlo per farsi aprire è un azzardo; tornare indietro significa perdere il percorso più sicuro."], ["La parola d'ordine", "Una guardia chiede al PG travestito la parola d'ordine del turno, o il nome del suo capitano. Ha un Tiro Presenza ({D}) per inventare qualcosa di credibile, o un istante per colpire prima che gridi."], ["Un altro intruso", "In una stanza buia i PG si trovano faccia a faccia con un altro intruso, coltello in mano, sorpreso quanto loro. Se qualcuno grida, cadono tutti: un patto sottovoce o un colpo silenzioso."], ["Un rumore di troppo", "Un vaso cade, un'asse scricchiola, una fibbia tintinna. Ogni PG Nascosto deve scegliere: restare immobile e sperare, o spostarsi subito verso un nuovo riparo con un Tiro Agilità ({D})."], ["Allarme muto", "Un filo sottile si spezza sotto il piede di un PG, e da qualche parte lontano suona un campanello che loro non sentono. Spendete una Paura e avviate in segreto un Conto alla Rovescia (4); se i PG se ne accorgono, possono correre o cercare il campanello per zittirlo."], ["Chiave spezzata", "La chiave rubata entra nella serratura e si spezza dentro. Forzarla richiede un Tiro Astuzia ({D}) e fa rumore; cercare un'altra via significa passare dai tetti o dalle cucine."], ["Il prigioniero", "Un prigioniero vede i PG attraverso le sbarre e li supplica di liberarlo, a voce sempre più alta. Liberarlo è un peso in più, zittirlo richiede di convincerlo, ignorarlo lo fa urlare."], ["Lama di luce", "Qualcuno apre una porta e una lama di luce taglia il corridoio proprio dove si trovano i PG. Hanno un istante: un Tiro Reazione di Agilità ({D}) per sparire nell'ombra, oppure restare fermi e inventarsi una scusa."], ["Non è qui", "La cassaforte è vuota, o la persona da trovare dorme in un'altra ala. C'è un biglietto, una traccia, un indizio: porta più in profondità, dove le guardie sono il doppio."], ["Uscita chiusa", "Spendete una Paura: la finestra, la grata o la barca su cui contavano per uscire è sorvegliata, o sparita. Serve un'altra uscita, mentre dentro qualcuno ha già notato che manca qualcosa."]], "Magia": [["Il prezzo", "L'incantesimo funziona, ma chiede qualcosa in cambio. Il giocatore sceglie: il PG marca 2 Stress, oppure dimentica per sempre un ricordo caro e lo racconta al tavolo prima di perderlo."], ["Effetto di troppo", "La magia esce più forte del previsto e investe anche un bersaglio non voluto entro distanza Ravvicinata: un alleato, un innocente o qualcosa di fragile. Il PG sceglie chi, prima di sapere quanto è grave."], ["Impronta luminosa", "Dove è stata lanciata la magia resta un segno luminoso, visibile a chi sa guardare: chiunque arrivi dopo saprà che i PG sono passati di qui. Cancellarlo richiede tempo e un Tiro Conoscenza ({D})."], ["Qualcosa ascolta", "Il lancio apre per un istante una fessura nell'aria, e dall'altra parte qualcosa nota il PG. Può richiuderla subito marcando uno Stress, o lasciarla aperta e sentire la voce che lo chiama per nome."], ["Rovescio", "L'effetto si capovolge: la cura brucia, lo scudo attira i colpi, la luce fa buio. Il PG può interrompere tutto e perdere l'incantesimo, o insistere con un Tiro Incantesimo ({D}): se fallisce, subisce {DMG} danni magici."], ["L'oggetto si sveglia", "Un oggetto magico nello zaino reagisce all'incantesimo: si scalda, vibra, sussurra. Chi lo porta può soffocarlo marcando uno Stress, o lasciarlo fare: per un istante indica una direzione, sempre la stessa."], ["Fiamme spente", "La magia beve tutta la luce intorno: torce, lanterne e fuochi entro distanza Lontana si spengono di colpo. Nel buio gli avversari hanno vantaggio finché qualcuno non spende un'azione per riaccendere una luce."], ["Il luogo rifiuta", "Il luogo respinge la magia: fino alla fine della scena i Tiri Incantesimo hanno svantaggio. Chi vuole lanciare comunque senza svantaggio deve lasciare un'offerta di sangue e marcare un PF."], ["Testimoni", "Qualcuno ha visto il PG usare la magia, e qui la magia fa paura: un bambino scappa urlando, una donna fa il segno contro il malocchio. Rincorrerli e parlare costa tempo; lasciarli andare significa che entro sera lo sapranno tutti."], ["Macchia nera", "Dove la magia ha toccato terra si allarga una chiazza di gelo nero, e qualcosa la sente. Spendete una Paura: un avversario attirato dall'Umbra compare entro distanza Lontana. I PG possono distruggere la chiazza perdendo tempo, o allontanarsi in fretta."], ["Il segno", "Sulla pelle del PG compare una venatura scura che pulsa al ritmo dell'incantesimo. Non fa male, per ora. Può mostrarla a chi se ne intende e ammettere cosa ha fatto, o nasconderla e sperare che nessuno la veda."], ["Il doppio", "L'incantesimo lascia dietro di sé un riflesso del PG che non svanisce: ha la sua faccia, un'espressione diversa, e se ne va per conto suo. Inseguirlo ora significa lasciare la scena; lasciarlo andare significa che da qualche parte c'è un altro con il suo volto."]]}, "svolte": ["Il nemico più temuto si ferma, abbassa l'arma e chiama uno dei PG con il nome di suo padre.", "Il terreno crolla sotto gli avversari, non sotto i PG, e rivela una cantina piena di provviste.", "Un alleato creduto morto compare ai margini della scena, ferito ma vivo, con una notizia che cambia il piano.", "Le due parti in lotta si accorgono di avere un nemico comune, e quel nemico è appena arrivato.", "La pioggia si ferma a mezz'aria, ogni goccia sospesa, e per un respiro solo i PG possono muoversi.", "Ciò che i PG cercavano non è un oggetto: è vivo, e ha paura di loro.", "Un morto si rialza, ma invece di attaccare si mette tra i PG e i loro nemici.", "Una campana lontana suona e tutti i presenti, amici e nemici, cadono in ginocchio, tranne i PG.", "Il PNG che li ostacolava crolla e confessa di essere ricattato, e indica chi lo tiene in pugno.", "Il fuoco si alza altissimo e tra le fiamme, per un istante, compare un volto velato rivolto verso un PG.", "Dalla tasca del capo nemico cade una lettera con il sigillo di qualcuno di cui i PG si fidavano.", "Un grosso animale selvatico irrompe nella scena e sceglie da che parte stare: quella dei PG.", "Il muro alle spalle dei nemici si apre da solo, su un passaggio che nessuna mappa riporta.", "Il nemico ferito sanguina luce invece che sangue, e la luce scorre a terra verso una direzione precisa.", "Tutti i presenti sentono lo stesso pensiero, nitido come una voce, e non appartiene a nessuno di loro.", "Una folla di sconosciuti in fuga da qualcosa travolge la scena, e nel caos chi è più svelto prende ciò che vuole.", "Il bersaglio si rivela un'esca, e il vero nemico, che osservava da lontano, si tradisce per un istante.", "Le nuvole si aprono per la prima volta da settimane, e la luce del sole vero fa fuggire ogni creatura d'ombra.", "Un PG si ritrova in mano una chiave tiepida, come se qualcuno gliel'avesse appena passata.", "Un bambino esce da un nascondiglio e dice, con calma, dove sono appostate tutte le guardie.", "Il PNG più ostile scoppia a ridere, si toglie il cappuccio e si rivela un vecchio amico di un PG, sotto falso nome.", "L'arma del nemico si spezza da sola, e dentro la lama c'era un messaggio arrotolato.", "Il luogo cambia stagione in un battito, neve, poi fiori, poi foglie secche, e i nemici indietreggiano terrorizzati.", "Un rombo sotterraneo spacca la scena in due, e il capo nemico resta isolato dalla parte dei PG.", "Le ombre dei PG si staccano da terra, combattono da sole per un istante e poi tornano al loro posto.", "Uno sconosciuto salda davanti a tutti il debito che pesava su un PG, e se ne va senza spiegare.", "La trappola preparata dai nemici scatta in ritardo, proprio su di loro.", "Chi aveva tradito i PG arriva di corsa, inseguito dai suoi nuovi padroni, e implora aiuto.", "Un'eco del passato riempie il luogo, e per un istante tutti vedono cosa accadde qui molto tempo fa, compreso un dettaglio che cambia tutto.", "Il mostro si ferma davanti a un PG, lo annusa e abbassa la testa come davanti al suo padrone.", "Una raffica di vento strappa via il mantello del capo nemico e scopre un tatuaggio che un PG riconosce.", "Un messaggero arriva al galoppo: la persona che i PG cercano è qui vicino, e sta per andarsene.", "Il nemico si accorge di aver preso l'ostaggio sbagliato, e adesso quell'ostaggio vale più per i PG che per lui.", "Una Pira lontana divampa nella notte, alta come una torre, e tutti capiscono che qualcuno sta chiedendo aiuto.", "La porta chiusa a chiave si apre dall'interno, e chi l'ha aperta è sorpreso quanto i PG.", "La lettera, la mappa o il libro che i PG hanno con sé si rivela scritto a due strati, e sotto l'inchiostro affiora un secondo testo.", "Un avversario cambia lato di colpo, perché ha riconosciuto un simbolo che un PG porta addosso.", "Cala un silenzio assoluto, e per un istante ognuno sente il battito di chi gli sta vicino, compresi i nemici nascosti.", "Il tempo salta: in un battito di ciglia è passata un'ora, la scena è cambiata, e solo i PG ricordano com'era prima.", "La statua che sorvegliava il luogo apre gli occhi e indica con il dito un nemico che nessuno aveva visto."], "azioni": ["Tradire", "Proteggere", "Nascondere", "Rivelare", "Inseguire", "Corrompere", "Riparare", "Distruggere", "Liberare", "Rubare", "Barattare", "Sacrificare", "Ricordare", "Dimenticare", "Risvegliare", "Seppellire", "Sfidare", "Imprigionare", "Guarire", "Avvelenare", "Guidare", "Smarrire", "Spiare", "Riscattare", "Bruciare", "Custodire", "Contaminare", "Abbandonare", "Ereditare", "Profanare", "Benedire", "Dividere", "Unire", "Attirare", "Confessare", "Esiliare", "Scambiare", "Interrompere", "Rinnegare", "Promettere", "Spezzare", "Falsificare", "Vendicare", "Reclamare", "Ricostruire", "Cercare", "Rapire", "Scortare", "Sfamare", "Sabotare", "Smascherare", "Assediare", "Comprare", "Vendere", "Saldare", "Sigillare", "Aprire", "Evocare", "Scacciare", "Domare", "Cacciare", "Catturare", "Studiare", "Decifrare", "Contrabbandare", "Nutrire", "Consumare", "Sprecare", "Rifiutare", "Accettare", "Giudicare", "Condannare", "Perdonare", "Celebrare", "Onorare", "Deridere", "Temere", "Desiderare", "Invidiare", "Rimpiangere", "Annunciare", "Predire", "Svuotare", "Riempire", "Spegnere", "Accendere", "Alimentare", "Usurpare", "Rovesciare", "Insegnare", "Pagare", "Negare", "Conquistare", "Perdere", "Ritrovare", "Trasformare", "Placare", "Scatenare", "Dissotterrare", "Purificare"], "temi": ["un giuramento", "la fame", "un debito", "il fuoco", "un erede", "un confine", "la fede", "un nome perduto", "il silenzio", "una reliquia", "un rancore", "un patto", "la paura", "una famiglia", "un segreto", "il raccolto", "una mappa", "la colpa", "la speranza", "un rito", "il sangue", "una prigione", "la verità", "un tesoro", "l'onore", "un ponte", "la follia", "una canzone", "il potere", "un dio velato", "la libertà", "una malattia", "un'alleanza", "la morte", "un'eredità", "il tempo", "una profezia", "la luce", "un simbolo", "una corona", "un rifugio", "l'acqua", "la cenere", "un ricordo d'infanzia", "una lettera", "un cadavere", "un bambino", "un mostro", "un amore proibito", "una ferita", "un'arma antica", "un volto", "una maschera", "una chiave", "un libro proibito", "un sogno", "una tomba", "una taglia", "un prigioniero", "un testimone", "una casata", "una bandiera", "un sigillo", "un rivale", "un villaggio", "una strada", "una carovana", "un pozzo", "il passato", "una tregua", "una legge", "un ostaggio", "una dote", "un matrimonio", "un funerale", "un dono", "un fuoco sacro", "una statua", "una biblioteca", "un ritratto", "una lanterna", "un'ombra", "un morto che torna", "la tempesta", "un seme", "una fonte", "un duello", "una scommessa", "un titolo", "un tributo", "una voce", "una spada spezzata", "un fratello", "una madre", "un maestro", "un'amicizia", "una bugia", "un esercito", "una ribellione", "una cura"], "partenze": {"Città": ["Il campanile della piazza vi crolla accanto e la folla in fuga vi travolge. Sotto le macerie una mano stringe ancora una borsa che tintinna d'oro, e tre tagliaborse ci stanno già correndo incontro.", "Siete sul tetto di una conceria, inseguiti dalle guardie per un furto che non avete commesso. Davanti c'è un salto di quattro metri sul tetto vicino; dietro, le prime mani si aggrappano al cornicione.", "Un toro scappato dal macello carica lungo la via del mercato, rovesciando bancarelle. In mezzo alla strada una vecchia sorda conta le uova nel cesto, voltata di spalle.", "Alla porta della città, il sergente confronta il manifesto di una taglia con la faccia di uno di voi: è identica. Ha già la mano sull'elsa, e dietro di lui la fila comincia a raccogliere pietre.", "Un uomo vi getta tra le braccia un neonato avvolto in un mantello e si butta nel canale. Un attimo dopo quattro sicari con lo stesso tatuaggio sbucano dal vicolo e fissano il fagotto.", "Siete a un'asta clandestina quando la cassa sul palco si apre dall'interno. Il banditore urla di sbarrare le porte, e le sbarrano: con voi dentro.", "Il ponte delle botteghe cede sotto il peso della folla, trave dopo trave. Da una parte la gente urla aggrappata ai parapetti; dall'altra il carro delle medicine dell'ospizio scivola verso il fiume.", "Il gong suona tre volte: coprifuoco, e le pattuglie hanno l'ordine di arrestare chiunque sia in strada. Siete a sei vie dalla locanda quando da una finestra qualcuno vi fa cenno di salire, in silenzio.", "Il pozzo della piazza vomita acqua nera, e con l'acqua salgono delle mani. Tutti scappano, tranne una bambina seduta sul bordo che guarda giù e ride.", "Vi svegliate in una cella della guardia con le nocche sbucciate e nessun ricordo della notte. Il secondino legge ad alta voce le vostre accuse, e la quinta è omicidio."], "Strada e natura": ["La frana vi sorprende a metà del sentiero di cresta. Il mulo con tutte le provviste scivola verso il burrone, trascinato dalla corda legata alla cintura di uno di voi.", "Un orso con una freccia nel fianco sbuca dal sottobosco a distanza Ravvicinata. Dietro, i cacciatori a cavallo vi gridano di levarvi di mezzo, oppure di abbatterlo e dividere la taglia.", "Il guado è diventato un torrente in piena e sull'altra riva un carro di profughi ha perso una ruota. L'acqua sale a vista d'occhio e un bambino è rimasto sul cassone.", "Il bosco brucia sopravento e il fumo vi è già addosso. L'unica radura sicura è occupata da un branco di lupi che ha avuto la vostra stessa idea.", "I briganti hanno abbattuto un albero di traverso sulla strada e chiedono un pedaggio. Il pedaggio è uno di voi, a vostra scelta: giurano che lo restituiranno, prima o poi.", "Un dardo si pianta nel tronco a un palmo dalla vostra testa. Legato all'asta c'è un biglietto: «La prossima no. Lasciate sulla pietra la cosa più preziosa che avete e andatevene.»", "A metà del lago ghiacciato il ghiaccio scricchiola. Sotto, qualcosa di scuro segue le vostre ombre e batte un colpo, poi un altro, sempre più vicino alla riva che volete raggiungere.", "Una mandria di cavalli impazziti scende la valle dritta verso il bivacco. In testa galoppa un cavallo sellato, con un cavaliere morto legato sulla schiena e una lettera tra i denti.", "Un nugolo di vespe grandi come pugni esce ronzando dalla carcassa di un cervo proprio mentre ci passate accanto. A cento passi c'è uno stagno; a dieci passi c'è un vecchio pastore che non riesce più a correre.", "Vi svegliate al bivacco e la sentinella non c'è. I suoi stivali sono accanto al fuoco, pieni di terra umida, e dal bosco arriva la sua voce che vi chiama: calma, troppo calma."], "Rovine e sotterranei": ["La lastra su cui state si inclina e tutta la sala comincia a scivolare verso un pozzo senza fondo. Le statue lungo le pareti girano la testa, una dopo l'altra, per guardarvi cadere.", "Avete l'idolo in mano e il piedistallo vuoto comincia a ticchettare. Dal corridoio arrivano passi di metallo, sempre più rapidi.", "L'unica uscita della cripta si chiude con un tonfo e dal soffitto comincia a colare sabbia. I graffi lasciati da chi c'era prima arrivano fino all'altezza di un uomo.", "Dei saccheggiatori vi puntano le balestre dall'alto della scalinata. «Ci servono sei braccia per sollevare la lapide», dice il capo. «O sei cadaveri in meno nel conto.»", "Il cunicolo è così stretto che si avanza strisciando, e chi è in testa resta incastrato. Alle vostre spalle, nel buio, qualcosa raschia la pietra e si avvicina.", "Aprite il sarcofago e dentro c'è una ragazza viva, legata e imbavagliata, che vi supplica con gli occhi. All'interno del coperchio qualcuno ha inciso di fresco: «Non liberatela. Per nessuna ragione.»", "L'acqua del canale sotterraneo vi arriva al petto e l'ultima torcia sfrigola. Controcorrente, verso di voi, galleggiano decine di candele votive accese.", "Il ponte di corda sopra la voragine si spezza alle vostre spalle. A metà passerella, davanti, un ragno grosso come un carro riavvolge i fili per tirarvi a sé.", "Un crollo vi divide: metà del gruppo da una parte del muro di detriti, metà dall'altra. Vi sentite attraverso le pietre, e da entrambi i lati qualcosa si sta avvicinando.", "Trovate un'altra squadra di esploratori seduta in cerchio attorno a un fuoco spento, immobile. Quando entrate si voltano tutti insieme, e uno dice: «Finalmente. Adesso tocca a voi.»"], "Ombra e Umbra": ["A mezzanotte la Pira del villaggio si spegne di colpo, con tutti dentro il cerchio. Nel buio decine di passi si fermano sul bordo delle pietre annerite, e l'unica torcia accesa ce l'avete voi.", "La tempesta d'Umbra vi raggiunge in campo aperto: il cielo diventa viola e il vento vi chiama per nome. A distanza Lontana c'è un fienile; a distanza Ravvicinata un uomo in ginocchio risponde alle voci e si alza per seguirle.", "Un morto della Piaga torna a casa mentre la famiglia è a tavola. Si siede al suo posto, prende il cucchiaio e chiede perché nessuno gli ha tenuto la zuppa calda; la moglie guarda voi, in attesa che qualcuno decida.", "La guida che vi accompagna da giorni si sveglia con gli occhi neri e un coltello in mano. Non vi attacca: indica la porta e sussurra «Sono già qui».", "Le ombre di tutti i presenti si staccano dai muri e corrono verso la stessa porta. Le vostre no: sono rimaste ferme, e vi tirano nella direzione opposta.", "Dal fiume si alza una nebbia viola che inghiotte il sentiero. Dentro oscilla una lanterna, e chi la porta ha la voce di qualcuno che avete seppellito, e vi prega di fare in fretta.", "Un Custode della Pira corre verso di voi con un braciere fumante tra le braccia, inseguito da una cosa fatta di fumo e denti. Inciampa, e il braciere rotola ai vostri piedi.", "Una processione di morti ritornati attraversa la strada in silenzio, diretta al vecchio cimitero. Uno di loro si ferma, vi riconosce e vi fa cenno di seguirlo prima che la fila si chiuda.", "Le campane dei templi suonano da sole, e a ogni rintocco una lanterna della via si spegne. Tra voi e il rifugio ne restano sette accese.", "Al risveglio le vostre ombre sono sparite e attorno a voi l'erba è grigia, morta, in un cerchio perfetto. Sul bordo qualcuno ha lasciato un fuoco acceso e un biglietto: «Correte verso est. Non voltatevi.»"], "Fiumi e acque": ["La chiatta urta qualcosa sott'acqua e comincia a imbarcare. Il barcaiolo si tuffa e nuota via, gridandovi di non toccare per nessun motivo le casse.", "Un'onda di piena scende dalle montagne con un ruggito. Avete il tempo di correre all'argine o di slegare i cavalli dal pontile, non tutte e due le cose.", "Dalla nebbia del lago arriva una barca senza remi, carica di lumini e di un passeggero incappucciato. Accosta, la cappa si affloscia, e sotto non c'è nessuno: solo una mappa bagnata e una moneta per ciascuno di voi.", "I pirati di fiume agganciano la barca con i rampini e saltano a bordo cantando. Il vostro capitano, invece di difendersi, apre il forziere della paga: «Comprate le vostre vite, se volete. Io compro la mia.»", "Siete sulla diga di legno quando la prima trave salta via come un chiodo. A valle dorme un villaggio intero, e la leva delle chiuse è già mezza sommersa.", "Un pescatore tira su la rete e dentro c'è un annegato che apre gli occhi e vi afferra il polso. «Non lasciate che mi ributtino giù», dice, mentre i pescatori alzano i remi.", "Le passerelle del porto prendono fuoco e le fiamme corrono verso la nave carica di polvere nera. Legati all'albero maestro ci sono due marinai, e nessuno sembra voler andare a slegarli.", "A metà del guado l'acqua si fa calda e torbida. Qualcosa di lungo e lento vi passa tra le gambe, e attorno a voi il guado comincia a girare in un gorgo.", "Di notte la barca resta incagliata tra le canne della palude, la pertica piantata nel fango. Da ogni direzione arriva il rumore di qualcosa che scivola in acqua, uno dopo l'altro.", "Siete dentro il condotto dell'acquedotto, al buio, a cercare chi l'ha chiuso. Alle vostre spalle si sente il cigolio della paratia che si riapre, e il rombo dell'acqua che arriva."], "Corte e potenti": ["Al banchetto l'assaggiatore del duca crolla con la schiuma alla bocca dopo aver toccato il vostro piatto. Tutta la sala si volta verso di voi, e le guardie aspettano solo un cenno.", "Il sovrano vi concede udienza e a metà frase si irrigidisce, cade dal trono e non si rialza. Nella sala del trono siete gli unici ad avere ancora le armi.", "Durante il ballo una dama vi trascina dietro una tenda e vi chiude una chiave nel pugno: «Se mi prendono, aprite lo studio di mio marito prima di mezzanotte.» Due guardie vengono dritte verso la tenda.", "Il consiglio vota la vostra espulsione dalla città e finisce in pareggio. Il consigliere che deve decidere vi guarda e fa capire che si può trattare: adesso, prima che il martello cada.", "Siete in ginocchio davanti al principe, accusati di furto. Il vero ladro sta in piedi accanto al trono e vi sorride; il principe vi concede una frase sola per difendervi.", "Al torneo il cavallo del campione si imbizzarrisce e carica la tribuna dei figli dei nobili. La lancia spezzata vola, roteando, verso il palco d'onore.", "La regina madre vi convoca di notte e vi spinge in mano una borsa d'oro: dovete portare il nipote fuori dal palazzo, vestito da sguattero. Fuori dalla porta si sentono già gli stivali dei congiurati.", "Assistete per cortesia a un processo, quando l'imputata si alza, vi indica e grida che siete i suoi complici. Il giudice batte il martello: «Che si processino anche loro, subito.»", "Un incendio parte dalle cucine del palazzo e la nobiltà fugge dalle porte principali. Dalla torre, un prigioniero urla che la sua cella è chiusa, e la chiave pende dalla cintura del carceriere svenuto ai vostri piedi.", "Il duca vi offre la mano della figlia e un titolo per un servizio da nulla: uccidere suo fratello, che sta entrando ora dalla porta in fondo alla sala. Avete il tempo di un brindisi."], "Carovana e accampamento": ["Il carro di testa si rovescia nel fango e la carovana si blocca in fondo a una gola. Dalle rocce sopra di voi rotola giù la prima pietra, e non è un caso.", "Di notte i cani del campo guaiscono tutti insieme. Nella luce del fuoco una sentinella torna barcollando, con una freccia nel collo e una lanterna verde in mano.", "Una bestia da soma impazzisce ed esce dal cerchio dei carri trascinando il carro dell'acqua. Senza quei barili la carovana non arriva al pozzo successivo.", "Il capocarovana vi sveglia: un bambino è sparito dal carro dei profughi e le sue impronte vanno verso la palude. All'alba si riparte, con o senza di lui.", "I predoni circondano la carovana e propongono un patto: tutti liberi in cambio di un solo carro. Il mercante, senza esitare, indica quello dove dormono le famiglie.", "Il fuoco del bivacco si alza di colpo, verde, e ne esce un serpente di braci che si avvolge attorno al carro delle provviste. Il carro è pieno di botti d'olio.", "Il viaggiatore che si era unito ieri alla carovana viene trovato con la gola tagliata, e il coltello è nella vostra tenda. Gli altri si stanno già radunando, torce in mano.", "In mezzo alla piana di sale si alza il vento, e all'orizzonte una colonna di polvere avanza più veloce dei cavalli. La guida, pallida, ammette di non sapere dove sia il riparo più vicino.", "Il ponte di barche viene tagliato a metà mentre la carovana lo attraversa, con tre carri ancora sopra. Sulla riva opposta uomini armati aspettano di vedere chi arriva a nuoto.", "Il mercante, ubriaco, sfida uno di voi a duello per un insulto mai detto, e tutto il campo fa cerchio. Con la coda dell'occhio vedete un'ombra che si avvicina alla cassa della paga rimasta incustodita."], "Festa e rito": ["Al culmine della festa del raccolto, il fantoccio di paglia sul rogo comincia a urlare con voce umana. La folla applaude: crede che faccia parte dello spettacolo.", "Alle nozze la sposa solleva il velo e sotto c'è un'altra donna, che punta una balestra allo sposo e chiede a tutti di restare fermi. Lo sposo, stranamente, sorride.", "Durante la danza delle maschere un ballerino vi stringe la mano e vi lascia un anello insanguinato. Poi crolla a terra, e le altre maschere continuano a ballargli intorno.", "Il rito di accensione della nuova Pira fallisce: la scintilla non prende. Il sacerdote, pallido, chiede chi è disposto a portare il fuoco vecchio dall'altra parte della valle prima che faccia buio.", "L'albero della cuccagna crolla in mezzo alla piazza e libera i maiali da premio, il toro della lotteria e l'orso del serraglio. La banda continua a suonare.", "La gara di bevute è finita: il campione del paese si alza, sputa una manciata di monete d'oro antiche e crolla. Tutti guardano il boccale che avete appena svuotato.", "Durante la processione delle reliquie i portatori si addormentano di colpo, uno dopo l'altro. La teca sta per rovesciarsi nel canale e la folla dietro spinge per toccarla.", "Il fuoco d'artificio finale parte di traverso e centra il padiglione degli ospiti d'onore. Nel fumo, qualcuno approfitta della confusione per portare via di peso il festeggiato.", "Nella notte dei lumi il paese spegne ogni luce per un minuto di silenzio in onore dei morti. Quando le riaccendono, in piazza ci sono tre persone in più, e nessuno sa chi siano.", "Per tradizione i forestieri d'onore della fiera devono scendere nel pozzo e riportare su la corona di ferro prima che si consumi la candela. Mentre vi calano, vi accorgete che la corda è stata tagliata e riannodata in fretta."]}, "dicerie4": [{"testo": "Il fabbro del borgo lavora di notte, e le spade che escono dalla sua bottega non portano mai il suo marchio.", "verita": "mezza", "dietro": "Lavora di notte, ma non forgia: ripara e rimarchia armi rubate per una banda di predoni che gli tiene in ostaggio il figlio."}, {"testo": "Nel lago ghiacciato c'è una nave intera, intrappolata sotto la superficie con tutto l'equipaggio.", "verita": "vera", "dietro": "La nave è carica di sale e l'equipaggio è ancora a bordo, conservato dal gelo. Al primo disgelo i marinai torneranno, e vorranno il loro carico."}, {"testo": "Il vecchio barone ha sepolto il suo tesoro sotto la tomba del suo cane.", "verita": "falsa", "dietro": "Sotto la tomba c'è solo il cane. Il barone ha messo in giro la voce per far scavare i parenti nel posto sbagliato; il tesoro è murato nella cella campanaria."}, {"testo": "Chi beve alla fonte delle tre pietre dimentica il nome di chi ama.", "verita": "mezza", "dietro": "Un fiore pallido cresciuto nella polla fa dimenticare, ma solo per una notte. Qualcuno ne vende l'acqua a chi vuole far saltare un matrimonio combinato."}, {"testo": "Le guardie hanno l'ordine di non entrare più nel quartiere dei conciatori, qualunque cosa succeda.", "verita": "vera", "dietro": "Il capitano ha un accordo: i conciatori tengono fuori i ladri, lui tiene fuori le guardie. Da una settimana però nel quartiere sparisce gente, e i conciatori non riescono a fermarlo."}, {"testo": "Un lupo bianco grande come un cavallo segue le carovane senza mai attaccarle.", "verita": "vera", "dietro": "Il lupo tiene lontano dalla strada qualcosa di peggio che vive nella forra. Sulla sua testa c'è una taglia, e chi la riscuote lascia la strada senza difesa."}, {"testo": "La figlia del mugnaio parla con i corvi, e i corvi le rispondono.", "verita": "mezza", "dietro": "Non ci parla: li ha addestrati a portare messaggi a un amante chiuso nelle prigioni del castello, e i corvi tornano con le risposte."}, {"testo": "Qualcuno sta comprando tutti i cani da guardia della valle, a qualunque prezzo.", "verita": "vera", "dietro": "Una banda di ladri compra i cani delle case che vuole svaligiare, una alla volta. L'ultima coppia di mastini comprata veniva dalla villa del giudice."}, {"testo": "Il pozzo della piazza non ha fondo: un uomo ci è caduto vent'anni fa e la sua voce si sente ancora.", "verita": "falsa", "dietro": "Il pozzo ha un fondo a trenta metri e una galleria laterale. La voce è di un contrabbandiere che ci tiene la merce e alimenta la leggenda per tenere lontani i curiosi."}, {"testo": "Il nuovo sacerdote recita le preghiere a memoria, e ogni tanto sbaglia le parole.", "verita": "vera", "dietro": "Non è un sacerdote ma un disertore che ha preso la tonaca da un morto lungo la strada. Il corpo del vero sacerdote è appena stato ritrovato in un fosso."}, {"testo": "Le monete nuove della zecca contengono più piombo che argento.", "verita": "vera", "dietro": "Il maestro di zecca ruba l'argento per pagare debiti di gioco, e ha già pronto il colpevole: il suo apprendista, che non sa niente."}, {"testo": "Nel bosco a nord vive una strega che si mangia i bambini.", "verita": "falsa", "dietro": "Ci vive un'erborista che nasconde i bambini fuggiti da un orfanotrofio che li manda a lavorare in miniera. La voce l'ha messa in giro il direttore."}, {"testo": "Tre notti fa una stella è caduta oltre le colline, e da allora le mucche danno latte nero.", "verita": "mezza", "dietro": "Non era una stella ma un grumo d'Umbra solidificata. Il latte nero viene solo dalle mucche che pascolano vicino al cratere, e chi lo beve sogna luoghi in cui non è mai stato."}, {"testo": "Il conte paga in oro chi gli porta la testa di un morto della Piaga, purché intera.", "verita": "vera", "dietro": "Le teste finiscono nella cantina di un alchimista che cerca il modo di far tornare i morti a comando. Gli manca poco, e gli serve una testa speciale."}, {"testo": "Chi dorme alla locanda del Gallo si sveglia con un dente in meno.", "verita": "vera", "dietro": "Il figlio dell'oste mette un sonnifero nel vino della casa e vende i denti a una fattucchiera del mercato, che ci fa amuleti contro la Piaga."}, {"testo": "Le Sacre Pire le hanno accese gli dèi in persona, l'ultimo giorno prima di velarsi.", "verita": "falsa", "dietro": "Le prime Pire le hanno accese dei mortali. Una cronaca sepolta in un archivio dell'Ateneo racconta con che cosa le hanno alimentate, e non era legna."}, {"testo": "Il ponte di pietra sul fiume l'ha costruito un demone in una notte, in cambio della prima anima che l'avrebbe attraversato.", "verita": "mezza", "dietro": "L'ha costruito in un mese una gilda che poi ha fatto sparire gli operai per non pagarli. I loro nomi sono incisi sotto la terza arcata, e chi li legge ad alta voce sente qualcuno rispondere."}, {"testo": "C'è una taglia altissima su un ladro che ruba soltanto campane.", "verita": "vera", "dietro": "Il ladro fonde le campane in un'unica campana enorme: crede che il suo suono possa respingere la tempesta d'Umbra. In parte ha ragione, e gli manca il bronzo dell'ultima."}, {"testo": "Il mercante di spezie ha comprato la torre in rovina a sud e ci ha fatto portare trenta casse, di notte.", "verita": "vera", "dietro": "Nelle casse ci sono armi e uniformi della milizia: il mercante finanzia un colpo di mano contro il consiglio, fissato per la prossima luna nuova."}, {"testo": "Il gigante della montagna è morto, e la sua grotta è piena di oro incustodito.", "verita": "mezza", "dietro": "Il gigante è morto davvero, ma nella grotta sono rimasti i suoi figli: piccoli per dei giganti, grossi come orsi per tutti gli altri, affamati e senza nessuno che insegni loro le buone maniere."}, {"testo": "Un viaggiatore ha visto un villaggio intero camminare di notte verso il mare, in fila, a occhi chiusi.", "verita": "vera", "dietro": "Una cantilena portata dal vento li chiama verso la scogliera. Ogni notte arrivano un po' più vicini al bordo, e la terza notte ci arriveranno."}, {"testo": "Il capo della milizia è morto un mese fa, e suo fratello gemello ha preso il suo posto senza dirlo a nessuno.", "verita": "falsa", "dietro": "Il capo è vivo e vegeto. È morto il gemello, ucciso da lui in una lite, e la voce l'ha messa in giro lui stesso per confondere le acque."}, {"testo": "In fondo alla miniera chiusa canta una ragazza, sempre la stessa canzone.", "verita": "vera", "dietro": "È una minatrice intrappolata in una sacca d'aria da settimane, nutrita da un fungo luminoso che le sta cambiando la pelle. Canta per farsi trovare."}, {"testo": "Gli elfi hanno chiuso i sentieri del bosco: chi entra, esce vecchio.", "verita": "mezza", "dietro": "I sentieri sono chiusi per una malattia che divora gli alberi dall'interno. Chi entra non invecchia: esce con i capelli bianchi per lo spavento di ciò che ha visto nutrirsi dei tronchi."}, {"testo": "Il borgomastro ha venduto il villaggio a un signore della guerra, con un contratto firmato col sangue.", "verita": "mezza", "dietro": "Ha venduto il raccolto del prossimo anno, non il villaggio, per comprare armi contro i predoni. Il contratto è firmato con l'inchiostro, ma la penale in fondo prevede ostaggi."}, {"testo": "Nelle notti senza luna i ritratti della villa abbandonata cambiano espressione.", "verita": "falsa", "dietro": "Una banda di ragazzini ritocca i quadri di nascosto per spaventare gli adulti e tenersi il nascondiglio: sotto la villa hanno trovato una cantina piena di vino antico e di una cosa che non osano toccare."}, {"testo": "Un Senzaporta vende mappe che portano sempre a qualcosa, ma mai a quello che cerchi.", "verita": "vera", "dietro": "Le mappe sono pezzi di un'unica mappa disegnata da un cartografo morto: chi ne riunisce quattro trova il quinto pezzo, e il nomade ne ha già vendute tre a tre persone diverse."}, {"testo": "L'ape regina dell'alveare del convento è grande come un gatto.", "verita": "vera", "dietro": "Le suore la nutrono con miele benedetto e cera di candele votive. Il suo miele chiude le ferite, ma lo sciame sta diventando aggressivo e una novizia è già morta."}, {"testo": "I morti di questo villaggio non tornano mai, perché il becchino ha un segreto.", "verita": "vera", "dietro": "Il becchino seppellisce ogni morto con un chiodo di ferro antico sotto la lingua. I chiodi stanno finendo, e sa dove ce ne sono altri: in una cripta che non osa aprire."}, {"testo": "La duchessa non esce più dal palazzo perché aspetta un figlio dal capitano delle guardie.", "verita": "falsa", "dietro": "La duchessa è morta da settimane. Il capitano e il cancelliere nascondono la notizia finché non avranno deciso chi dei due prenderà il potere."}, {"testo": "Un orologiaio ha costruito un uomo d'ottone che lavora al posto suo.", "verita": "mezza", "dietro": "Il costrutto esiste ma non funziona: dentro c'è il fratello minore dell'orologiaio, che si finge macchina per sfuggire all'arruolamento forzato."}, {"testo": "Ogni notte il lago sale di un palmo, e i vecchi dicono che vuole riprendersi il paese.", "verita": "vera", "dietro": "Qualcuno ha chiuso di nascosto la vecchia chiusa a valle per allagare i campi e ricomprarli per niente. Tra un mese l'acqua arriverà alle prime case."}, {"testo": "Solo il giullare del signore sa dove è nascosto l'erede legittimo.", "verita": "vera", "dietro": "L'erede è il giullare stesso, sfregiato da bambino perché nessuno lo riconoscesse. Lo sa soltanto la vecchia balia, ormai cieca."}, {"testo": "Le rondini sono tornate con due mesi di anticipo: è il segno che la fine è vicina.", "verita": "falsa", "dietro": "Le rondini fuggono da un incendio a sud che nessuno ha ancora notato. Un'intera foresta brucia, e il vento sta girando verso il paese."}, {"testo": "Al mercato vendono un unguento che rende invisibili per un'ora.", "verita": "mezza", "dietro": "Non rende invisibili: per un'ora chi lo usa non resta nella memoria di nessuno. I ladri lo comprano tutto, e il venditore lo prepara col grasso dei morti della Piaga."}, {"testo": "Il drago che bruciò la valle cent'anni fa è tornato: si vede il fumo sulla montagna.", "verita": "falsa", "dietro": "Il fumo viene da una forgia nascosta di nani rinnegati, che fondono armi per chi paga e tengono viva la leggenda per scoraggiare i curiosi."}, {"testo": "Un cavaliere senza testa sfida a duello chiunque passi il guado di notte.", "verita": "mezza", "dietro": "La testa ce l'ha, infilata in un elmo troppo grande. Ha giurato di difendere il guado finché il suo signore non torna, e il suo signore è morto da trent'anni: nessuno ha avuto il coraggio di dirglielo."}, {"testo": "Le campane del convento suonano da sole, e ogni volta muore qualcuno in paese.", "verita": "mezza", "dietro": "Le suona la badessa quando il becchino le annuncia un decesso. La gente ha confuso causa ed effetto, e qualcuno sta già raccogliendo torce per bruciare il convento."}, {"testo": "Il sale di questa miniera conserva le cose per sempre, anche le persone.", "verita": "vera", "dietro": "In fondo alla miniera c'è una sala con trenta minatori conservati nel sale, in piedi. Uno di loro stringe ancora la mappa di una vena d'argento mai sfruttata."}, {"testo": "Il figlio del giudice ha ucciso un uomo, e il giudice ha fatto impiccare un vagabondo al posto suo.", "verita": "vera", "dietro": "Il vagabondo impiccato era un Senzaporta. La sua carovana è accampata a due miglia dal paese e aspetta solo una prova per farsi giustizia da sé."}, {"testo": "Chi riesce a toccare la statua velata del tempio senza farsi vedere dalla guardiana ottiene un desiderio.", "verita": "falsa", "dietro": "La statua è cosparsa di una polvere che brilla al buio. La guardiana alimenta la leggenda per marchiare le dita dei ladri e sapere chi tenere d'occhio."}, {"testo": "Ogni volta che piove rosso, qualcuno in paese si sveglia parlando una lingua sconosciuta.", "verita": "vera", "dietro": "È la lingua di un popolo scomparso, e chi la parla ripete sempre la stessa frase: le indicazioni per una porta sotto il municipio."}, {"testo": "La compagnia di mercenari al soldo della città sta per cambiare bandiera.", "verita": "vera", "dietro": "Il nemico ha offerto il doppio, e il capitano accetterà alla prima paga mancata. Il tesoriere ha già speso i soldi della paga di questo mese."}, {"testo": "Il mendicante cieco del porto riconosce chiunque dal passo, anche a distanza di anni.", "verita": "mezza", "dietro": "Non è cieco: era una spia dell'Ateneo rimasta senza padrone, e vende quello che ricorda a chi paga meglio. Sa già chi siete."}, {"testo": "Hanno trovato una bambina nella neve che non sente il freddo e non mangia.", "verita": "mezza", "dietro": "Mangia, ma solo cenere. È una piccola creatura del fuoco fuggita da una Pira, e si sta spegnendo: deve tornare là da dove è venuta."}, {"testo": "Il tesoro della gilda dei mercanti è sorvegliato da un serpente che non dorme mai.", "verita": "falsa", "dietro": "Il serpente è morto da anni ed è imbalsamato: la gilda lo sposta ogni notte per far credere che sia vivo. La vera guardia è un vecchio con la balestra e la vista corta."}, {"testo": "Nessuno vede più il vescovo da quando è salito alla torre dell'osservatorio.", "verita": "vera", "dietro": "Il vescovo ha visto qualcosa nel cielo e si è murato dentro per fare i conti. Secondo i suoi calcoli mancano nove giorni, ma non dice a cosa."}, {"testo": "I lupi della valle hanno imparato ad aprire le porte.", "verita": "mezza", "dietro": "Le porte le apre un ragazzo cresciuto con il branco, che lo guida contro le fattorie della famiglia che l'ha abbandonato nel bosco."}, {"testo": "Le prigioni del castello sono vuote: hanno liberato tutti in segreto.", "verita": "mezza", "dietro": "Nessuno è stato liberato: i prigionieri sono stati venduti come rematori a un capitano di fiume, e tra loro c'è un innocente con amici molto potenti."}, {"testo": "Un poeta ha scritto una ballata che fa piangere chiunque, e il signore l'ha proibita.", "verita": "vera", "dietro": "Nei versi sono cifrati i nomi dei consiglieri che hanno tradito il vecchio signore. Il poeta è sparito, e chi conosce la canzone a memoria è in pericolo."}, {"testo": "In una cappella sul passo si conserva un'ampolla con le lacrime di un dio velato.", "verita": "falsa", "dietro": "Nell'ampolla c'è acqua di neve e un pizzico di sale. Il frate lo sa, e la vende a gocce ai pellegrini per comprare medicine al villaggio: se la verità viene fuori, il villaggio resta senza."}, {"testo": "Un Toccato dall'Umbra vive tra i cani randagi del porto, e i cani non lo mordono mai.", "verita": "vera", "dietro": "Sente arrivare le tempeste e lo annuncia ululando con il branco: chi ha imparato a capirlo si salva. Un mercante lo vuole in gabbia per vendere le sue previsioni."}, {"testo": "Le pietre del cerchio sulla collina sono tredici di giorno e quattordici di notte.", "verita": "vera", "dietro": "La quattordicesima è una creatura di pietra che viene a dormire nel cerchio. Da un mese all'alba non se ne va più, e si sta avvicinando alla strada."}, {"testo": "Chi trova la moneta bucata del barcaiolo può farsi traghettare nel regno dei morti.", "verita": "mezza", "dietro": "Il barcaiolo è un vecchio contrabbandiere che porta oltre il confine chi deve sparire. Il suo regno dei morti è una valle dove vivono tranquilli molti che il mondo crede sepolti."}, {"testo": "La gilda dei ladri ha giurato vendetta contro chi ha derubato il suo capo.", "verita": "vera", "dietro": "Al capo hanno rubato il registro con i nomi di tutti i membri. Chi lo trova può ricattare mezzo quartiere, o essere ucciso entro un'ora."}, {"testo": "Un orso che parla gestisce la stazione di posta sul passo.", "verita": "falsa", "dietro": "È un omone gentile, peloso e dalla voce cavernosa, che si diverte a lasciarlo credere. Sa chi ha attraversato il passo nell'ultimo mese, e lo dice solo a chi lo fa ridere."}, {"testo": "Hanno impiccato tre volte lo stesso uomo, e tre volte la corda si è spezzata.", "verita": "vera", "dietro": "Il boia è suo fratello e incide la corda ogni volta. La quarta esecuzione è domani, con un boia nuovo arrivato dalla capitale."}, {"testo": "La fontana del chiostro guarisce chi ci immerge le mani all'alba.", "verita": "mezza", "dietro": "L'acqua non guarisce: scorre su un minerale che addormenta il dolore. Un erborista la imbottiglia e la vende, e chi ne beve troppa non si sveglia più."}, {"testo": "Il pozzo dei desideri è pieno di monete fino all'orlo, e nessuno osa prenderle.", "verita": "vera", "dietro": "Chi ci ha provato è stato trovato annegato in un catino. Non è una maledizione: le monete sono la cassa segreta di una famiglia, e il loro sicario fa sembrare ogni morte un castigo."}, {"testo": "Un mago dell'Ateneo ha venduto l'anima per sapere quando finirà il mondo.", "verita": "falsa", "dietro": "Ha solo fatto i conti, e i conti dicono che il mondo non finirà. La cosa preoccupa chi ha costruito il proprio potere sulla paura della fine, e lo stanno cercando."}], "dicerie_mondo": ["Si dice che qualcuno abbia visto {A} uscire dal luogo «{L}» prima dell'alba, con le mani sporche di cenere.", "Gira voce che la fazione «{F}» paghi in oro chiunque riesca a seguire {A} per una notte intera senza farsi scoprire.", "Qualcuno giura che tra {A} e {B} ci sia un vecchio conto in sospeso, e che stavolta si chiuderà col sangue.", "Al mercato raccontano che chi dorme nel luogo «{L}» si svegli gridando sempre lo stesso nome: {A}.", "Si dice che la fazione «{F}» stia cercando un modo per entrare nel luogo «{L}» senza farsi vedere, e che abbia già comprato una guida.", "Un ubriaco giura di aver visto {A} e {B} brindare insieme come vecchi amici, la notte in cui la Pira si è abbassata.", "Qualcuno sussurra che la fazione «{F}» tenga un elenco di nomi da far sparire, e che in cima ci sia scritto: {A}.", "Gira voce che {A} e {B} abbiano diviso qualcosa trovato nel luogo «{L}», e che da allora non si rivolgano più la parola.", "Si dice che chiunque abbia osato contraddire {A} in pubblico, entro una settimana, abbia perso la casa o il lavoro.", "Al pozzo raccontano che la fazione «{F}» abbia comprato il silenzio delle guardie che sorvegliano il luogo «{L}».", "Qualcuno giura che nel luogo «{L}», di notte, si senta una voce che chiama {B} e piange.", "Si dice che tra {A} e la fazione «{F}» ci sia un accordo, e che il prezzo lo stiano pagando tutti gli altri.", "Le lavandaie giurano che ultimamente con {A} giri sempre una figura incappucciata che non parla mai e non mangia.", "Si racconta che la fazione «{F}» abbia messo una taglia segreta, e che sul foglio ci sia un solo nome: {B}.", "Qualcuno sostiene che chi cerca {B} debba passare prima dal luogo «{L}», e pagare il pedaggio giusto alla persona giusta.", "Gira voce che tra la fazione «{F}» e {A} ci sia stata una lite furiosa, e che nel luogo «{L}» se ne vedano ancora i segni sui muri.", "Si dice che nessuno abbia più visto {B} da quando la fazione «{F}» ha messo piede nel luogo «{L}».", "Un vecchio giura che anni fa, nel luogo «{L}», uno sconosciuto abbia tirato fuori {B} dalle macerie, e che oggi quello sconosciuto sia tornato a riscuotere.", "Si dice che {A} e {B} abbiano giurato fedeltà davanti alla stessa Pira, e che il giuramento sia già stato rotto.", "Al mercato si scommette su chi cadrà per primo tra {A} e {B}, e a tenere il banco delle puntate è la fazione «{F}»."], "segreti": ["Il debito che lega {A} e {B} è annotato in un registro nascosto nel luogo «{L}», sotto la terza asse del pavimento.", "La fazione «{F}» tiene {A} in pugno: ha comprato in segreto ogni cambiale di gioco con quella firma, e la prossima scade alla luna nuova.", "Chi incontra {A} ogni settimana nel luogo «{L}» non è un amante ma un esattore, e il debito si paga in vite, non in monete.", "{A} e {B} hanno firmato un patto davanti a un testimone che ora vive nascosto nel luogo «{L}», e quel testimone non si fida più di nessuno.", "Una lettera sigillata, nascosta nel luogo «{L}», prova che la fazione «{F}» ha pagato chi ha appiccato l'ultimo incendio.", "La persona che si fa chiamare {A} ha rubato quel nome a un morto: la vera tomba è nel luogo «{L}», con l'iscrizione ancora leggibile.", "Il vero nome nascosto dietro {A} lo conosce una sola persona, {B}, e quel segreto vale come un'assicurazione sulla vita.", "La fazione «{F}» ha un infiltrato tra la gente che lavora con {A}: il corriere, che copia ogni messaggio in un quaderno nascosto nel luogo «{L}».", "Ogni notte di luna piena un pacco viene lasciato sulla soglia del luogo «{L}»; chi lo ritira, se pedinato, finisce sempre per incontrare {A}.", "{A} e {B} si amano da anni e lo nascondono, perché la fazione «{F}» ha giurato di spezzare quel legame con ogni mezzo.", "Il ricatto che costringe {A} a obbedire riguarda una notte nel luogo «{L}»: c'era un testimone, e il testimone ha conservato un oggetto sporco di sangue.", "La fazione «{F}» ricatta {B} con un ritratto: mostra un bambino che tutti credono morto, e quel bambino vive nascosto nel luogo «{L}».", "Sulle pareti del luogo «{L}» è incisa una profezia sull'ultima notte della fazione «{F}», e qualcuno ha appena scalpellato via le righe che spiegano come avverrà.", "Le ceneri lette da una veggente hanno detto che tra {A} e {B} tradirà chi ha più da perdere; lo sanno entrambe le parti, e ora il sospetto corre nei due sensi.", "Nel luogo «{L}» c'è un passaggio murato che porta dritto agli archivi della fazione «{F}»; la malta è fresca, e qualcuno l'ha già usato.", "Il veleno che ha ucciso l'ultimo testimone viene da un erborista che ha una sola cliente abituale: la fazione «{F}».", "Le armi sparite il mese scorso sono nascoste nel luogo «{L}», e il sigillo di cera sul lucchetto lo riconosce subito chiunque abbia lavorato con {A}.", "Le prove che indicano {A} come traditore della fazione «{F}» sono state fabbricate, e il falsario che le ha preparate lavora in una bottega vicino al luogo «{L}».", "{A} e {B} vogliono prendere il controllo della fazione «{F}» alla prossima assemblea; il segnale sarà una campana suonata dal luogo «{L}».", "La fazione «{F}» protegge in segreto {B}: chiunque alzi le mani contro quella persona sparisce entro tre giorni.", "Qualcuno paga un mendicante perché tenga d'occhio {A} giorno e notte; il mendicante fa rapporto a mezzanotte nel luogo «{L}», a una figura con la maschera.", "La lettera d'amore trovata nel luogo «{L}» non è di chi tutti credono: chi riconosce la grafia capisce subito chi l'ha scritta, ed è {B}.", "Il sigillo usato per falsificare gli ordini della fazione «{F}» è stato preso e rimesso a posto nel luogo «{L}»: le chiavi della teca le hanno solo in due, tra cui {A}.", "Tra {A} e {B} c'è un legame di sangue che nessuno conosce, e lo prova un registro delle nascite custodito nel luogo «{L}».", "Ogni moneta che entra nelle casse della fazione «{F}» passa prima da un cambiavalute del luogo «{L}», che trattiene la sua parte e annota tutto in codice.", "La guardia che sorveglia il luogo «{L}» è stata comprata con un debito di famiglia; chi lo salda al posto suo ottiene la sua fedeltà, e le sue chiavi.", "Chi ha avvelenato il pozzo ha lasciato l'impronta di uno stivale chiodato, e stivali così escono soltanto dall'armeria della fazione «{F}».", "Una profezia cucita nell'orlo di una vecchia bandiera, conservata nel luogo «{L}», nomina un erede: secondo chi l'ha decifrata, quel nome è {B}.", "La fazione «{F}» prepara un incendio per la notte della festa, e la polvere nera è già stipata nel luogo «{L}», sotto sacchi di farina.", "Anni fa qualcuno ha strappato {A} all'Umbra pagando un prezzo terribile, e ora vuole indietro il favore con gli interessi: l'appuntamento è nel luogo «{L}».", "Il morto della Piaga che vaga nel luogo «{L}» ripete sempre la stessa frase, e la frase è un'accusa che contiene un nome: {B}.", "Tra {A} e la fazione «{F}» esiste un contratto firmato, e il prezzo pattuito è il luogo «{L}», da consegnare prima della fine della stagione.", "La spia che vende informazioni sulla fazione «{F}» usa come cassetta delle lettere una nicchia nel luogo «{L}», e dentro c'è già un messaggio mai ritirato.", "Chi ha rubato la reliquia l'ha nascosta nel luogo «{L}» per incastrare {B}, e ci ha lasciato apposta un falso indizio: un bottone strappato.", "{A} e {B} si odiano in pubblico e si scrivono in privato; le lettere passano per le mani di un corriere che dorme nel luogo «{L}».", "La fazione «{F}» non vuole vincere la guerra ma farla durare, perché vende armi a tutti e due i fronti; i libri contabili sono nel luogo «{L}».", "Un vecchio bandito nascosto nel luogo «{L}» giura che ai tempi della sua banda c'era anche {A}, e conserva un ritratto che lo dimostra.", "La fazione «{F}» tiene un ostaggio nel luogo «{L}», ed è questo il filo con cui muove {B} come vuole.", "Il guaritore che cura in segreto {A} ha capito che male è, e chi conosce quel male sa anche dove si prende: nel luogo «{L}».", "Un anello spezzato a metà lega {A} e {B}: una metà è al sicuro, l'altra è andata persa nel luogo «{L}», e chi la trova ha in mano una prova.", "Le lettere che hanno messo nei guai {B} sono false: la carta viene da una cartiera che rifornisce soltanto la fazione «{F}».", "Il patto tra la fazione «{F}» e qualcosa che vive nell'Umbra ha un garante in carne e ossa, e quel garante è {A}.", "Ogni anno, il giorno dei morti, qualcuno porta fiori freschi su una tomba senza nome nel luogo «{L}»; il fioraio ricorda bene chi li compra: {B}.", "La chiave della cassaforte della fazione «{F}» è divisa in tre pezzi: uno è nascosto nel luogo «{L}», e dove siano gli altri due lo sanno solo {A} e {B}.", "La fazione «{F}» ha assoldato un sicario per la notte del mercato, e secondo il contratto il bersaglio è {A}.", "Chi protegge {B} nell'ombra non è un amico ma un creditore, che vuole quella persona viva finché il debito non sarà saldato.", "Il ponte non è crollato per caso: le travi erano state segate, e la sega ripescata nel luogo «{L}» porta il marchio di una bottega che lavora solo per la fazione «{F}».", "Il bambino che vive con {A} non è un nipote: è l'erede che la fazione «{F}» cerca da anni.", "{A} e {B} vogliono lasciare la città prima dell'inverno e, per pagarsi la fuga, hanno svuotato una cassa che non era loro; la cassa vuota è ancora nel luogo «{L}».", "Il predicatore che arringa la folla davanti al luogo «{L}» riceve ogni sermone già scritto, e la grafia è la stessa dei biglietti che si scambiano {A} e {B}."]});
